local _, GQ = ...

-- GENERATED by scripts/build-locale-quests.py. Do not edit by hand.
-- The client's own quest descriptions and objectives (Questie / QuestieDB data).
if GQ.LOCALE ~= "deDE" then
    return
end

local text = GQ.LocaleText
for k, v in pairs({
    ["\"Here you go, the power source is safely removed and the data is preserved. Well, safe journeys and all that."] = "\"Wir sind so weit, die Kraftquelle ist entfernt und die Daten sind gesichert. Also dann, sichere Reisen und all das.",
    ["- I have heard of you, newcomer. Perhaps it is you that will help us, where others have failed. We tauren have carved a home out of this land, but not without a cost."] = "<name>... Ihr seid ein Neuling, ich habe von Euch gehört. Vielleicht könnt Ihr uns ja helfen, wo andere bereits versagt haben.",
    [". A task I would ask of you. Have you seen the ruins of Ameth'Aran? If not, you will find them on the eastern side of the main road, some ways to the south."] = "<class>. Ich möchte Euch um etwas bitten. Habt Ihr die Ruinen von Ameth'Aran gesehen? Falls nicht, findet Ihr sie auf der Ostseite der Hauptstraße, ein paar Straßen weiter südlich.",
    [". The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock. Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars."] = "<name>. Die Burning Blade haben die Knochenhöhle östlich von Orgrimmar besetzt. Sie führen in dieser Höhle schlimme Rituale durch und fügen sich durch Senghalsbänder selbst Brandwunden zu.",
    ["... your timing is perfect. I just hope I can compliment your haste as well. I was careless while fighting a few of the venomtails nearby, and one of them stung me deeply."] = "<name>, Ihr hättet den Zeitpunkt nicht besser wählen können. Ich hoffe nur, dass ich Euch auch zu Eurer Eile beglückwünschen kann. Während eines Kampfes mit ein paar Siechstachelskorpiden war ich unvorsichtig und ich wurde von einem von ihnen heftig gestochen. Während wir uns unterhalten, spüre ich, wie sein Gift mich schwächt.",
    ["A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor. He would be very interested in a sample of the wolf hearts Renferrel sent me."] = "Ein Kollege in Kalimdor, Apotheker Helbrim, untersucht die Auswirkungen von Lordaerons Toxinen auf die Wildtiere von Kalimdor. Er wäre an einer Probe der Wolfherzen interessiert, die Renferrel mir geschickt hat.",
    ["A like you must get pretty hungry out here in The Barrens. Me, I'm starving all day long. Tell you what, I'll fix you up a nice stew. Just need a few dig rats."] = "Die Königliche Apothekervereinigung, die in der großen Undercity Lordaerons ansässig ist, hat mich geschickt, um eine ganz besondere Aufgabe zu erledigen, <name>. Vielleicht möchtet Ihr mich und damit auch die dunkle Fürstin bei unseren Bemühungen, die Verlassenen weiterzubringen, unterstützen. Ich studiere seit kurzem eine rare Pflanzenart namens Schlangenflaum. Ich denke, dass dieses Kraut in größeren Mengen außerordentliches Potenzial besitzt.",
    ["A mudsnout composite? Absolutely brilliant! Why didn't I think of that? Let me contribute my colloid of decay to this devilish brew."] = "Ein Morastschnauzengemisch? Das ist wirklich brillant! Warum ist mir das nicht eingefallen? Lasst mich meine Paste des Verfalls diesem Teufelsgebräu hinzufügen.",
    ["A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside. Take this vial."] = "Ein Satyr, der unter dem Namen Schlangenzunge bekannt ist, hat die Höhlen von Maraudon verderbt und so das Wachstum vieler Pflanzen im Inneren behindert. Nehmt diese Phiole, <name>.",
    ["A second encampment of satyrs threatens the land of Felwood towards the north, led by the cruel Xavaric. The vile betrayers and tricksters feed upon the corruption of the native creatures of Felwood."] = "Ein weiterer Satyrstützpunkt unter der Leitung des grausamen Xavaric bedroht den Teufelswald im Norden. Die elenden Verräter und Schwindler zehren von der Verderbnis der im Teufelswald heimischen Kreaturen.",
    ["A tauren skilled in the ways of the hunt knows that his prey is not for mere trophy. The beasts of the plains provide us with a means of survival."] = "Ein Tauren, der in der Fertigkeit des Jagens bewandert ist, weiß, dass seine Beute nicht nur eine Trophäe ist. Die Wildtiere der Ebenen versorgen uns mit allem, was wir zum Überleben brauchen.",
    ["A terrible menace has been laid to rest. The cruel Ossirian has been vanquished. The denizens of Kalimdor would be relieved to know of this victory."] = "Eine schreckliche Bedrohung hat ihr Ende gefunden. Der grausame Ossirian existiert nicht mehr. Die Bewohner Kalimdors werden aufatmen, wenn sie von diesem glorreichen Sieg erfahren.",
    ["A truly amazing story! You have my thanks, and the heartfelt gratitude of all who were involved, I can assure you. Through your efforts we are delivered from the mistakes of our past."] = "Das ist ja eine unglaubliche Geschichte, <name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.",
    ["A while ago, I had an incident with the Shadowforge Dwarves. They brought me to Angor Fortress to study two types of strange stones from Uldaman."] = "Vor einiger Zeit hatte ich einen kleinen Zwischenfall mit den Zwergen der Schattenschmiede. Sie brachten mich in die Festung Angor, um dort zwei Arten von seltsamen Steinen zu untersuchen, wie sie in Uldaman vorkommen.",
    ["According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague. Those beasts dwell on the islands in Lake Lordamere to the east."] = "Laut Berards Tagebuch könnte sich das Moos von Seeschleichern und Seekrabblern bei unserer Suche nach einer neuen Seuche als nützlich erweisen. Diese Bestien leben auf den Inseln im Lordameresee im Osten.",
    ["According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands."] = "Laut der Dokumente, die Ihr von der Karawane geborgen habt, hat die Venture Company viele Pläne parat, um zu versuchen, uns von unserem Land hier zu vertreiben und damit freie Bahn zur Plünderung des Landes zu haben. Ich bin entsetzt und es stößt mich ab, auf welches Niveau man sich herablassen kann, um seine Ziele durchzusetzen; ich will, dass der führende Kopf hinter ihren Plänen vernichtet wird.",
    ["After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache."] = "Nachdem Ihr die Karte sorgfältig studiert habt, erkennt Ihr, dass Eure Entdeckung die geheimen Pläne des Grimmhauer-Kriegshäuptlings für eine ausgedehnte Belagerung des Lagers Narache sind.",
    ["After examining this charm, I see now what must be done. Please take it, and do as I ask. You are to explore the deepest areas of the Ban'ethil Barrow Den."] = "Nachdem ich den Glücksbringer untersucht habe, weiß ich jetzt, was zu tun ist, <name>. Bitte nehmt ihn, und tut das, worum ich Euch bitte. Ihr müsst die tiefsten Tiefen des Grabhügels von Ban'ethil erforschen.",
    ["After much observation, I have discovered Morganth's plans. He searches for the Scythe of Elune...and he may have found it! If he has, then the Redridge Mountains, and the kingdom of Stormwind, will soon feel his dark might."] = "Nach langen Beobachtungen habe ich jetzt Morganths Pläne durchschaut. Er sucht nach der Sense von Elune... und vielleicht hat er sie bereits gefunden!",
    ["After pulling the barrel free from the muck and opening it, a silvery figurine is found packed in fine straw. It depicts a young, long-haired Paladin with hammer upraised."] = "Nachdem Ihr das Fass aus dem Dreck gezogen und geöffnet habt, findet Ihr eine in dünnes Stroh eingepackte, silbrige Figur. Sie stellt einen jungen, langhaarigen Paladin mit erhobenem Hammer dar.",
    ["Agmond's tracks lead from the west. It is easy to tell from the bloody smears across rock and sand that the dwarf crawled some distance."] = "Agmonds Spuren führen nach Westen. Anhand der Blutspuren auf den Felsen und im Sand ist unschwer zu erraten, dass sich der Zwerg ein ganzes Stück weit geschleppt haben muss.",
    ["Ain't nothin' that irks me more than losin' these here beautiful horses."] = "Nix macht mich wütender als wenn ich diese schönen Pferdchen verlieren tu.",
    ["All right then... if you're sure, we'll sneak out of here. Let us leave when you're ready. Remember, after you've escaped, meet Terenthis back in Auberdine."] = "Na gut... wenn Ihr sicher seid, werden wir uns hier hinausschleichen. Lasst uns verschwinden, sobald Ihr bereit seid. Vergesst nicht, Euch in Auberdine mit Terenthis zu treffen, sobald Euch die Flucht gelungen ist.",
    ["All right, force it is. Let's get out of here as soon as you're ready. We'll fight our way down to the road--Grimclaw should still be there."] = "Gut, <name>, dann sei es Gewalt. Lasst uns hier verschwinden, sobald Ihr bereit seid. Wir werden uns unseren Weg hinunter zur Straße erkämpfen - Grimmklaue dürfte immer noch dort sein.",
    ["All that remains is to deliver the Crown of Will to Sharlindra in the Undercity. She will see that it is delivered to Lady Sylvanas."] = "Mug'Thol und seine Crushridge-Oger haben die Ruinen von Alterac überrannt. Ihm eine schwere Strafe zukommen zu lassen, ohne die Anzahl der Oger zu verringern, wird nicht einfach sein.",
    ["Although I have no knowledge of this Lord Azrethoc, I agree with Maurin, he must be stopped; especially if he is attempting to gain influence over the Burning Blade to further his goals."] = "Wiewohl ich nichts über diesen Lord Azrethoc weiß, stimme ich mit Maurin überein, er muss aufgehalten werden.",
    ["Although no mention of Private Thorsen is found in these records, hidden within the binding of one of Herod's ledger books is a small, brass key."] = "In den Berichten wird kein Wort über den Gefreiten Thorsen verloren, jedoch im Einband eines von Herods Geschäftsbüchern findet sich ein kleiner Messingschlüssel.",
    ["Ambassador Infernus was sent to Angor Fortress by Ragnaros himself to mind the Shadowforge seeking lost artifacts in Uldaman. It has already meant tremendous casualties for our people, but it has obviously grown worse."] = "Ragnaros persönlich schickte den Gesandten Infernus zur Festung Angor, damit er dort die Suche der Zwerge der Schattenschmiede nach in Uldaman verschollenen Artefakten organisiert. Unser Volk hat bereits einen enormen Verlust erlitten, aber in letzter Zeit hat sich die Lage offensichtlich noch verschlimmert.",
    ["An archmage of great power is overseeing the reactivation of the ley energy node. With the progress they have made, our only hope of stopping them is by killing him."] = "Ein Erzmagier von großer Macht leitet die Reaktivierung des Leyenergieknotens. Angesichts ihres Fortschritts liegt unsere einzige Hoffnung, sie noch aufzuhalten, darin, ihn zu töten.",
    ["And again, it is your task to perform the ritual of cleansing. Go to the Thunderhorn Water Well, north of the village, and use the Thunderhorn Cleansing Totem in your ritual."] = "Das Totem ist bereit, <name>. Und wiederum ist es Eure Aufgabe, das Ritual der Säuberung durchzuführen.",
    ["Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body."] = "Anilia legt Euch die Hände auf die Schultern und zieht Euch zu sich heran. Nach Luft ringend zeigt sie in Richtung des Bogens im Norden, bevor sich ihre Augen schließen und sie einen letzten, keuchenden Atemzug ausstößt.",
    ["Anyway, you should check back with me relatively soon... that is if you want to know what was in here. As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you."] = "Tja, Ihr solltet möglichst bald wieder zu mir kommen... falls Ihr wissen wollt, was sich hier drinnen befand. Sobald ich herausfinde, was es ist, und falls es in der Tat ein Buch ist, werde ich diese Informationen gern mit Euch teilen.",
    ["Argh, 'tis a horrible life. I should be in a watery grave right now, not sittin' here by the fire, breathin' fresh air. The crew tried so hard to save my beautiful Maiden's Folly."] = "Grr, 's ist ein elendes Leben. Ich sollte in meinem nassen Grab liegen und nicht hier am Feuer sitzen und frische Luft atmen. Die Crew hat ihr Bestes gegeben um meine wunderschöne TOLLE MINNA zu retten.",
    ["Arnak thinks we're going to be married... but after I declined his offer he came back that night and kidnapped me. My brother tried to stop him, but Arnak was too strong."] = "Arnak glaubt, dass wir heiraten werden… aber nachdem ich seinen Antrag abgelehnt hatte, kehrte er in der Nacht zurück und entführte mich. Mein Bruder wollte ihn aufhalten, aber Arnak war einfach zu stark. Er...",
    ["Arugal still resides in Shadowfang Keep. We cannot claim Silverpine as a strategic stronghold for the Dark Lady until Arugal is slain. I shall see to it that his magic is eradicated."] = "Arugal lebt immer noch in der Burg Shadowfang. Wir können Silberwald erst dann als strategische Festung für die dunkle Fürstin beanspruchen, wenn Arugal erschlagen ist. Ich werde mich darum kümmern, seine Magie zu neutralisieren, <name>.",
    ["As if crashing into the Loch wasn't bad enough, troggs from the nearby island attacked me and stole my tools and special Blastenheimer Blastencapper explosives."] = "Als wäre es nicht schlimm genug gewesen, in den Loch zu stürzen, haben mich auch noch Troggs von der nahe gelegenen Insel angegriffen und mir mein Werkzeug und meinen speziellen Sprengstoff \"Superspreng\" aus der Blastenheimer-Sprengstoffstube gestohlen.",
    ["As you have seen, though the land is in pain, the cycle of life is a powerful thing. Now we must do our part help it along. You must plant these seeds at the center of the destruction, to the west, in the Charred Vale."] = "Wie Ihr sehen könnt, <class>, ist der Zyklus des Lebens eine mächtige Sache, auch wenn das Land Schmerzen leidet. Jetzt müssen wir unseren Teil leisten, um ihm zu helfen. Ihr müsst diese Samen im Zentrum der Zerstörung pflanzen, im Westen, im verbrannten Tal.",
    ["As you may know, wyverns are often tamed by orcs for use as mounts. But what is less known is that the venom of a wyvern, in some circles, is more valuable than the beast itself."] = "Wie Ihr sicher wisst, werden Flügeldrachen oft von Orcs als Reittiere gezähmt. Weniger bekannt indessen ist, dass das Gift eines Flügeldrachen in manchen Kreisen höher geschätzt wird als die Bestie selbst.",
    ["As you might know, I collect lore. Old lore. Powerful lore. Lore that opens doorways, and lore that can awaken Those Who Sleep."] = "Wie Ihr vielleicht wisst, trage ich Lehren zusammen. Alte Lehren. Mächtige Lehren. Lehren, die Portale öffnen, und Lehren, die die Schlafenden erwecken können.",
    ["At last, friends of the Alliance! Help... please... The last thing I remember these foul Orcs overpowered our regiment. Most the men were killed."] = "Freunde der Allianz! Endlich! Helft... bitte... Das Letzte, an das ich mich erinnere, ist, dass diese abscheulichen Orcs unser Regiment überwältigten.",
    ["At last, help has arrived! You have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place."] = "Endlich ist Hilfe eingetroffen! Ihr habt keine Ahnung, wie lang ich hier gefangen gehalten wurde. Ich kann mich nicht erinnern, wann ich zum letzten Mal draußen war.",
    ["Attention! A reward is being offered for the death of the murloc \"Murkdeep\"."] = "Achtung! Eine Belohnung wird ausgesetzt für den Tod des Murlocs \"Gurgelbacke\".",
    ["Avast! Who goes there? Argh, I am but useless without me special enchanted eye. Bad enough to have lost me eyes in battle in the first place!"] = "Haltet ein! Wer da? Grrr, ich bin so gut wie nutzlos ohne mein verzaubertes Spezialauge. Als ob es nich' schon schlimm genug is', dass ich meine Augen im Kampf verlor'n hab!",
    ["Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize."] = "Da Ihr mit solcher Verbissenheit und Ehre in der Schlacht von Hillsbrad gekämpft habt, habe ich für Euch diese Belobigung geschrieben, in der Eure Heldentaten im Kampf angemessen gerühmt werden, sodass das Oberkommando sie anerkennt.",
    ["Because you proved yourself to be such a go-getter in the jungle, let me tell you about a ferocious raptor that even I have failed to kill."] = "Da Ihr Euch im Dschungel als so tatkräftig erwiesen habt, lasst mich Euch von einem wilden Raptor erzählen, den sogar ich nicht erlegen konnte.",
    ["Before you spoke to me, I had heard of your endeavors... that you had an unyielding desire to prove yourself, that you had an exceptional ability as a, and I now know these things to be the truth."] = "Schon bevor Ihr mit mir spracht, <name>, habe ich von Euren Abenteuern gehört... dass Ihr den unerschütterlichen Willen habt, Euch selbst zu beweisen, und dass Ihr als <class> außerordentliche Fähigkeiten besitzt.",
    ["Before you take rest, speak to Tok'Kar again. While you were gone I believe he finished a few weapons. For your help here, he would offer one of them to you."] = "Ich mag weder das Meer noch die Kreaturen, die ich aus seiner Tiefe kommen sah. Es ist eine mächtige, aber blinde Herrin; launisch und brutal. Es wäre mir ein Vergnügen, die Fischmenschen zu Hunderten zu töten, wenn es in meiner Macht stünde.",
    ["Behold - the Hand of Iruxos. A gruesome sight indeed. You must possess it if the demon portals at Mannoroc Coven are to be banished... which is what I now ask you to do."] = "Seht - die Hand von Iruxos. Ein wirklich grausiger Anblick. Ihr müsst sie besitzen, wenn die Dämonenportale im Mannoroc-Koven gebannt werden sollen... und genau darum bitte ich Euch nun.",
    ["Bibbly thinks he is the only goblin in Desolace who knows how to make money. Well, the only caravan brave enough to travel these parts relies on me."] = "Bibbly glaubt, dass er der einzige Goblin in Desolace sei, der weiß, wie man Geld macht. Tja, die einzige Karawane, die mutig genug ist, diese Gebiete zu bereisen, verlässt sich auf mich.",
    ["Big dragons come and make fire at old home. Me smart ogre."] = "Verbeugen Euch vor Oberanführer Mok'Morokk! Rexxar mich machen zu mächtigem Anführer von Stonemaulklan!",
    ["Black dragons kill many ogre. Kill Tharg's wife."] = "Mok'Morokk wurde von Rexxar zum Oberanführer gemacht. Ihm liegt mehr an Macht als an den Ogern.",
    ["Blackrock Outrunners and Renegades are running ambushes between here and Stonewatch Keep. The leader of the Outrunners is an orc named Tharil'zun--we want this orc."] = "Zwischen hier und Burg Steinwacht legen Kundschafter und Renegaten der Blackrock ständig Hinterhalte. Der Anführer der Kundschafter heißt Tharil'zun und diesen Orc wollen wir haben.",
    ["Blast the nerve of Firallon! He couldn't sail a skiff through Crystal Lake let alone lead an entire fleet against us. The Bloodsail Buccaneers will pay for their carelessness."] = "Die Karte zeigt Booty Bay mit einem roten \"X\" genau an dem Punkt, wo Ihr gerade steht. Der hingekritzelte Text lautet: \"Leute, errichtet ein Lager an dieser Stelle und verhaltet euch schön unauffällig. Wartet auf das Signal vom südlichen Kommandoposten, bevor ihr angreift.",
    ["Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat. He is a blind buffoon. Proof stands two feet away from him and he does not see."] = "Bolvar ist ein Dummkopf. Ich war gerade dabei, ihm seinen kostbaren 'Beweis' zu beschaffen, um ihm diesen in den Hals stopfen zu können. Er ist ein blinder Blödmann. Selbst wenn der Beweis ihn in die Nase beißt, würde er ihn nicht sehen.",
    ["Bring me a sample of his skin along with other minor components and I shall craft you leggings of great power."] = "Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher?",
    ["Bring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us. Do it and I'll give ya a belt that our augurs use - one with powerful mojo inside it!"] = "Die Weissager kennen das Mojo der Elemente, das ist wahr. Sie setzen es ein, um den Stamm zu Ruhm und Ehre zu führen.",
    ["Bring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!"] = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.",
    ["Bring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don."] = "Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?",
    ["Burlguard sent you, did he? Yes, I have spare weapons around here, but first I have a task for you... A while ago a Defias villain Dead-tooth Jack tricked me."] = "Burlguard hat Euch geschickt, nicht? Ja, ich habe Waffen übrig, aber zuerst habe ich eine Aufgabe für Euch... Vor einer Weile überlistete mich ein Bösewicht der Defias, Stumpfzahn Jack.",
    ["But complications have arisen. A local band of ogres has occupied the Mizjah Ruins to the southeast of Grom'gol."] = "Als wir in diesem Dschungel ankamen, hatten wir nicht vor, die hier ansässigen Stämme zu bekämpfen. Unsere Mission, Stonard zu versorgen, hat höchste Priorität.",
    ["But the power harnessed in these goggles will allow you to locate them easily. A little gnomish ingenuity goes a long way!"] = "Der Schatz befand sich so lange auf dem Meeresboden, dass die Edelsteine von einer dicken Kalkschicht umgeben sind. Aber die Macht, die in dieser Schutzbrille gefangen ist, wird Euch ermöglichen, sie leicht zu finden.",
    ["But to blow the horn, you need a mouthpiece. To get a mouthpiece, kill Maraudine centaur."] = "<name>, Ihr habt uns gegen die Magram geholfen. Jetzt helft uns dabei, die Maraudine zu schlagen!",
    ["But, there may be more centaur than I thought, I ask you, to fight with me against these vile assassins."] = "Es könnte allerdings noch viel mehr Zentauren geben, als ich dachte, deshalb bitte ich Euch, <name>, zusammen mit mir gegen diese gemeinen Auftragsmörder zu kämpfen.",
    ["By communion with animals and givin' them up to the spirits when needed, they give us divine guidance. In times past, the haruspex's insight and wisdom gave us an edge in the wars against the splintered tribes of the Gurubashi."] = "Ein Haruspex ist ein wichtiges Mitglied in unserem Stamm, ihr tut gut daran auf ihr Omen zu hören. Mittels spiritueller Vereinigung mit den Tieren und deren Opferung, falls nötig, schenken sie uns göttliche Leitung.",
    ["By order o' 'is eminence, Overseer Oilfist, the rogue Thorium Brotherhood agent an' newly hired commander o' the Dark Iron Slag Pit crew o' the Cauldron, Overseer Maltorius, is to be killed an' 'is head brung back as proof o' the deed."] = "Auf Anordnung seiner Eminenz, Aufseher Oilfist, des Agenten der Thoriumbruderschaft und gleichzeitig neu angeheuerten Kommandanten der Schlackengrubentruppe der Dunkeleisenzwerge des Kessels, soll Aufseher Maltorius getötet und sein Kopf als Beweis für die Tat erbracht werden.",
    ["By order of High Executor Darthalia, the human known as Baron Vardus is wanted for crimes against the Forsaken. Vardus is known to be a high-ranking member of the organization known as the Syndicate."] = "Laut Befehl der Hochexekutorin Darthalia wird der unter dem Namen Baron Vardus bekannte Mensch wegen Verbrechen gegen die Verlassenen gesucht. Vardus ist bekannt als hochrangiges Mitglied der Organisation, die sich das Syndikat nennt.",
    ["By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice! A grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard."] = "Der üblen Priesterin Hexx und ihren Dienern soll im Namen von Primal Torntusk Gerechtigkeit widerfahren! Wer auch immer die üble Priesterin Hexx und alle ihre Aman'zasiwachen vernichten möge, soll eine bedeutende Entlohnung erhalten.",
    ["By order of the Magistrate of Thelsamar: Chok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary."] = "Auf Befehl des Magistrats von Thelsamar: Der Tod von Chok'sul, dem Oger und mutmasslichen Anführer und Kopf hinter den Angriffen auf die Stadt Thelsamar, den Stonewroughtdamm und die Ausgrabungsstätte, wird unter allen Umständen gewünscht.",
    ["Champion, is it you? A thousand years it has been since I was entrusted the shard and it is at my darkest hour that one should rise to relieve me of it..."] = "Held, seid Ihr es? Es ist tausend Jahre her, seitdem man mir den Splitter anvertraut hat.",
    ["Curses! That swab Maury put a lock on his foot, and I can't open it! His loot's inside the foot, and that's what he owes me! We need to find the key to open the lock."] = "Verflucht noch eins! Dieser Blödmann Maury hat ein Schloss an seinem Fuß befestigt und ich kann es nicht öffnen! Seine Beute ist in dem Fuß, und das sind seine Schulden! Wir müssen den Schlüssel finden, dann kriegen wir auch das Schloss auf.",
    ["Daddy told me to give you this key. He said it opens a chest out back behind the house. He also wanted me to thank you. Did you do a favor for him?"] = "Papa sagte, ich solle Euch diesen Schlüssel geben. Er sagte, er öffnet eine Truhe draußen hinter dem Haus. Er wollte außerdem, dass ich Euch danke. Habt Ihr ihm einen Gefallen getan?",
    ["Dangerous! The following humans of Hillsbrad have been deemed dangerous and are marked for bounty by High Executor Darthalia: Clerk Horrace Whitesteed."] = "Gefährlich! Die folgenden Menschen aus Hillsbrad werden als gefährlich erachtet.",
    ["Death Knight Darkreaver lords over the Great Ossuary in the Scholomance. He threatens to twist the spirit realm to do his own bidding, and he must be stopped!"] = "Der Todesritter Schattensichel herrscht über das große Ossuarium in Scholomance. Er droht die spirituelle Ebene zu seinen eigenen Zwecken zu missbrauchen...",
    ["Deep in Maraudon lives an evil creature of chaos--Princess Theradras is an elemental force of earth related to the Old Gods. Ages ago, she and Zaetar, first son of Cenarius, began a relationship."] = "Tief in Maraudon lebt eine böse Kreatur des Chaos - Prinzessin Theradras ist eine Naturgewalt der Erde, die mit den alten Göttern verwandt ist. Vor langer Zeit gingen sie und Zaetar, der erstgeborene Sohn von Cenarius, eine Beziehung ein.",
    ["Delgren has asked me to deliver messages and supplies to Sentinel Starbreeze in Auberdine, but I am loathe to leave on my own."] = "Delgren hat mich gebeten, der Schildwache Starbreeze in Auberdine Nachrichten und Nachschub zu bringen, aber es schmeckt mir gar nicht, allein dorthin zu gehen.",
    ["Demetria is chief advisor to the Grand Crusader. She is called the Oracle due to her 'otherworldly' senses. She has successfully assisted the Crusade in several of their victories against the Scourge."] = "Demetria ist die oberste Beraterin des obersten Kreuzzüglers. Ihrer 'überirdischen' Sinne wegen nennt man sie das Orakel. Sie hat den Kreuzzug erfolgreich zu mehreren Siegen gegen die Geißel geführt.",
    ["Did I mention the bad news yet? Its name is Maws: 100 feet of death and destruction. I guess I may have forgotten that little tidbit."] = "Hatte ich die schlechte Neuigkeit schon zur Sprache gebracht? Sein Name ist \"Der weiße Riese\": Einhundert Meter Tod und Zerstörung pur. Den kleinen Leckerbissen hatte ich glatt vergessen.",
    ["Did Lieutenant Doren want you to report back to him with that patrol information?"] = "Wollte Lieutenant Doren, dass Ihr Euch mit diesen Patrouillen-Informationen wieder bei ihm meldet?",
    ["Do you think you could help me find my way back to my friend, Rockbiter? He was supposed to be watching me... But I do have a tendency to wander off now and then."] = "Glaubt Ihr, Ihr könnt mir helfen, meinen Weg zurück zu meinem Freund, Felsbeißer, zu finden? Er sollte auf mich aufpassen... Aber ich neige dazu, gelegentlich davonzuschlendern.",
    ["During the last orc invasion we were forced to smelt our iron down to make bullets, swords and armor."] = "Während der letzten Invasion der Orcs waren wir gezwungen, unser Eisen einzuschmelzen, um Kugeln, Schwerter und Rüstungen herzustellen.",
    ["During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes."] = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.",
    ["Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal."] = "Edana Hasskralle ist die Königin der Nordschwingen, die in den Ruinen im Westen zu Hause sind. Sie ist das vollkommen Böse; ich habe gehört, dass sie ein Herz aus Kristall hat.",
    ["Empowered by the ancient rites of the chaotic Old Gods the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world."] = "Mit der Macht der uralten Rituale der chaotischen Alten Götter versuchen die Mitglieder der Twilight-Hammer, ihre dunklen Schutzherren zurückzuholen und Tod und Schrecken in der Welt zu verbreiten.",
    ["Even fragmented, they still possess the powers of the demons trapped inside. The orb of Soran'ruk was broken into two pieces, one was further broken to be used by the acolytes of the Twilight's Hammer in Blackfathom Deeps."] = "Wenn Dämonen der Legion in Ungnade fallen, wird ihr Geist in Kugeln gefangen und an ihre Magier und Hexenmeister verteilt. Viele wurden von ihren Bediensteten in Azeroth getragen.",
    ["Even though my will is free, I can serve the Dark Lady no more. I feel my time on Azeroth has come to an end. My life force is shattered. Interrogator Vishas did this to me!"] = "Trotz meines freien Willens kann ich der dunklen Fürstin nicht mehr dienen. Ich fühle, dass meine Zeit in Azeroth zu Ende geht. Meine Lebenskraft ist zerschmettert. Das hat mir Befrager Vishas angetan!",
    ["Everything was going well, but a large gust of wind blew through the camp and scattered the pages everywhere! I was able to gather most of the pages but many are still strewn about the jungle."] = "Meister Nesingwary wird furchtbar wütend sein, wenn er das herausfindet! Er vertraute mir das Manuskript für seinen Roman, \"Die Grünen Hügel des Schlingendorntals\", zum Korrekturlesen an.",
    ["Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them."] = "Exekutor Zygand sagt mir, dass Ihr Scharlachrote Kreuzzügler töten wart. In Tirisfal wimmelt es nur so von denen.",
    ["Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos... The skull of Gul'dan ensured that none were spared here."] = "Der Teufelswald war einst ein friedliches und ruhiges Land... bis die Legion hier eingefallen ist. Die Höllenbestien, Zerstörung, Chaos... Der Schädel des Gul'dan hat dafür gesorgt, dass hier niemand ungeschoren davonkam.",
    ["Finally! Someone to rescue me! I can't believe you got past the guards. These zealots from Theramore are out of their minds. They sank our ship and imprisoned me, the only survivor."] = "Endlich! Jemand rettet mich! Ich kann es nicht glauben, dass Ihr an den Wachen vorbeigekommen seid. Diese Fanatiker aus Theramore müssen verrückt sein. Sie haben unser Schiff versenkt und mich, den einzigen Überlebenden, eingesperrt.",
    ["Following Khazgorm's plans it should be no problem to fashion an explosive charge Ah, there we go. Now, I am going to entrust you with a special task."] = "Wenn wir uns an Khazgorms Pläne halten, sollte es eigentlich kein Problem sein, eine Sprengladung herzustellen. Ah, fertig.",
    ["Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor? I fear that the blood elves will meet a similar deformation."] = "Törichte Blutelfen spielen mit Dämonenmagie. Wurden sie nicht Zeugen, was mit den Naga und den Satyrn von Kalimdor geschehen ist? Ich fürchte, die Blutelfen werden auf ähnliche Weise deformiert.",
    ["For all the work that you have done, you deserve to be well rewarded. Return to Delgren and tell him that Athrikus Narassin lies stilled by your hand, and the Cult of the Dark Strand is beaten and scattered."] = "Für all das, was Ihr geleistet habt, habt Ihr eine ordentliche Belohnung verdient. Kehrt zu Delgren zurück und sagt ihm, dass Ihr Athrikus Narassin eigenhändig den Garaus gemacht habt, und dass der Kult des dunklen Strangs zerschlagen ist.",
    ["For now I will exchange your belt and gauntlets."] = "Ihr habt große Verlässlichkeit bewiesen, <name>.",
    ["For so long, I have been a puppet of the Grand Crusader. What reason was there to fight against what the Scarlet Crusade had become?"] = "Über so lange Zeit war ich eine Marionette des obersten Kreuzzüglers. Welchen Grund gab es, gegen das anzukämpfen, was aus dem scharlachroten Kreuzzug geworden ist?",
    ["For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line."] = "Die Innenseiten sind fertig gestellt, jetzt fehlt nur noch die äußere Schicht. Dafür verwende ich nur die besten Häute der alten Krokilisken.",
    ["For you to know the way of our illusionists, go to Zul'Gurub and bring back to me selected Paragons of Power. For this, I will give you arm wraps our illusionists use to weave their spells."] = "Magier sind in unserem Stamm als Illusionisten bekannt. Sie setzen bei ihren Beschwörungen mächtiges Mojo ein, bringen die Feinde des Stamms oft durcheinander und machen sie konfus!",
    ["For your shrewdness and valor, I have a marker here that is good for one piece of armor. I want you to take it to Sara Timberlain at the Eastvale Logging Camp."] = "Als Dank für Eure Gewitztheit und Euren Mut gebe ich Euch hier einen Gutschein, den Ihr gegen ein Rüstungsteil eintauschen könnt. Bringt den Gutschein ins Holzfällerlager des Osttals zu Sara Timberlain.",
    ["From the corpses of the fallen, the armor is stripped and taken back to Naxxramas to be used for unknown purposes."] = "Im letzten Krieg sind zahllose Helden umgekommen und auch heute fallen der Geißel täglich noch viele weitere Streiter zum Opfer.",
    ["Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge."] = "Garrick Padfoot, ein Dieb und Halsabschneider, der schon seit Wochen unseren Bauern und Händlern das Leben schwer macht, ist bei einem Schuppen in der Nähe der Weinberge gesehen worden.",
    ["Gazlowe told me once, \"Rezlak. There's one thing you need to know in life, and that's if you want something done well, do it yourself.\" I can't deal with losing all our caravans, so I'm just going to take matters into my own hands."] = "Gazlowe sagte mal zu mir: \"Rezlak. Eines musst du im Leben wissen: Wenn du was richtig gemacht haben willst, dann tu's selbst.\" Ich kann es mir nicht leisten, all unsere Karawanen zu verlieren, also muss ich die Sache selbst in die Hand nehmen.",
    ["General Shandris Feathermoon would like to speak with you personally."] = "<name>, General Shandris Feathermoon möchte unter vier Augen mit Euch sprechen.",
    ["Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west. The slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help."] = "Eindringlinge der Knarzklauen wurden beim Überfall im Westen des Ban'ethil-Grabhügels gesehen. Wenn wir ihnen nicht zur Hilfe kommen, werden die schlummernden Druiden auf ewig im Smaragdgrünen Traum gefangen gehalten, vollkommen ahnungslos ihrem Schicksal ausgeliefert.",
    ["Gnolls, brutish creatures with no decent business in these lands, have been seen along the borders of Elwynn Forest. A large pack of them, many more than we can handle alone, have infested the woods south of the guard tower yonder."] = "Gnolle, brutale Wesen, die in dieser Gegend nichts zu suchen haben, sind entlang der Grenzen des Waldes von Elwynn gesehen worden. Ein großes Rudel, viel zu viele, als dass wir allein mit ihnen fertig werden könnten, hat sich in den Wäldern südlich von jenem Wachturm dort eingenistet.",
    ["Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined."] = "Vor zwei Jahren noch hat man sich jedesmal darüber lustig gemacht, wenn die Rede auf Gnomentechnologie kam. Diese Zeiten haben sich definitiv geändert. Jetzt haben sie eine neue Maschine gebaut, die besser ist als all unsere Schreddermodelle zusammen.",
    ["Gnomeregan has fallen under the control of those dastardly troggs! The situation is grave but perhaps you can help. Deep in the Deadmines is a functional goblin shredder."] = "Gnomeregan ist diesen elendigen Troggs in die Hände gefallen! Die Situation ist ernst, aber vielleicht könnt Ihr helfen, <name>. Tief in den Todesminen gibt es einen funktionierenden Goblinschredder.",
    ["Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?"] = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?",
    ["Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power? I must warn you; purchases made at a friendly reputation with the Dawn come with an extremely hefty surcharge."] = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet? Ich muss Euch warnen, wer bei der Argentumdämmerung einen freundlichen Ruf genießt, muss sich bei Käufen mit einem extrem hohen Aufpreis abfinden.",
    ["Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power? I must warn you; purchases made at a friendly reputation with the Dawn come with a hefty surcharge."] = "Seid gegrüßt, <mein Freund/meine Freundin>. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet? Ich muss Euch warnen, wer bei der Argentumdämmerung einen freundlichen Ruf genießt, muss sich bei Käufen mit einem hohen Aufpreis abfinden.",
    ["Greetings, young one. You have a gleam in your eye; I can tell you are eager to venture back to the plains for the hunt. May you bring honor to your clan!"] = "Seid gegrüßt. Ihr habt so einen Glanz in den Augen; Ihr brennt darauf, in die Ebene zurückzukehren, um zu jagen. Möget Ihr Eurem Klan Ehre machen!",
    ["Greetings. I am Conservator Ilthalaine. My purpose in Shadowglen is to ensure that the balance of nature is maintained."] = "Seid gegrüßt, <name>. Ich bin Konservator Ilthalaine. Meine Aufgabe in Shadowglen ist es, für den Erhalt des Gleichgewichts der Natur zu sorgen.",
    ["Hail! I can tell by your demeanor that you've seen and done much in this world. Yet I'm willing to wager you haven't seen a piece of armor like this."] = "Seid gegrüßt, <class>. Ich habe hier etwas, das Euch interessieren könnte. Es gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität.",
    ["Hail. Perhaps you've seen those spiders that have taken over the western border? The eight-legged menaces are too much for us to handle, and the Commander hasn't enough manpower to spare so far from Darkshire."] = "Seid gegrüßt, <class>. Vielleicht habt Ihr die Spinnen gesehen, die die Grenze im Westen überrannt haben? Mit den achtbeinigen Monstern werden wir nicht fertig und der Kommandant hat nicht genug Leute, um sie so weit weg von Dunkelhain einsetzen zu können.",
    ["He must be stopped! Take this sacred cord, and string through it the heads of the high priests responsible for channeling our gods' energy."] = "Es ist wahr. Hakkar hat sich in Zul'Gurub eingenistet und badet in den Kräften unserer Götter.",
    ["He told me of its demonic red eyes, razor-sharp talons and venomous bite. As fortune would have it, while traveling across the plains, I encountered it, and it took a nasty bite from my shoulder."] = "Mein Großvater erzählte mir Geschichten von seinen Kämpfen gegen einen Schreiter namens Mazzranache. Er erzählte mir von seinen dämonischen roten Augen, rasiermesserscharfen Krallen und seinem giftigen Biss.",
    ["He's done it this time! Bad enough that Gelriz's muscling out the moguls who were appointed by the trade princes, now he tries to cut in on the most notorious pirate!"] = "Diesmal ist er zu weit gegangen! Schlimm genug, dass Gelriz dabei ist, die von den Handelsfürsten eingesetzten Moguln rauszudrängen, jetzt versucht er auch noch, den berüchtigtsten aller Piraten mit hineinzubringen!",
    ["Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin' learned more soon."] = "Geht zurück zu Belgrom in Orgrimmar und sagt ihm, dass Moktar in Tausend Nadeln ganz in seinem Sinne handelt. Sagt ihm auch, dass meine Studien voranschreiten und ich hoffe, dass ich bald mehr gelernt habe.",
    ["Heathens have a place in the tribe. Heathens are freethinkers of Zandalar."] = "Ihr seid ungläubig. Ungläubige haben einen Platz in unserem Stamm.",
    ["Heavens no! Poor Rustlocke. 'Tis quite a tragedy indeed. We must not let his death pass in vain."] = "Eine enorme Explosion donnerte durch die Hügel hinweg. 's war furchtbar, sag ich Euch! Gute Soldaten starben bei der Verteidigung des Thandol-Übergangs. Longbraid sagt, wir werden uns noch an den Dunkeleisenzwergen rächen.",
    ["Help me make some Westfall Stew! Come back with the following ingredients: 3 Stringy Vulture Meat 3 Goretusk Snouts 3 Murloc Eyes 3 Okra"] = "Wollt Ihr mir dabei helfen, Westfall-Eintopf zu kochen? Dann bringt mir die folgenden Zutaten: 3 Stücke sehniges Geierfleisch 3 Geiferzahnschnauzen 3 Murlocaugen 3 Okraschoten",
    ["Here is some encased ooze created from the Felwood samples you recovered. Take the case to Un'Goro Crater and find a pure ooze... the primal variety will do nicely."] = "Hier drin eingeschlossen ist einer von den Brühschlammern, die Ihr im Teufelswald eingesammelt habt. Bringt das Behältnis zum Un'Goro Krater und sucht dort einen reinen Brühschlammer - einer von den Urzeitbrühschlammern wird's tun, denke ich. Sobald Ihr nahe genug heran seid, lasst den Brühschlammer aus dem Behältnis frei, und dann wollen wir doch mal sehen, was die beiden voneinander halten.",
    ["Here you go. Bring this message to Master Carevin. A few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today."] = "Hier, bitte schön, <name>. Bringt Meister Carevin diese Nachricht. <Schnell zieht er ein Stück verblasstes Pergament hervor und reicht es Euch.> Noch ein paar mehr wie Ihr, dann sind wir bald mehr Kämpfer als die Nachtwache! Vielleicht können wir dann das Werk vollenden, an dem wir wenigen uns heute noch vergebens abmühen.",
    ["Here's your cask of Evershine. And again, thank you for the hunting earlier."] = "Hier habt Ihr Euer Fässlein mit Immerschimmer, <name>. Und wie gesagt, vielen Dank für die Jagd kürzlich.",
    ["Here, take this and lay it on his grave. Maybe... somehow, he'll know that I'm okay, and that none of us hold him responsible for what happened."] = "Hier, nehmt dies und legt es auf sein Grab. Vielleicht... vielleicht weiß er dann irgendwie, dass es mir gut geht und dass keiner von uns ihn für das verantwortlich macht, was geschehen ist.",
    ["Hey!! Come here! My raiders and I are about to attack the Silverwing Outpost to the west. Our target is its leader, Duriel Moonfire. Scouts report the outpost is defended heavily with sentinels and warriors."] = "He! <class>! Kommt mal her! Meine Räuber und ich wollten gerade den Außenposten der Silverwing im Westen angreifen. Unser Ziel ist der dortige Anführer, Duriel Moonfire.",
    ["Hey. Be careful 'round here. There be Dark Iron dwarves all around--looked like the Shadowforge clan. They just attacked the excavation site I was workin' at--killed nearly everyone there, including my boss Hammertoe."] = "He, <name>. Seid lieber vorsichtig. Es sind Dunkeleisenzwerge in der Nähe - scheinen vom Schattenschmiedeklan zu sein. Sie haben gerade die Ausgrabungsstätte angegriffen, auf der ich arbeite - haben fast alle dort umgebracht, darunter meinen Boss Hammertoe.",
    ["Hey. I been sent to the Crossroads to watch over the land and take note of its happenings for my masters in Orgrimmar. One object of my studies are the insect-like creatures found to the south in the Field of Giants."] = "He, <name>. Man hat mich nach Crossroads geschickt, damit ich über das Land wache und meinen Meistern in Orgrimmar über eventuelle Vorkommnisse berichte. Eines meiner Studienobjekte sind die insektenartigen Kreaturen, die man im Süden auf dem Feld der Riesen findet.",
    ["Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens. He is fierce, brutal and cunning. Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us."] = "Hezrul Blutmal ist der Anführer der Kolkarzentauren im Brachland. Er ist wild, brutal und schlau. Könnte man ihn besiegen, würde das die Kolkars spalten und zerschlagen und die Bedrohung durch sie enorm entschärfen.",
    ["High Executor Darthalia sent me to keep watch of Dun Garok from a distance. I had set up camp just out of sight. But when morning came and I had to boil water, I left to gather firewood."] = "Hochexekutorin Darthalia hat mich hergeschickt, um Dun Garok aus der Ferne zu beobachten. Ich hatte mein Lager gerade außer Sichtweite aufgeschlagen. Am Morgen, als ich Wasser kochen wollte, ging ich Feuerholz sammeln.",
    ["Hildelve wrote in his journal that he was attacked by Mangeclaw, a \"huge Ice Claw Bear.\" He drove off the beast, but not before it mauled him savagely."] = "Hildelve schrieb in sein Tagebuch, dass er von Marterklaue, einem \"gewaltigen Eisklauenbären\", angegriffen wurde.",
    ["How can one truly hope to win against a foe that is not even really there? We Zandalar know the power of this, and as such illusionists hold a honored place within the tribe."] = "Magie ist eine rohe, uralte Kraft, die von denen beherrscht werden muss, die stark genug dafür sind. Mojo ist unsere Ausdehnung dieser Macht; eine der mächtigsten Manipulationen davon ist die Form der Illusion.",
    ["I am devising a potion that requires rare mushrooms, mushrooms that grow only in a certain cave. The cave lies behind Cliffspring Falls, to the east and slightly north along the mountains."] = "Ich entwickle gerade einen Trank, für den rare Pilze erforderlich sind. Pilze, die nur in einer bestimmten Höhle wachsen.",
    ["I am so lost! My wife, Torta, sent me out to fetch dinner and I must have taken a wrong turn somewhere. Would you be so kind as to lead me back to Torta?"] = "Ich habe mich vollkommen verirrt! Torta, meine Frau, schickte mich Essen holen, aber ich muss irgendwo falsch abgebogen sein. Würdet Ihr so freundlich sein, mich zu Torta zurückzuführen?",
    ["I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission. It may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains."] = "<name>, ich bin mir sicher, dass Tyrande Whisperwind Euch persönlich für Eure Teilnahme an dieser Mission danken wollen wird. Es mag auf den ersten Blick zwar nicht so aussehen, aber Ihr habt dazu beigetragen, etwas in Gang zu setzen, das unsere Position im Steinkrallengebirge erheblich stärken wird.",
    ["I am the new magistrate of Southshore, recently assigned after the assassination of the previous magistrate."] = "Ich bin der neue Magistrat von Southshore.",
    ["I am the only survivor from our caravan attack by the centaur! A rare yet mighty panther is guarding my best gizmo, which is around his neck."] = "Ich bin der einzige Überlebende des Angriffs der Zentauren auf unsere Karawane! Ein rarer, aber mächtiger Panther bewacht mein bestes Dingsda, das um seinen Hals geschlungen ist.",
    ["I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me an ordinary belt and a set of gloves that you wish to upgrade."] = "Ihr habt große Verlässlichkeit bewiesen, <name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.",
    ["I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me the belt and set of gauntlets that you wish to upgrade."] = "Ihr habt große Verlässlichkeit bewiesen, <name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.",
    ["I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me the belt and set of gloves that you wish to upgrade."] = "Ihr habt große Verlässlichkeit bewiesen, <name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.",
    ["I came to Shadowglen to observe the webwood spiders that dwell in the Shadowthread Cave."] = "Ich kam nach Shadowglen, um hier die Waldweberspinnen zu beobachten, die in der Schattenweberhöhle leben.",
    ["I can make you a protective item that'll be of assistance in the fight against our enemy. I shall need a Qiraji drape, which I'll resize for you of course."] = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, <name>. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, <class>.",
    ["I can't lift the curse from the Eye of Paleth."] = "Ich kann den Fluch nicht von dem Auge von Paleth nehmen.",
    ["I do not know why, but a festering grows within the Wetlands. Fen Creepers have risen. They are diseased, fevered blisters on the land, and for the fever to break they must be dispatched and allowed to settle back into the marshes."] = "Ich weiß nicht warum, aber irgendetwas schwärt im Sumpfland. Moorkrabbler haben sich dort ausgebreitet. Sie sind wie kranke, fiebrige Blasen auf dem Land, und um das Fieber zu besiegen, müssen sie erledigt und dem Sumpf wieder zugeführt werden.",
    ["I entrust you with the Gem of the Serpent. Place this gem on the Serpent Statue's hand on Ranazjar Isle, a small island northwest of here. Placing it will summon the one who protects the Book of the Ancients."] = "<name>, ich vertraue Euch den Edelstein der Schlange an. Legt diesen Edelstein auf der Insel Ranazjar nordwestlich von hier in die Hand der Schlangenstatue. Dadurch wird jener gerufen, der das 'Buch der Uralten' beschützt.",
    ["I fear the ancient statuette's secrets will remain forever hidden unless you find the key to its ancient lock. That key is a ring, the Ring of Zoram."] = "Ich fürchte, die Geheimnisse der antiken Statuette werden für immer verborgen bleiben, wenn Ihr nicht den Schlüssel zu ihrem antiken Schloss findet. Dieser Schlüssel ist ein Ring, der Ring von Zoram.",
    ["I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step. But I am no longer the hero..."] = "<name>, ich fange endlich an, mich zu erinnern! Ich bin hergekommen, um gegen Sturmflamme zu kämpfen. Ich war auf einer Reise und das hätte der letzte Schritt sein sollen. Aber ich bin kein Held mehr...",
    ["I find myself in quite a pinch here. The bottles are close to running dry. The latest booze shipment is long overdue. The orc invasion has been hell."] = "Mir werden hier gerade die Vorräte knapp, <name>. Alle Flaschen sind fast leer, und die letzte Schnapslieferung hätte schon längst hier eintreffen sollen. Die Orcinvasion ist einfach die Hölle. Vielleicht könnt Ihr Euch ja für mich an die Arbeit machen?",
    ["I guess I'd better think about getting out of here, also. It won't take long for word of what happened here to spread to the higher ups, and I'm sure they wouldn't take too kindly to meeting me again."] = "Wisst Ihr, ich war hier einst die zweitwichtigste Person. Das hat sich alles geändert, als Gerenzo hier übernahm.",
    ["I had a month's worth of dried meats salted and locked away for the cold season. Kept it locked so the bears wouldn't get it! But while I was off hunting deer, that beast, Old Icebeard, made off with the meat locker."] = "Ich hatte einen Monatsvorrat Trockenfleisch gesalzen und für die kalte Jahreszeit weggeschlossen. Weggeschlossen deshalb, damit die Bären nicht rankommen! Aber während ich unterwegs auf der Jagd war, hat sich diese Bestie, Eisbart der Alte, mit meinem Fleisch-Spind davongemacht.",
    ["I hate those nasty timber wolves! But I sure like eating wolf steaks... Bring me tough wolf meat and I will exchange it for something you'll find useful."] = "Ich hasse diese grässlichen Waldwölfe! Aber Wolfsteaks esse ich für mein Leben gern. Bringt mir zähes Wolfsfleisch, dann gebe ich Euch etwas dafür, das Euch von Nutzen sein wird.",
    ["I have a lead on an even BETTER source of hides, if that's even possible to believe! In the northern parts of Feralas - deep within Rage Scar Hold - are another throng of yetis."] = "Ob Ihr es glaubt oder nicht, ich habe eine noch viel bessere Quelle für Yetibälge entdeckt! Im nördlichen Teil von Feralas, tief in der Wutschrammfeste gibt es noch andere Yetis.",
    ["I have cutting to do. I can't tell you what I'm going to cut, but... I need myself a blade. A certain blade... Some people call it a sword. I call it a swing blade."] = "Ich habe zu schneiden. Ich kann Euch nicht sagen, was ich schneiden werde, aber... Ich brauche eine Klinge. Eine ganz bestimmte Klinge... Manche Leute sprechen von einem Mondstahlbreitschwert. Ich nenne es eine Schwingklinge.",
    ["I have discovered a use for the carapace of the crypt fiend. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas."] = "Ich habe eine Verwendung für den Panzer der Gruftbestie gefunden. Ich bin in der Lage, ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente von Gruftbestien mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.",
    ["I have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality. I'd be willing to trade the bracers for ordinary ones in exchange for a small favor."] = "Seid gegrüßt, <class>. Ich habe hier etwas, das Euch interessieren könnte.",
    ["I have not long to live... so... so... weak....the b-b-brave dwarf, Lonebrow, has been sent to w-w-warn Falfindel... But before I... d-d-die......my wife, Treshala..."] = "Ich habe nicht mehr lange zu leben... so... so... schwach. ... der t-t-tapfere Zwerg Lonebrow hat jemanden geschickt, Falfindel zu w-w-warnen...",
    ["I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind."] = "Ich habe einen Bericht an den König vorbereitet. Und Ihr sollt sein Überbringer sein, zusammen mit einer Auflistung Eurer Ergebnisse. Macht Euch keine Sorgen, er wird Euch zweifellos für die Erfüllung Eurer Pflicht gegenüber den Leuten von Stormwind loben.",
    ["I have received reports that a group of undead are holing up to prepare for an attack against us. Armed with this information, we can turn the tables and attack them first, nipping their little plan in the bud."] = "Ich habe Berichte erhalten, dass eine Gruppe Untoter sich zusammenrottet, um einen Angriff gegen uns vorzubereiten. Mit diesen Informationen können wir den Spieß umdrehen und sie zuerst angreifen, damit wäre ihr Plan erledigt.",
    ["I have rendered the spores you gave me into an emulsion. I must now send it to my associate, Apothecary Zamah. If you were to carry this to her, she can offer you something from our stores of alchemical goods."] = "Ich habe die Sporen, die Ihr mir gabt, zu einer Emulsion verarbeitet. Die muss ich jetzt meiner Kollegin schicken, der Apothekerin Zamah. Wenn Ihr sie ihr bringen könntet, würde sie Euch bestimmt etwas aus ihrem Vorrat alchimistischer Waren anbieten.",
    ["I have reshaped the Mind's Eye into a Soul Gem. Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul."] = "Ich habe das Gedankenauge in einen Seelenedelstein umgeformt. Somit hat er zweierlei Zwecke: Erst verwendet Ihr ihn, um Yenniku zu betäuben, und sobald er betäubt ist, legt Ihr den Seelenedelstein auf seinen Kopf, um seine Seele einzufangen.",
    ["I have the digest for you. I need not tell you to take great care with it. And to keep it far from unfriendly hands. This book holds many truths......And the truth can burn."] = "Ich habe die Zusammenstellung für Euch, <name>. Ich muss Euch wohl nicht sagen, dass Ihr sie sorgfältig behandeln solltet. Und dass Ihr sie nicht in unfreundliche Hände gelangen lassen solltet. Dieses Buch enthält viele Wahrheiten...",
    ["I hear Lord Wishock enjoyed his beverage. You have served us well. The Warlocks of Stormwind will be able to practice our ways without disturbance, thanks to you."] = "Wie ich höre, hat Lord Wishock sein Getränk genossen. Ihr habt uns gut gedient, <name>. Die Hexenmeister von Stormwind werden nun, dank Euch, ohne Störung ihrem Tagewerk nachgehen können.",
    ["I hear you were enlisted by Darthalia to wage war on the humans of Hillsbrad. So jealous I am..."] = "Ich habe gehört, Ihr wurdet von Darthalia eingezogen, um Krieg gegen die Menschen von Hillsbrad zu führen. Ich bin ganz grün vor Neid...",
    ["I hope you're here to lend us a hand. After the last trogg attack, we could use all the help we can get. I hear the buggers have been popping up all across the lands, and it seems Coldridge Valley is no exception."] = "Ich hoffe, Ihr seid hier, um uns zu helfen, <class>. Nach dem letzten Angriff der Troggs können wir alle Hilfe gebrauchen, die wir kriegen können. Ich habe gehört, die kleinen Biester sind überall im ganzen Land aufgetaucht, und wie es scheint, ist das Coldridge-Tal keine Ausnahme.",
    ["I just arrived here in Feralas, and I've heard that the Gordunni Ogres that inhabit the wilds here have some interesting minerals. Who knows what they are up to, but they sure are protective of that stuff!"] = "Ich bin gerade erst hier in Feralas angekommen und habe gehört, dass die Oger der Gordunni, die die Wildnis hier bewohnen, einige interessante Mineralien besitzen. Keiner weiß, was die so vorhaben, aber sie passen höllisch gut auf dieses Zeug auf!",
    ["I just picked up this shredder from Ratchet and I was on my way back to the Warsong Lumber Camp, where I am supposed to be on duty."] = "Ich habe gerade diesen Schredder in Ratchet abgeholt und war auf dem Heimweg ins Holzfällerlager der Warsong, in dem ich eigentlich Dienst verrichten sollte.",
    ["I look at my undeath as a malady. An illness that merely requires treatment; however, it is also a great blessing for the Argent Dawn. What better vessel to smite the heathens of the Scourge than through the undead?"] = "Ich sehe meinen Untod als eine Krankheit an, <Volk>. Eine Krankheit, die einfach nur eine Behandlung erfordert; sie ist aber auch ein großer Segen für die Argentumdämmerung. Wie kann man die Heiden der Geißel besser schlagen als durch den Untod?",
    ["I love crab. Crabs are the fruit of the sea! You can bake it, barbecue it, boil it, and broil it. They're pan fried, deep fried, and stir fried."] = "Ich liebe Krebse. Krebse sind die Früchte des Meeres! Man kann sie backen, grillen, kochen und braten. Man kann sie in der Pfanne braten, frittieren und kurzbraten.",
    ["I make no pretenses, maggot. The darkness Plagueheart items hold could very well destroy the both of us."] = "Ich mache Euch nichts vor, Wurm. Die Finsternis, die die Rüstung des verseuchten Herzens erfüllt, könnte uns beide mit Leichtigkeit zerstören.",
    ["I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones."] = "Ich habe Gerenzo einmal getroffen, und lasst mich Euch eines sagen, er ist nicht gerade eine Schönheit. Sein Fleisch sieht aus, als würde es faulen.",
    ["I need some underbelly scales from black dragon whelps to pay for the shoes Argus sent me from Goldshire."] = "Ich brauche einige Bauchschuppen von schwarzen Großdrachenwelpen, damit ich die Hufeisen bezahlen kann, die Argus mir aus Goldhain geschickt hat.",
    ["I need you to venture into Hive'Regal and find what became of my dearest Natalia. This will be no easy task for you. Before you dive headlong into the maw of madness, make sure that you go back and speak with those dwarves."] = "Ihr müsst für mich in den Bau des Regalschwarms eindringen und herausfinden, was aus meiner liebsten Natalia geworden ist, <name>. Es ist dort sehr gefährlich, also geht nicht alleine dorthin. Sprecht noch einmal mit den Zwergen, bevor Ihr Euch in den Schlund des Wahnsinns stürzt.",
    ["I now present you with the Water of the Seers. When you are ready, consume the waters near the tribal fire. Once you have ingested the holy waters, it will take a few moments before the vision materializes before the fire."] = "Hier ist es nun, das Wasser der Seher. Wenn Ihr bereit seid, trinkt das Wasser in der Nähe des Stammesfeuers. Nachdem Ihr das heilige Wasser getrunken habt, wird es einen Moment dauern, bis die Vision vor dem Feuer erscheint.",
    ["I once served the Scarlet Crusade with honor, loyalty and pride. I believed their cause to be a noble one: to rid Azeroth of the undead."] = "Einst diente ich dem Scharlachroten Kreuzzug mit Ehre, Treue und Stolz. Ich hielt das Ziel, das sie verfolgten, für edel: Azeroth von den Untoten befreien.",
    ["I put my faith in you and anyone you can muster to help free me. The great Skymane King Mukla is my captor. He commands the beasts of this island, and they keep me here against my will with the aid of this chain."] = "In der Notiz steht Folgendes in recht guter Handschrift: An alle, die mir helfen können: Bitte, ich benötige dringend Hilfe. Ein großer Blaumähnengorilla hält mich auf einer Insel in den südlichen Meeren gefangen. Die Sternbilder am Nachthimmel sind mir nicht vertraut und von Dschungelbäumen verdeckt, aber an klaren Tagen kann ich die wilden Ufer im Nordwesten erkennen und im Südwesten etwas, das große Segelschiffe sein könnten.",
    ["I sent my apprentice out into the marshes to skin some of our famous giant Wetlands crocolisks. When he didn't return, I went out to look for him..."] = "Ich habe meinen Lehrling in die Marschen geschickt, um einige unserer berühmten riesigen Sumpflandkrokilisken zu häuten. Als er nicht zurückkam, bin ich losgezogen, um ihn zu suchen...",
    ["I should have known. My arch-enemy, Doctor Weavil, up to his old tricks! And now, thanks to your failure in Winterspring, Doctor Weavil has destroyed my book!"] = "Ich hätte es wissen müssen. Mein Erzfeind, Doktor Weavil, hat wieder seine dreckigen Finger im Spiel! Jetzt, nach Eurem Versagen in Winterspring, hat Doktor Weavil mein Buch zerstört!",
    ["I speak of Elementium, mortal. Find and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power."] = "Arygos hat die Theorie aufgestellt, dass das Element, welches während des Konflikts zwischen den uralten Göttern und ihren Anhängern entstanden ist, unter den richtigen Bedingungen für sie tödlich ist. Ich spreche vom Elementium, <Sterblicher/Sterbliche>.",
    ["I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?"] = "Ich würde mal sagen, ich kann das nach und nach lernen... Kann ja nicht so schwer sein. Ein paar Knöpfchen hier, ein oder zwei Hebelchen da... Also, seid Ihr bereit zu gehen?",
    ["I take pride in my leather work, and I feel it shows; quality should never be compromised. Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!"] = "Ich bin stolz auf meine Lederarbeiten und ich glaube, das sieht man ihnen an; Qualität sollte niemals zweitrangig sein. Jeder, der behauptet, Qualität sei unwichtig, wird Euch wahrscheinlich auch glauben machen wollen, dass die Erde keine Geheimnisse enthält!",
    ["I think I can fix the samophlange, but I'm going to need the user's manual first."] = "Ich glaube, ich kann das Samophlang reparieren, aber dazu brauche ich erst einmal das Handbuch.",
    ["I trust the Valley of Trials will teach you much, young. I was sent to the Valley to guide you, but I have discovered a growing taint here..."] = "Ich denke, das Tal der Prüfungen wird Euch viel lehren, <class>. Man hat mich eigentlich ins Tal geschickt, um Euch anzuleiten, aber ich habe dort eine sich ausbreitende Besudelung entdeckt...",
    ["I used to sail a ship from here all the way to Ratchet, in Kalimdor. I was a successful captain with a sterling reputation. Until... Those cursed sea giants ruined me!"] = "Früher hab ich ein Schiff von hier bis ganz nach Ratchet, in Kalimdor gesegelt. Ich war ein erfolgreicher Kapitän mit einem einwandfreien Ruf. Bis... Diese verfluchten Meeresriesen mich ruinierten!",
    ["I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade."] = "Man hat mich mit einer kleinen Gruppe Schildwachen hierher beordert, um den Orakelbaum vor den Harpyien zu beschützen, die überall im Tal Nester gebaut haben.",
    ["I was on my way to Maestra's Post to meet Liladris Moonriver, but I decided to stop here and take a short nap. Ever since I awoke from the emerald dream, I have been so sleepy..."] = "Ich war auf dem Weg zu Maestras Posten, um mich mit Liladris Moonriver zu treffen, als ich beschloss, hier anzuhalten und ein kurzes Nickerchen zu machen. Seit ich aus dem Smaragdgrünen Traum aufgewacht bin, bin ich ständig so müde...",
    ["I was playing near the Fargodeep Mine, and I think I dropped, er...I mean I saw, the old lady's necklace. Don't ask me how it got there...it wasn't me!"] = "Ich hab in der Nähe von der Tiefenschachtmine gespielt und da hab ich, glaub ich, die Kette von der alten Dame fallen ge... äääh, gesehen.",
    ["I was sent to Grom'gol to aid Nimboya on his quest, but... I too have reasons for being here. The Bloodscalp tribe is enemy to our tribe. Collecting trophies of our enemies gives us power over them."] = "Ich wurde nach Grom'gol geschickt, um Nimboya auf seiner Suche zu begleiten, aber... Ich habe meine eigenen Gründe, hier zu sein. Der Bloodscalpstamm ist der Feind unseres Stammes. Wenn wir Trophäen unserer Feinde sammeln, erhalten wir Macht über sie.",
    ["I was sent to the Valley to guide you, but I have discovered a growing taint here... A group that calls itself the Burning Blade has a coven here in the Valley of Trials."] = "Ich denke, das Tal der Prüfungen wird Euch viel lehren, <class>. Man hat mich eigentlich ins Tal geschickt, um Euch anzuleiten, aber ich habe dort eine sich ausbreitende Besudelung entdeckt...",
    ["I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb."] = "Ich werde sofort mit der Arbeit an Eurer Kugel beginnen und Euren neuen Dämon darin einschließen. Wenn ich damit fertig bin, könnt Ihr entscheiden, ob Ihr ihn lieber in Form eines Stabs oder einer Kugel hättet.",
    ["I will give you a weapon, but first you must aid me. The Razormanes to the northwest came into my camp a few nights past."] = "Ich gebe Euch eine Waffe, <name>, doch vorher müsst Ihr mir helfen. Vor einigen Nächten kamen die Grimmhauer von Nordwesten in mein Lager.",
    ["I will put the robe together for you now. It will take but a few moments. Do not go far."] = "Jetzt schneidere ich die Robe für Euch. Es dauert nur einen Augenblick. Geht nicht weit fort, ja?",
    ["I'll go make the wands now."] = "Ich werde jetzt die Zauberstäbe machen.",
    ["I'll leave it to you to get Tazan's satchel open, and return to me with its contents. The locking mechanism is complex, so it would probably be easiest if you obtained the key."] = "Die Methoden des Kriegshäuptlings sind zu zimperlich. Er wagt nicht, die Macht der Horde zu entfesseln.",
    ["I'll tell you what. If you give me those unfired gauntlets, I will teach you how to make a set all your own."] = "Beim Barte Thaurissans! Wo habt Ihr sie gefunden?",
    ["I'm a scientist, but also a treasure hunter at heart! Long ago, when trolls used to occupy this land, they created large amounts of ornaments modeled after Gahz'rilla, a hydra they worshipped as a deity."] = "<name>, ich bin zwar Wissenschaftler, aber im Grunde meines Herzens bin ich auch Schatzsucher! Vor langer Zeit, als Trolle dieses Land besetzt hielten, schufen sie eine große Anzahl von Ornamenten nach dem Vorbild der Gahz'rilla, einer Hydra, die sie als Göttin verehrten.",
    ["I'm behind on my report, and could use your help. I just managed to find where the trolls are holed up, but I saw so many trolls, I was afraid to go in."] = "Ich bin mit meinem Bericht etwas im Rückstand und könnte Eure Hilfe brauchen, <name>. Ich habe gerade herausgefunden, wo sich die Trolle verschanzt haben, aber ich habe so viele Trolle gesehen, dass ich mich nicht getraut habe, hineinzugehen.",
    ["I'm glad to hear you're aiding us in our attack on Ahn'Qiraj. I can make you a protective item that'll be of assistance in the fight against our enemy."] = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, <name>. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, <class>.",
    ["I'm going to have to do something about the giants if I stay out here! They're certainly not good for business, now are they?"] = "Ich muss etwas gegen die Riesen unternehmen, wenn ich hier draußen bleibe! Sie sind sicherlich nicht gut fürs Geschäft, oder nicht?",
    ["I'm going to need more samples. But--and I don't know how to put this--they have to be pure samples. I know, I know. \"What does 'pure' mean, Laris?\" I'm not sure."] = "Ich brauche noch mehr Proben, <name>. Aber - und ich weiß nicht so recht, wie ich das ausdrücken soll - es müssen reine Proben sein. Ich weiß, ich weiß. \"Was meint Ihr mit 'rein', Laris?\", fragt Ihr.",
    ["I'm making a flying machine! I got stranded here, and I'm absolutely horrible at finding my way around. I'd take a gryphon or wind rider back to Gadgetzan, but those beasts just scare me to death."] = "Ich baue einen Flugapparat! Ich bin hier gestrandet und habe leider absolut überhaupt keinen Orientierungssinn. Ich würde ja einen Greifen oder Windreiter zurück nach Gadgetzan nehmen, aber diese Viecher jagen mir einfach eine höllische Angst ein.",
    ["I'm on a quest, a quest to make the perfect stout. I know I can do it -- brewing's in my blood. I just need to find the right recipe... The Frostmane trolls grow a plant, shimmerweed, high up in the hills to the east."] = "Ich bin von einem Vorhaben besessen, dem Vorhaben, das perfekte Starkbier herzustellen. Ich weiß, dass ich es schaffen kann - das Brauen liegt mir im Blut. Ich muss nur das richtige Rezept finden... Weit oben in den Bergen im Osten bauen die Trolle der Frostmane eine Pflanze an, Schimmerkraut genannt.",
    ["I've seen Kinelory look way worse after a night in the tavern than she does now. You obviously did a good job protecting her."] = "Kinelory sah nach einer Nacht in der Taverne schon schlechter aus als jetzt. Ihr habt sie offensichtlich sehr gut beschützt.",
    ["I, the great Bartolo, shall make for you the world famous, Alliance renowned, Yeti Fur Cloak!"] = "Ich, der große Bartolo, werde für Euch den weltberühmten, allianzweit bekannten Yetifellumhang anfertigen.",
    ["If the \"Collector\" is taking gold from our mines then he's stealing from the kingdom! Bring the Collector to justice, and bring me the ring mentioned in the pickup schedule you gave me."] = "Wenn der \"Sammler\" Gold aus unseren Minen entnimmt, dann bestiehlt er das Königreich! Führt den Sammler seiner gerechten Strafe zu und bringt mir den Ring, der in dem Abholplan, den Ihr mir gegeben habt, erwähnt wurde.",
    ["If you want Bonescythe made, you're going to have to supply the materials."] = "Wenn Ihr etwas von der Knochensensenrüstung wollt, dann werdet Ihr die Materialien dafür auftreiben müssen.",
    ["If you would be so kind as to deliver the relic to my wife Vestia, I would appreciate it. She's not only a fine priestess for our community, but she is one of the most well-versed scholars you'll find anywhere."] = "Wenn Ihr so nett wärt, das Relikt zu meiner Frau Vestia zu bringen, wüsste ich das zu schätzen. Sie ist nicht nur eine gute Priesterin für unsere Gemeinde, sondern auch eine der versiertesten Gelehrten, die es gibt.",
    ["Ilkrud Magthrull. Yes, I have knowledge of him. He is a powerful orc warlock that makes his residence at the Fire Scar Shrine, a place of great evil in southwestern Ashenvale."] = "Für all das, was Ihr geleistet habt, habt Ihr eine ordentliche Belohnung verdient. Kehrt zu Delgren zurück und sagt ihm, dass Ihr Athrikus Narassin eigenhändig den Garaus gemacht habt, und dass der Kult des dunklen Strangs zerschlagen ist.",
    ["Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin."] = "Es ist ein äußerst komplizierter Vorgang, die Waffen mit dem Muisek zu erfüllen. Aber da ich jetzt sowohl über alle erforderlichen Materialien als auch über das Muisek der von Euch eingefangenen Kreaturen verfüge, kann ich endlich beginnen.",
    ["In Timbermaw, we are content. We do not like strangers. This is good for us, but it is bad for trade. Not long ago, a rare night elf friend came to Timbermaw and she wore a runecloth cloak."] = "Wir in der Holzschlundfeste sind eigentlich ganz zufrieden. Wir mögen keine Fremden. Das ist gut für uns, aber schlecht für das Geschäft. Es ist noch nicht lange her, da kam eine Nachtelfenfreundin, die einen Runenumhang trug, auf die Holzschlundfeste.",
    ["In Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death."] = "Hmm, jetzt, wo ich darüber nachdenke, könnte es doch etwas geben, das Ihr für die Hand erledigen könntet. Ja, Jes'rimon könnte bestimmt Eure Hilfe brauchen.",
    ["In a cave along the southern bank of the lake, a timberling named Oakenscowl is spreading corruption to all the creatures that make Lake Al'Ameth their home."] = "In einer Höhle am Südufer des Sees überträgt ein Bäumling namens Grimmeiche die Verderbnis auf alle Wesen, die am Al'Amethsee leben.",
    ["In northern Winterspring, great cats assemble around a large landmark called Frostsaber Rock. The leader of these cats is known by the name Shy-Rotam."] = "Im nördlichen Winterspring sammeln sich große Katzen rund um einen großen Orientierungspunkt, dem Frostsäblerfelsen. Die Anführerin dieser Katzen ist unter dem Namen Shy-Rotam bekannt.",
    ["In preparation for an assault on Shadowfang, two deathstalkers were sent to the keep to gather intelligence."] = "Als Vorbereitung auf einen Überfall auf Shadowfang wurden zwei Todespirscher in die Burg geschickt, um Informationen zu sammeln.",
    ["In the Barrens lies a horrid mess of tangled vines called Razorfen Downs. While our first observations of this place revealed little threat, our recent findings are much more serious..."] = "Die Geißel ist eine dauerhafte Bedrohung für die Allianz. Ich bin sicher, Euch ist diese Tatsache vertraut.",
    ["In the aftermath of the battles at the Well of Eternity, I heard that Ameth'Aran had been destroyed, its people dead, including my love, Anaya."] = "Nach den Schlachten um den Brunnen der Ewigkeit hörte ich, dass Ameth'Aran zerstört wurde und alle Bewohner ums Leben kamen, darunter auch meine geliebte Anaya.",
    ["In the dark times after the fall of the Gurubashi Empire, Zandalar predators used their prowess to provide sustenance for the tribe."] = "In den dunklen Zeiten nach dem Fall des Imperiums der Gurubashi, setzten die zandalarianischen Jäger ihre Tapferkeit ein, um den Lebensunterhalt für den Stamm zu sichern.",
    ["Indurium has an amazing resistance to heat! I'm sure it will work for Fizzle's pistons."] = "Indurium besitzt einen erstaunlichen Hitzewiderstand! Ich bin sicher, es taugt für Fizzles Kolben.",
    ["Indurium has an amazing resistance to heat! I'm sure it will work for Fizzle's pistons. But he'll need true indurium ore, not just the flakes."] = "Indurium besitzt einen erstaunlichen Hitzewiderstand! Ich bin sicher, es taugt für Fizzles Kolben. Aber er braucht echtes Indurium, nicht nur die Späne.",
    ["It has become obvious that we cannot ensure that Blacklash and Hematus will remain imprisoned in Lethlor."] = "Es ist offensichtlich, dass wir nicht mehr gewährleisten können, Schattenbringer und Hematus noch länger in Lethlor festzuhalten.",
    ["It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon."] = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.",
    ["It makes them go berserk! Bring me 8 idols - I want to study them, and I want them out of Trogg hands!"] = "Vor einer Weile, kurz bevor die Troggs in der Stätte auftauchten, hatten wir eine große Anzahl seltsame, verzierte Götzen gefunden. Leider hatten wir keine Gelegenheit, sie zu untersuchen, denn kurz nach ihrer Entdeckung haben uns die Troggs aus den Ruinen verjagt.",
    ["It took a long time, but I found Reethe. He hide good for a human. Ogron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him."] = "Es hat lange gedauert, aber ich fand Reethe. Für einen Menschen hatte er sich gut versteckt. Ogron hatte Angst, nach der langen Zeit im Sumpf könnte er verrückt sein. Ihr kommt mit mir, denn wir brauchen Antworten von ihm.",
    ["It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color."] = "Es war die Kunst eines der mächtigsten Hochgeborenen, der das Siegel erschuf, das mein Gefängnis war. In Ameth'Aran, den Ruinen im Süden, die diesen hier aufs Haar gleichen, gibt es sogar heute noch eine uralte Flamme, blau ist ihre Farbe.",
    ["It's going to be tough going here if I can't manage to scrounge up some materials to construct some defenses and other necessities. I've noticed that the ogres in the area seem to be well equipped with scrap metal."] = "Es wird hier ganz schön haarig werden, wenn es mir nicht gelingt, Material aufzutreiben, um ein paar Verteidigungslinien und andere Notwendigkeiten zu konstruieren. Mir ist aufgefallen, dass die Oger in diesem Gebiet über jede Menge Metallschrott verfügen.",
    ["It's no secret that the trademark of the Defias Gang is their Red Bandanas. But we've learned that the material from which these bandanas are made signifies the member's rank."] = "Es ist kein Geheimnis, dass das Markenzeichen der Defiasbande ihre roten Kopftücher sind. Aber wir haben herausgefunden, dass das Material, aus dem diese Kopftücher gemacht sind, den Rang des Bandenmitglieds bezeichnet.",
    ["It's so cold, now. The Plague of Undeath crawls through my veins like an icy serpent. The Mindless State will be upon me soon. But no doomed destiny will prevent me from serving our Dark Lady."] = "Es ist jetzt so kalt. Die Seuche des Untodes kriecht durch meine Adern wie eine eisige Schlange. Ich werde bald den Hirnlosen Zustand erreichen. Doch auch ein besiegeltes Schicksal wird mich nicht davon abhalten, unserer dunklen Fürstin zu dienen.",
    ["It's terrible. We are not going to have enough parts to get our fleet of gyrodrillmatic excavationators to Dun Morogh. What we need are spare parts."] = "Es ist schrecklich, <name>. Wir werden nicht genug Teile haben, um unsere Flotte aus gyrobohrmatischen Exkavationatoren nach Dun Morogh zu bringen. Wir brauchen Ersatzteile, <name>.",
    ["It... It... It was all a trap. Forgive... me. Kill the bastard... Kill him for us... for Thorius."] = "Es... Es... Es war alles eine Falle. Vergebt... mir. Tötet den Bastard... Tötet ihn für uns... für Thorius.",
    ["Just before the invasion I uncovered a large tablet called the Goaz Stone. The translated text breaks off in 4 places. The text speaks of a \"divine plan\" and a \"doomed prophecy.\" I fear we are running out of time."] = "Kurz vor der Invasion habe ich eine große Schrifttafel gefunden, die man den Goazstein nennt. Der übersetzte Text reißt an 4 Stellen ab. Der Text spricht von einem \"göttlichen Plan\" und einer \"schicksalhaften Prophezeiung\".",
    ["Just one last thing you must do, soldier. I've taken the liberty of putting Gor'tesh's head on a pike. Now all you have to do is take this head to the top of Dreadmaul Rock and stick it into the ground."] = "Jetzt müsst Ihr nur noch eine Sache erledigen, Soldat. Ich habe mir die Freiheit genommen, Gor'teshs Kopf auf einen Pfahl zu stecken. Ihr sollt jetzt einfach diesen Kopf zur Spitze des Schreckensfelsens bringen und ihn in den Boden rammen.",
    ["Just recently, a large band of nomadic ogres arrived in Tanaris. South of here, they have taken over a large area of the desert and formed a compound."] = "Erst kürzlich ist eine große Gruppe nomadischer Oger in Tanaris eingetroffen. Südlich von hier haben sie einen großen Bereich der Wüste in Besitz genommen und ein Truppenlager aufgeschlagen.",
    ["Kill me. Before it's too late. I am Hameya. While traveling to Zul'Mashar, my brethren and I ate some bad meat... and we changed. We are infected."] = "Tötet mich. Bevor es zu spät ist. Ich bin Hameya. Auf der Reise nach Zul'Mashar aßen meine Geschwister und ich verdorbenes Fleisch... und wir veränderten uns. Wir sind infiziert.",
    ["Kroshius lays in a heap to the northeast, in the Shatter Scar Vale. Take this Fel fire and use it on his remains. The fire should reanimate the fallen infernal."] = "Kroshius liegt zusammengefallen im Shatter Scar-Tal, Richtung Nordosten. Verwendet dieses Teufelsfeuer auf seinen Überresten, es sollte die gefallene Höllenbestie wieder erwecken. Ich bin überzeugt, dass er Euch und Eure eventuell mitgebrachten Begleiter genau dann umbringen wird - und glaubt mir, Ihr werdet ein paar Freunde bei Euch haben wollen.",
    ["Kurzen may be dead, but...that which drove him to evil still lives! Through my studies I have discovered this: An Ogre Mage - Mai'Zoth - dwells in an Ogre Mound within the eastern mountains of Stranglethorn."] = "Kurzen mag vielleicht tot sein, doch das, was ihn zum Bösen trieb, ist noch am Leben! Mittels meiner Studien habe ich Folgendes entdeckt: Ein Ogermagier namens Mai'Zoth lebt in einem Ogerhort in den östlichen Bergen des Schlingendorntals.",
    ["Legend states that their ancient robes never looked the same twice. I will give you an illusionist's robe..."] = "Im Stamm wird Stellung und Macht durch das ausgezeichnet, was man trägt. Unsere Kleidung wird aus den feinsten Materialien hergestellt und mit Mojo verwoben, mit dessen Hilfe wir uns Macht verleihen.",
    ["Let me to be frank with you. I'm interested - nay, concerned with why the Arch Druid in Darnassus is using the name of the Cenarion Circle as well as the Circle's resources to procure vast amounts of morrowgrain."] = "Lasst mich offen mit Euch sein, <name>. Ich bin interessiert zu wissen - nein, ich muss es unbedingt wissen, warum der Erzdruide in Darnassus den Namen des Zirkels des Cenarius sowie dessen Mittel benutzt, um große Mengen Morgenkorn zu beschaffen.",
    ["Like many in our village, I too have lost a loved one to the wilds. Alas, it was my twin brother Malkhor - taken in the same raid as Torntusk's mate by the Vilebranch."] = "Wie viele in unserem Dorf, habe auch ich einen Nahestehenden verloren. Ach, es war mein Zwillingsbruder Malkhor - er wurde beim selben Überfall wie Torntusks Gefährte von den Vilebranch verschleppt.",
    ["Limiting the number of Bloodfury Harpies will not be enough. The only true cure for their disease would be to slay their leader, Bloodfury Ripper!"] = "Es genügt nicht, die Anzahl der Blutfurienharpyien zu verringern. Die einzig wahre Kur für ihre Krankheit wäre es, ihre Anführerin zu beseitigen, die Zerfetzerin der Blutfurien!",
    ["Listen well. While the four towers can never be destroyed, you can use the torch of retribution to set them ablaze for a very long period of time: A fire that no element or force can subdue."] = "Hört gut zu, <name>. Obgleich die vier Türme niemals zerstört werden können, könnt Ihr dennoch die Fackel der Vergeltung benutzen, um sie für lange Zeit in Brand zu setzen.",
    ["Listen, that ring is yours, sure..."] = "Hört mir zu, <name>.",
    ["Long ago I possessed a beautiful piece of jewelry, the Tiara of the Deep. And not only was it pretty--it held great power for those with the knowledge to use it."] = "Vor langer Zeit besaß ich ein wunderschönes Schmuckstück, die Tiara der Tiefen. Diese war nicht nur schön, sondern enthielt auch große Macht für diejenigen, die damit umzugehen wussten.",
    ["Look at what has happened to this place! These lands were once occupied by good farm folk. But the damned thieves have driven them all off. Not me, though!"] = "Jetzt seht Euch nur an, was aus diesem Ort geworden ist! In dieser Gegend lebten einst ehrbare Bauersleute. Die verdammten Diebe haben sie alle vertrieben. Aber mich nicht!",
    ["Lower your voice. The Kolkar centaurs lie just over the ridge to the west in Kolkar Crag."] = "Sprecht leiser, <class>. Die Zentauren der Kolkar liegen gleich hinter jener Kuppe im Westen der Kolkarklippe.",
    ["Malcin claims he is outside Razorfen Downs. This ambassador must be slain--his mission a failure in the eyes of the Lich King."] = "Milady, Ihr wisst sehr genau, was wir Euch anbieten. Die Gelegenheit, das Brachland und das dahinter liegende Gebiet zu erobern, ist nicht zu verachten.",
    ["Many a hunter is attracted to Loch Modan to hunt our famous crocs. There are always merchants who seek out crocolisk skins for clothing items or armor, and there are also some who enjoy the taste of their meat."] = "So manchen Jäger zieht es an den Loch Modan, um unsere berühmten Kroks zu erlegen. Irgendein Händler sucht immer Krokiliskenhäute für seine Kleidungsstücke oder Rüstungen und es gibt auch einige Leute, denen ihr Fleisch mundet.",
    ["Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with..."] = "Viele Angehörige der Legion bedenken ihre Anhänger mit Geschenken, wie Ihr bestimmt wisst. Manche dieser Geschenke wären nach Ansicht der Dunklen Fürstin besser in der Hand von Leuten aufgehoben, die...",
    ["Many of my friends perished that horrible day when the mine tunnel caved in. If your adventures happen to bring you into that wing of the mine in Moonbrook, please keep an eye out for any sign which might identify them."] = "Viele meiner Freunde starben an jenem schrecklichen Tag, als der Minentunnel einstürzte. Wenn Eure Abenteuer Euch in jenen Abschnitt der Mine in Moonbrook führen sollten, dann haltet doch bitte die Augen offen nach jedem Zeichen, anhand dessen man sie identifizieren könnte.",
    ["Many of my soldiers died in the battle of Dun Modr. My own brother perished when the West Bridge over the Thandol Span was destroyed. Aye, the Dark Iron dwarves are a devilish breed."] = "Viele meiner Soldaten fielen in der Schlacht von Dun Modr. Mein eigener Bruder kam um, als die Westbrücke über dem Thandol-Übergang zerstört wurde. Jawohl, die Dunkeleisenzwerge sind eine teuflische Brut.",
    ["Master Mazen's directions were quite clear: Deliver a very important essay to Watcher Mahar Ba in Nethergarde Keep. But I had never been to the Blasted Lands before!"] = "Als Verwalter der Arbeit hier in der Bibliothek der Akademie der Arkanen Künste und Wissenschaften liegt es in meiner Verantwortung, dafür zu sorgen, dass alle magischen Folianten und Rollen stets erfasst sind. Wer weiß, was Schlimmes geschehen würde, fielen einige dieser verzauberten Texte in die falschen Hände?",
    ["Maybe it'll even help protect you from the coming atrocity that is Lotwil's newest invention. I've been working with all the extra stones you collected for him, and I can make some nice bracers that you might want to use."] = "Ich weiß, wie knickerig Lotwil sein kann, <name>, also lasst mich etwas als Belohnung für all Eure Mühen fertigen. Vielleicht kann es Euch sogar vor der Scheußlichkeit schützen, die Lotwil gerade erfindet.",
    ["Me and some other warriors were sent by the Warchief to retrieve an object from Durnholde and to investigate this so-called Syndicate."] = "Ich und einige andere Krieger wurden vom Kriegshäuptling geschickt, um ein Objekt aus Durnholde zu holen und dieses so genannte Syndikat zu untersuchen.",
    ["Mellifluous liquid clear as a baby's tears Turns a lovely deep amber over the years But before we proceed to get lit to the hilt A barrel of charred oak must be built."] = "Das Getränk, das ich braue, das reine und klare, Wird goldbraun und samtig im Laufe der Jahre.",
    ["Mirah Chandler's song, given for finishing a chain of favours in the Barrens -- the reward players remember long after they forget the errands."] = "Das ist es, <name>.",
    ["Morbent Fel hides in his lair, the house perched atop the hill to the east overlooking the Raven Hill cemetery. His time in this land is drawing to an end..."] = "Morbent Fel hält sich in seinem Unterschlupf verborgen, dem Haus, das hoch oben auf dem Hügel im Osten über dem Friedhof von Rabenflucht thront. Doch seine Zeit in diesem Land neigt sich dem Ende entgegen...",
    ["Mud big ogre. Me hungry. Go bash fishy. Bring Mud food. You feed Mud or Mud eat you."] = "Mud großer Oger. Ich hungrig. Geht Fische hauen. Bringt Mud Essen. Ihr füttert Mud oder Mud frisst Euch.",
    ["Murlocs are becoming a problem. Larger groups of the fishmen are dropping anchor along the shores of Lake Everstill and fishing up a storm!"] = "Die Murlocs werden zu einem Problem. Große Gruppen der Fischwesen werfen entlang der Ufer des Immerruhsees Anker und fischen, was das Zeug hält!",
    ["My brother Quinn and I were tasked to recon Silverpine Forest and report to High Executor Hadrec. But we didn't get far -- when moving through this farm we were attacked by the ghoul Ivar the Foul."] = "Mein Bruder Quinn und ich wurden beauftragt, den Silberwald auszukundschaften und Hochexekutor Hadrec Bericht zu erstatten. Aber wir kamen nicht weit - als wir über diese Farm gingen, wurden wir von einem Ghul namens Ivar der Verfaulte angegriffen.",
    ["My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another."] = "Mein Bruder Ribbly hat unserer Familie schon immer auf der Tasche gelegen, unser Geld genommen und es für eine Dummheit nach der anderen ausgegeben.",
    ["My brother Senir and I were sent to different parts of Dun Morogh to investigate the threat posed by the trolls. The Senate has its hands full with the troggs, so they've no need for further annoyances."] = "Mein Bruder Senir und ich wurden in unterschiedliche Ecken von Dun Morogh entsandt, um dort die von den Trollen ausgehende Gefahr zu untersuchen. Der Senat hat mit den Troggs bereits alle Hände voll zu tun, deswegen kann er keinen weiteren Ärger gebrauchen.",
    ["My brother and I run the poison operations out of the manor Ravenholdt."] = "Mein Bruder und ich sind im Ravenholdt-Anwesen für den Giftbedarf zuständig.",
    ["My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies. Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life."] = "Meine Klangefährtin, Mura Runetotem, ist nach Silberwald gereist, um unseren untoten Verbündeten zu helfen. Der Silberwald ist ein kranker Wald, ein sterbender Wald, und Muras Hoffnung war, ihm neues Leben zu bringen.",
    ["My delvings into the Mosh'aru Tablets bear grim news. Hakkar's true form, the god himself, can be born again through the very egg into which you captured him."] = "Meine eingehende Beschäftigung mit den Mosh'aru-Schrifttafeln bestätigt den Verdacht auf schlechte Neuigkeiten, <name>. Hakkars wahre Gestalt, der Gott selbst, kann mit genau dem Ei wiedergeboren werden, in dem Ihr ihn gefangen habt.",
    ["My duties include tending to our wounded warriors, tailoring armor and clothes, and assisting Shadow Priest Sarvis with whatever else he might need."] = "Meine Pflichten umfassen, die verwundeten Krieger zu versorgen, Rüstung und Kleidung zu schneidern und Schattenpriester Sarvis in jeder erdenklichen Weise zu unterstützen.",
    ["My former mentor in the Stormwind city guard sent a message to me that Alliance High Command is becoming concerned with the threat posed by the naga."] = "Mein ehemaliger Mentor bei der Stadtwache von Stormwind hat mir eine Nachricht zukommen lassen, dass sich das Oberkommando der Allianz langsam Sorgen macht um die Bedrohung, die von den Naga ausgeht.",
    ["My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills."] = "Mein Freund Mori Hildelve, ebenfalls ein Pilot der Belagerungsmaschinen, hat sich in den Hügeln verirrt.",
    ["My grandfather told me stories about his battles with a strider named Mazzranache. He told me of its demonic red eyes, razor-sharp talons and venomous bite."] = "Mein Großvater erzählte mir Geschichten von seinen Kämpfen gegen einen Schreiter namens Mazzranache. Er erzählte mir von seinen dämonischen roten Augen, rasiermesserscharfen Krallen und seinem giftigen Biss.",
    ["My journal! They took it away to the cave. The one that had it... It was a big brute with some odd markings on his skin and face. I didn't get a much better look than that."] = "Mein Tagebuch! Sie haben es in die Höhle gebracht. Der, der es hatte, war ein großer Kerl mit seltsamen Zeichen auf der Haut und im Gesicht. Viel mehr konnte ich leider nicht sehen. Ihr hattet ja mit den Trollen Erfolg, vielleicht könntet Ihr es mir wiederbeschaffen?",
    ["My pet is almost done. Now I just need something to stuff it with. Only the voodoo feathers from the trolls in the sunken temple will do. They go by the names Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro."] = "Mein Begleiter ist fast fertig. Jetzt brauche ich nur noch etwas als Füllmaterial. Nur die Voodoofedern von den Trollen aus dem versunkenen Tempel sind dafür geeignet. Sie heißen Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro.",
    ["My philosophy on leatherworking is that the work must be the best quality possible - no compromises. Anyone who says that quality doesn't matter is trying to sell you ocean-front property in Dun Morogh!"] = "Ich bin stolz auf meine Lederarbeiten und ich glaube, das sieht man ihnen an; Qualität sollte niemals zweitrangig sein. Jeder, der behauptet, Qualität sei unwichtig, wird Euch wahrscheinlich auch glauben machen wollen, dass die Erde keine Geheimnisse enthält!",
    ["My physical being ceased functioning after an hour of this torture. The beast then ripped my wedding nose-ring off of my face and stuck it on his finger."] = "Meine ganze Gruppe wurde gefangen genommen, <name>. Alle wurden getötet - alle, außer mir.",
    ["Naralex had a noble goal. Our great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was."] = "Naralex hatte ein edles Ziel. Unser großer Anführer trachtete danach, in den Smaragdgrünen Traum zu gelangen und dabei zu helfen, aus diesem kargen Land wieder den üppigen Wald zu machen, der hier einst wuchs.",
    ["Negolash is a hungry giant. When the giants destroyed our ship, Negolash went straight for my kitchen. He wasn't hungry for crew like the other giants."] = "Negolash ist ein hungriger Riese. Als die Riesen unser Schiff zerstörten, ging Negolash schnurstracks in meine Kombüse. Er hatte keinen Appetit auf die Crew wie die anderen Riesen.",
    ["No, no, no - I'm not all of the sudden saying that the ring is mine."] = "Nein, nein, nein - ich behaupte nicht plötzlich, der Ring sei meiner.",
    ["Normally I put forth a small challenge to followers of the Light to test their skill."] = "Normalerweise wird etwa zu dieser Zeit die Macht in einem von Euch geprüft, um zu sehen, ob er würdig genug ist, jene Roben zu tragen, die seinen Platz in der Kirche anzeigen.",
    ["Nothing like a day of boar hunting, eh? Though, here in Coldridge Valley, there are so many boars it almost takes the fun out of it. No need to get them charging."] = "Es geht doch nichts über einen Tag auf der Eberjagd, wie? Na ja, hier im Coldridgetal gibt es so viele Eber, dass es fast schon keinen Spaß mehr macht. Man muss sie gar nicht mehr reizen.",
    ["Now is the time to assault the Scourge's place of strength in Silverpine: Fenris Isle. You must again go to the Isle and destroy Thule Ravenclaw."] = "Es ist an der Zeit, den Standort der Geißel im Silberwald zu stürmen: die Insel Fenris. Ihr müsst Euch noch einmal auf diese Insel begeben und Thule Rabenklaue vernichten.",
    ["Now it is time to capture the essence of the avatar of Hakkar. Take the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth."] = "Jetzt wird es Zeit, die Essenz des Avatars von Hakkar einzufangen. Bringt das Ei von Hakkar in das Sanktum des Gefallenen Gottes im Versunkenen Tempel in Azeroth.",
    ["Now that I have the spiders' venom, I'd like some live specimens to study. Unfortunately, capturing a living, giant spider is more than I can ask of you, young."] = "Jetzt, da ich das Spinnengift habe, hätte ich gern auch ein paar lebende Exemplare, um sie zu studieren. Leider kann ich Euch nicht darum bitten, eine lebende Riesenspinne für mich einzufangen, <class>.",
    ["Now that I've finished copying the book, here's the original Stresses of Iron. Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay."] = "Nachdem ich jetzt mit der Abschrift fertig bin, könnt Ihr das Original von \"Belastbarkeit von Eisen\" haben. Ich danke Euch für Eure Geduld, und wenn Ihr Milton seht, bitte sagt ihm, die lange Verzögerung täte mir Leid.",
    ["Now that my crop is saved, take this Grape Manifest to Brother Neals. He manages the store of food and drink in Northshire, and I'm sure he'll be delighted to hear that he has fresh grapes."] = "Jetzt, wo meine Ernte in Sicherheit ist, bringt diese Traubenliste zu Bruder Neals. Er ist verantwortlich für die Essens- und Getränkevorräte von Nordhain und ich bin mir sicher, er wird hoch erfreut sein zu hören, dass er frische Trauben bekommt.",
    ["Now that the catapults have been burned, find and kill Chieftain Nek'rosh."] = "Jetzt, nachdem die Katapulte abgebrannt wurden, sucht und tötet Häuptling Nek'rosh.",
    ["Now that you have gathered Bloodscalp trophies, I have another task for you. The Skullsplitter tribe of trolls live to the southeast, and for years we have warred with them."] = "Nun, da Ihr Bloodskalp-Trophäen gesammelt habt, habe ich eine weitere Aufgabe für Euch. Der Skullsplitterstamm der Trolle lebt im Südwesten und wir bekämpfen sie schon seit Jahren.",
    ["Now that you scared the centaur clans, it's time to bleed them. When traveling Desolace, hunt centaur. I don't care which clan you hunt. Just gather ears."] = "Viele Klans bilden das Volk der Zentauren. Jeder hat seinen Anführer und eine Agenda, aber alle Klans haben eines gemeinsam: Grausamkeit. Wenn wir je Frieden finden wollen, müssen die Zentauren entfernt werden. Und ich übertrage Euch die Aufgabe, genau das zu tun.",
    ["Now that you've had a taste of the Crushridge ogres, I want you to really bloody their noses... Go into the Ruins of Alterac and seek out the Crushridge Warmongers."] = "Nun, da Ihr die Bekanntschaft der Crushbridge-Oger gemacht habt, möchte ich, dass Ihr ihnen so richtig zeigt, was eine Harke ist... Geht zu den Ruinen von Alterac und sucht die Crushridge-Kriegstreiber.",
    ["Now the time has come to save the Druids of the Talon. If we fail now, they will be forever lost in sleep. I shall prepare the Relics of Wakening and perform the ritual."] = "Jetzt ist die Zeit gekommen, die Druiden der Kralle zu retten. <name>, sollten wir jetzt versagen, sind sie für immer im Schlaf verloren. Ich werde die Relikte des Erwachens vorbereiten und das Ritual durchführen.",
    ["Now there is just one more item needed to complete this device. Cog's blueprint calls for a lens of some sort. The only lens I know of that would be large enough will be very difficult to acquire."] = "Jetzt brauchen wir nur noch einen weiteren Gegenstand, um das Gerät fertig zu stellen. Laut Cogs Blaupause wird eine Linse oder etwas in der Art benötigt. Die einzige Linse, von der ich weiß, dass sie groß genug wäre, wird sehr schwierig zu beschaffen sein.",
    ["Now you must finish the task to which you have been appointed. Take the spinnerets and offer Lady Sathrah's sacrifice to Elune; lay the great spider to rest."] = "Jetzt müsst Ihr die Aufgabe vollenden, die Euch auferlegt worden ist. Nehmt die Spinndrüsen und bringt Elune Lady Sathrahs Opfer dar.",
    ["O'Breen led the ships into the cove. We were certain this is where the treasure could be found. The Harbinger docked safely but as the Maiden's Folly and Spirit of Silverpine approached the tides began to lower."] = "O'Breen führte die Schiffe in die Bucht. Wir waren ziemlich sicher, dass der Schatz dort zu finden sei. Die HARBINGER konnte noch sicher andocken, aber als die TOLLE MINNA und die SILBERGEIST näher kamen, senkte sich der Meeresspiegel plötzlich ab.",
    ["Off the coast of Darkshore to our north are two wrecked ships - the Silver Dawning and the Mist Veil. Some time ago, both ships ran afoul of the blasted murlocs as they sailed across the vast sea into Auberdine."] = "Nahe der Ufer von Dunkelküste im Norden liegen zwei havarierte Schiffe - die SILBERMORGEN und die NEBELSCHLEIER. Vor einiger Zeit kollidierten die beiden Schiffe wegen der verfluchten Murlocs, als sie über das weite Meer nach Auberdine segelten.",
    ["Oh my! Oh my! There is a doom approaching. Mark me! A doom! No, I cannot speak of it...cannot utter their names or they may hear me! But if we learn, yes, if we learn more of them...then maybe we can learn how to foil them!"] = "Oh je! Oh je! Unheil naht! Hört auf mich! Unheil! Nein, ich darf nicht darüber sprechen... darf nicht ihre Namen aussprechen, sie könnten mich hören!",
    ["Oh, you know what? That reminds me. You wanna finish up a little job I took up while I was in Tanaris? It's easy... Krinkle Goodsteel in Gadgetzan was lookin' for some stuff found here in Searing Gorge and a few other places."] = "Ach, wisst Ihr was? Da fällt mir grade was ein. Wo ich doch immer noch hier drin festsitz: Wollt Ihr nich' vielleicht 'n kleinen Job für mich fertig machen, den ich angenommen hab, als ich in Tanaris war? Is' auch ganz einfach... na ja, wenn man nich' grade hier drin sitzt, jedenfalls.",
    ["Oh...the flowers are blooming in Hillsbrad and the air is so fresh and brisk. I can't help but to wallow in the misery of it all. I look out my grimy window and long for the day when our New Plague brings this world the death it deserves."] = "Oh, <name>..., in Hillsbrad blühen die Blumen und die Luft ist so klar und rein. Ich muss in diesem ganzen Elend baden. Ich sehe aus meinem verdreckten Fenster und sehne den Tag herbei, an dem unsere neue Seuche dieser Welt ihren wohlverdienten Tod bringt.",
    ["Ok, everything is prepared and packed and ready for transport! Good luck in your journey, and make sure you tell Tinkee that she owes me!"] = "Gut, alles ist bereit und verpackt und transportfertig! Viel Glück auf Eurer Reise und richtet Tinkee aus, dass sie mir was schuldet!",
    ["One of Onyxia's own teeth, taken after she was finally dragged out of Stormwind's court and killed in her lair."] = "Oberanführer Runthak erwartet Eure Ankunft im Tal der Stärke.",
    ["One of Zandalar's legendary madcaps was Khar'vaxal the Cracked."] = "Khar'vaxal der Irrsinnige war einer der legendären Wildfänge der Zandalar.",
    ["One of my most observant scouts brings back word that the wreckage of Proudmoore's fleet still remains off the coast of Durotar, just east of Tiragarde Keep."] = "Einer meiner aufmerksamsten Späher hat mir Kunde gebracht, dass die Trümmer von Proudmoores Flotte immer noch an der Küste Durotars liegen, gleich östlich von Burg Tiragarde.",
    ["One of my scouts witnessed an attack on a caravan from Durotar. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout."] = "Einer meiner Späher war Zeuge eines Angriffs auf eine Karawane aus Durotar, <name>. Die Übeltäter waren in der Tat vom Grimmhauerstamm der Stacheleber. Ein ganz bestimmter Stacheleber führte den Überfall an: Kreenig Grantelschnauze.",
    ["One of our greatest struggles is obtaining the natural resources we need to survive. Gold was scarce even in the height of the Alliance's power."] = "Eine unserer größten Schwierigkeiten besteht darin, die Rohstoffe zu besorgen, die wir zum Überleben brauchen. Gold war schon zu Hochzeiten der Macht der Allianz selten.",
    ["Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch. Make haste to Wyrmbog in the south of Dustwallow Marsh."] = "Das Dorf Stonemaul wurde von der Brut von Onyxia überrannt. Aber warum sollte die Tochter des Schwarzen-Großdrache-Lords Deathwing über unser Land herfallen? Das ist sehr beunruhigend.",
    ["Our initial scouting reports of Silverpine show the rot hides have a base at an old farm to the north, the Dead Fields."] = "Unsere ursprünglichen Spähberichte über den Silberwald zeigen, dass die Moderfelle auf einer alten Farm im Norden, nahe dem Todesfeld, einen Stützpunkt haben.",
    ["Our power comes from darkness and shadow, but that is not your only role. You have acknowledged that there is merit in knowing the healing arts."] = "Unsere Macht beziehen wir aus der Dunkelheit und dem Schatten, <name>, doch das ist nicht Eure einzige Rolle. Ihr habt erkannt, dass es von Vorteil ist, sich in der Heilkunst auszukennen.",
    ["Out here in the wilderness, Kindal and I have meager means to reward your help, but we don't want you to feel unappreciated. Take my signet ring."] = "Hier draußen in der Wildnis haben Kindal und ich nur geringe Mittel, um Euch für Eure Hilfe zu entlohnen, aber wir wollen nicht, dass Ihr Euch nicht wertgeschätzt fühlt. Nehmt meinen Siegelring.",
    ["Overlord Runthak awaits your arrival in the Valley of Strength. Do not keep your public waiting, hero."] = "Oberanführer Runthak erwartet Eure Ankunft im Tal der Stärke. <Thrall salutiert euch.> Lasst Euer Publikum nicht warten, großer Held.",
    ["Past the Argent Dawn encampment of Light's Hope and west of Northdale, you will find the corpulent maggot beast, Borelgore. I've lost entire regiments to that monster."] = "Hinter der Hoffnung des Lichts, dem Lager der Argentumdämmerung, und westlich von Northdale, findet Ihr die wohlbeleibte Madenbestie Blutschlinger. Ich habe ganze Regimenter an dieses Monster verloren.",
    ["Perhaps you know the pain of uncertainty, perhaps not. But know this: I stand here every day, from the sun's rising till its decline, scouring the horizon for more of those monsters."] = "Vielleicht kennt Ihr diesen Schmerz der Ungewissheit, <class>, vielleicht auch nicht. Doch wisset: Ich stehe hier jeden Tag, vom Aufgang der Sonne bis zu ihrem Untergang, und suche den Horizont nach diesen Monstern ab.",
    ["Please help! These creatures are going to eat me! Help me out of here, and I'll give you a great treasure! It's in my camp in the swamp north of Stonard, but it's locked in a strongbox that can be opened through a trick that only I know."] = "Bitte helft! Diese Kreaturen werden mich fressen! Helft mir hier raus und ich gebe Euch einen großen Schatz! Er ist in meinem Lager im Sumpf im Norden von Stonard, aber in einer Geldkassette eingeschlossen, die man mit einem Trick öffnet, den nur ich beherrsche.",
    ["Please, return to Duthorian and let him know that I'm safe for now. I have you and the Church to thank for that. He'll send word to Ironforge to let my Jordan know that he has nothing to fear."] = "Ich wette, die kommen bald wieder, also macht Euch bereit. Ich habe eine Schusswaffe im Haus. Ich hole sie und helfe Euch gern, aber Ihr werdet weitgehend auf Euch gestellt sein.",
    ["Please, take from this a relic of old. We no longer have a use for the item. May it serve you well in your fight against the legion."] = "Bitte, nehmt Euch ein Relikt der Vergangenheit. Wir haben für den Gegenstand keine Verwendung mehr. Möge es Euch in Eurem Kampf gegen die Legion gute Dienste leisten.",
    ["Poor Heralath! And this dwarf... Lonebrow. What a brave soul he was. We must not let their valiance go for naught. This crone... Charlga Razorflank..."] = "Armer Heralath! Und dieser Zwerg... Lonebrow. Was war er doch für eine mutige Seele. So viel Heldenmut darf nicht umsonst gewesen sein. Diese Greisin... Charlga Razorflank...",
    ["Powerful warrior and awkward novice alike have fallen to the venomous sting of the scorpid. You will find large numbers of scorpids northwest of here."] = "Sowohl mächtige Krieger als auch tollpatschige Anfänger fallen dem Giftstachel der Skorpiden zum Opfer. Nordwestlich von hier findet Ihr eine größere Ansammlung Skorpiden.",
    ["Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose."] = "Nach dem Öffnen der Front der Steuerkonsole zeigt sich ein dichtes Gewirr aus Kabeln, Schläuchen und anderen seltsamen, mechanischen Objekten - die meisten davon scheinen keinen praktischen Nutzen zu haben.",
    ["Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon."] = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.",
    ["Quite impressive. The crystal of Zin-Malor can never be returned to the temple which, as you know, lies in ruin. But I believe that your effort to undo the evil of the past should not go unrewarded."] = "Recht eindrucksvoll, <name>. Der Kristall von Zin-Malor kann niemals in den Tempel zurückgebracht werden, der, wie Ihr wisst, nur noch eine Ruine ist. Aber ich finde, dass Eure Bemühung, das Böse der Vergangenheit ungeschehen zu machen, nicht ohne Belohnung bleiben soll.",
    ["Rackmore's log tells of how his ship was sailing for Feathermoon Stronghold when it was attacked by seafaring creatures."] = "Aus Rackmores Logbuch geht hervor, dass sein Schiff zur Festung Feathermoon segelte, als es von seefahrenden Kreaturen angegriffen wurde.",
    ["Razelikh's lair is atop the highest mountain in the Blasted Lands. The only way to the lair is through the use of the teleport runes near the mountain."] = "Razelikhs Unterschlupf befindet sich auf dem Gipfel des höchsten Berges in den verwüsteten Landen. Einzig durch Einsatz der Teleport-Runen in der Nähe des Berges kann man zu diesem Unterschlupf gelangen.",
    ["Ready to go? First, we need to get this powder to Ironband. It'll be a lot for me to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for me."] = "Bereit zum Aufbruch, <name>? Als Erstes müssen wir dieses Pulver zu Ironband bringen. Für mich allein wäre es zu viel zu tragen und diese Gegend kann gefährlich werden - und wer weiß, was diese Dunkeleisenzwerge noch für mich bereithalten?",
    ["Recently, a new group of thieves has been hanging around Northshire. They call themselves the Defias Brotherhood, and have been seen across the river to the east."] = "Seit kurzem treibt sich eine neue Diebesbande in Nordhain herum. Sie nennen sich die \"Bruderschaft der Defias\" und sind auf der anderen Seite des Flusses im Osten gesehen worden.",
    ["Recently, just before the Troggs surfaced within the site, we had uncovered a large number of strange, carved idols. But we didn't have the chance to study them, for soon after their discovery the Troggs chased us away from the ruins!"] = "Vor einer Weile, kurz bevor die Troggs in der Stätte auftauchten, hatten wir eine große Anzahl seltsame, verzierte Götzen gefunden. Leider hatten wir keine Gelegenheit, sie zu untersuchen, denn kurz nach ihrer Entdeckung haben uns die Troggs aus den Ruinen verjagt.",
    ["Relara's fever has passed, but she is still very weak. I do not believe time alone will give her back the strength she has lost. I believe it will take the power of a moonstone."] = "Relara hat kein Fieber mehr, aber sie ist immer noch sehr schwach. Ich glaube nicht, dass sie wieder zu Kräften kommt, wenn wir einfach nur abwarten. Ich glaube, dazu bedarf es der Kraft eines Mondsteins.",
    ["Reports from my superiors in Brill indicate that an agent of the Scarlet Crusade was dispatched from the Scarlet Monastery and sent here to Deathknell."] = "Berichte meiner Vorgesetzten in Brill weisen darauf hin, dass ein Agent des Scharlachroten Kreuzzugs vom Scharlachroten Kloster hierher nach Deathknell entsendet wurde.",
    ["Return to Belgrom in Orgrimmar. He will want to see her head for himself! We'll return there shortly. Ah, this is indeed a good day. Thank you for your help."] = "Kehrt zu Belgrom nach Orgrimmar zurück. Er wird ihren Kopf höchstpersönlich sehen wollen. Wir werden in Kürze dorthin zurückkehren. Ah, dies ist heute wahrlich ein Freudentag. Danke für Eure Hilfe, <name>.",
    ["Return to my mate, Primal Torntusk at Revantusk Village. Tell her that I am coming home! She is sure to reward you."] = "Kehrt zu meiner Gefährtin Primal Torntusk in Revantusk zurück. Richtet ihr aus, dass ich heimkehren werde! Sie wird Euch sicherlich belohnen.",
    ["Return to your own tribe and let them know of your victory here. Show them your trophy, and bask in the glory..."] = "Kehrt zu Eurem eigenen Stamm zurück und lasst ihn von Eurem Sieg hier wissen. Zeigt ihm Eure Trophäe und sonnt Euch in Eurem Ruhm...",
    ["Scarlet Crusaders have been raiding from the ruined tower in northern Tirisfal, past Faol's Rest. According to the information we have, a ruthless commander named Captain Melrache is in charge of this evil crew."] = "Scharlachrote Kreuzzügler haben vom verfallenen Turm im nördlichen Tirisfal, hinter Faols Ruheplatz, Überfälle ausgeführt. Nach den Informationen, die wir haben, führt ein unbarmherziger Kommandant mit Namen Captain Melrache diese bösartige Truppe an.",
    ["Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure! But it remains that I cannot make the trek back to the Den unassisted."] = "<class>! Ich dachte schon, ich müsste hier draußen sterben und niemand würde es bemerken. Auf der Jagd nach den Skorpiden des Tals stieß ich auf ein besonders heimtückisches Exemplar. Ich stürzte mich auf ihn und konnte einer seiner Klauen einen ordentlichen Draufschlag versetzen, bevor sie sich um mein Bein schloss.",
    ["Sergeant Bly stole from me! He said he'd only borrow it, but he stole my cherished divino-matic rod!! Without that rod how will I know where to dig new water holes??"] = "Sergeant Bly hat mich bestohlen! Er sagte, er wolle sie sich nur ausleihen, aber er hat meine geliebte Wünschel-mato-Rute gestohlen! Wo soll ich denn bitte ohne diese Rute wissen, wo ich neue Wasserlöcher graben muss?",
    ["Shadowfang Keep holds a book, the Book of Ur, which would be much prized in my collection. Ur was a great mage of Dalaran before the coming of the Scourge, his studies in other worlds are of much value to..."] = "<name>, in der Burg Shadowfang gibt es ein Buch, das Buch von Ur, das ich unbedingt in meiner Sammlung haben möchte. Ur war einst ein großer Magier aus Dalaran bevor die Geißel kam.",
    ["Shortly after the fall of the Gurubashi, we Zandalar almost succumbed to a final defeat from evil within our own tribe."] = "Kurze Zeit nach dem Fall der Gurubashi wurden wir Zandalarianer fast endgültig vom Bösen innerhalb unseres Stammes besiegt.",
    ["Small timberlings are sprouting around the waters of Lake Al'Ameth. I'm afraid these sprouts are beyond help -- we should try to clear them from the land before they grow large enough to cause trouble."] = "Kleine Bäumlinge sprießen rund um das Wasser des Al'Amethsees. Ich fürchte, dass man diesen Schösslingen nicht mehr helfen kann - wir sollten versuchen, sie auszureißen, bevor sie groß genug sind, um Probleme zu bereiten.",
    ["So excited I am! Three little cages for three little elves! But what shall we do with our lovely tree-hugging friends? Why, let's give them a taste of..."] = "Ich bin ja so aufgeregt! Drei kleine Käfige mit drei kleinen Elfen! Aber was tun wir nur mit unseren süßen Baumschützer-Freunden? Na, lassen wir sie doch...",
    ["So you're looking for an altar of some sort? Well, I'm no expert on troll ruins like my father, but I have heard about a sunken troll city out near that island you're looking for."] = "Ihr sucht also nach einer Art Altar? Nun, ich bin zwar kein Experte für Trollruinen wie mein Vater, aber ich habe von einer versunkenen Trollstadt nah bei der Insel gehört, die Ihr sucht.",
    ["So, the time is now then? I appreciate your efforts, and if the situation does not lend itself, then allow me to thank you now for everything you've done for me and my family."] = "Also ist die Zeit gekommen? Ich weiß Eure Bemühungen zu schätzen, und wenn auch die Situation dafür nicht geeignet ist, lasst mich Euch jetzt für alles danken, was Ihr für mich und meine Familie getan habt.",
    ["Something evil is brewing in the forests of Teldrassil. Look long the hills to where the peaceful furbolgs used to dwell. They have deserted their homes and are amassing under the name of the Gnarlpine tribe."] = "Etwas Böses braut sich im Wald von Teldrassil zusammen. Schaut Euch die Hügel an, in denen die friedlichen Furbolgs früher hausten. Sie haben ihre Heime verlassen und sammeln sich unter dem Banner des Knarzklauenstamms.",
    ["Stalvan Mistmantle led a life of depravity. Innocent victims died by his hand. Undoubtedly he is guilty of countless crimes. Now the lunatic threatens Darkshire."] = "Stalvan Mistmantle hat ein Leben der Verworfenheit gelebt und unschuldige Opfer starben von seiner Hand. Zweifellos hat er noch zahllose andere Verbrechen begangen und nun wird Dunkelhain von diesem Wahnsinnigen bedroht. Das Licht allein weiß, welche schmutzigen Pläne er jetzt ausheckt. Deswegen brauche ich Eure Hilfe, <class>.",
    ["Stormwind has abandoned us. A foul wind of depravity rustles through the plains of Westfall. This was my homeland and I will not turn my back on the citizens who choose to remain here."] = "Stormwind hat uns im Stich gelassen. Der üble Gestank der Verderbtheit weht über die Ebenen von Westfall. Dies war und ist mein Heimatland und ich werde die Bürger, die sich zum Bleiben entschlossen haben, nicht verlassen.",
    ["Such a shame the land is in such shambles. But the Memorial came out quite well!"] = "Ah, welch edle Steine doch aus Lordaeron kommen. Was für eine Schande, dass in diesem Land ein solches Chaos herrscht.",
    ["Sure enough, deep within the Old Jug there is another clue to Sander's treasure."] = "Und tatsächlich, ganz unten, fast am Boden des alten Henkelkruges findet sich der nächste Hinweis auf Sanders Schatz.",
    ["Take Karnitol's things back to Roetten in Ironforge and he'll pay you for a job well done. Haha, if you're not careful, he's gonna be so pleased with ya that he'll ask you to join us full time."] = "Ihr überlegt eine Weile, was die Kiste aufgebrochen haben könnte, und bemerkt an den Seiten und am Deckel lange, tiefe Kratzer, die belegen, dass sich etwas anderes als ein Mensch oder Riese dafür interessierte. Solche Spuren scheinen nicht von einem Dolch oder Schwert verursacht worden zu sein.",
    ["Take Lok's head to Thork in the Crossroads. He should know what has happened to my tribe without any words--ha, not that he would believe Mangletooth helped in such things."] = "Bringt Loks Kopf zu Thork in Crossroads, <Volk>. <schnaubt> Er sollte ohne Worte wissen, was meinem Stamm zugestoßen ist - ha, nicht dass er denken würde, Quetschzahn hätte bei <schnaubt> solchen Dingen geholfen.",
    ["Take this Nether Gem to my old comrade Bethor. It will let us communicate... and I have much to tell him."] = "Bringt meinem alten Kameraden Bethor diesen Netheredelstein. Er wird uns ermöglichen, miteinander zu kommunizieren... und ich habe ihm eine Menge zu erzählen.",
    ["Take this letter back to Stormwind and let Malin know that Kryten an' I'll be home soon. He'll reward you well for helping us here, of that I've no doubt."] = "Bringt diesen Brief nach Stormwind und lasst Malin wissen, dass Kryten und ich bald wieder zu Hause sind. Ich zweifle nicht daran, dass er Euch reichlich für Eure Hilfe uns gegenüber belohnen wird, <name>.",
    ["Take this refined and purified Incendia powder to Thousand Needles and toss it on the sacred fire of life. It is located in the Darkcloud Pinnacle on an isolated needle where they bury their dead."] = "Bringt dieses aufbereitete und geläuterte Brandpulver nach Tausend Nadeln und werft es in das hochheilige Feuer des Lebens. Es befindet sich beim Düsterwolkengipfel auf einer isolierten Nadel, wo sie ihre Toten beerdigen.",
    ["Take this sealed commendation to Varimathras in the Undercity."] = "Da Ihr mit solcher Verbissenheit und Ehre in der Schlacht von Hillsbrad gekämpft habt, habe ich für Euch diese Belobigung geschrieben, in der Eure Heldentaten im Kampf angemessen gerühmt werden, sodass das Oberkommando sie anerkennt.",
    ["Talk to my friend, Furen Longbeard, in the Dwarven District of Stormwind. He's the best shieldsmith you'll ever meet, and he owes me a big favor."] = "Ihr habt echt gezeigt, aus welchem Holz Ihr geschnitzt seid, als Ihr am Rethbanspießrutenlauf teilgenommen habt, <name>. Und ich stehe zu meinem Wort.",
    ["Tampering of the timeline by a sinister force - most likely the Scourge - has occurred in Andorhal! I can try to keep the passage of time here intact and mend what has been damaged, but I'll need your help to do so uninterrupted."] = "Die Zeitlinie in Andorhal wurde durch eine finstere Kraft verfälscht - wahrscheinlich durch die Geißel! Ich kann versuchen, das Verstreichen der Zeit hier in den Griff zu bekommen und den Schaden zu beheben, aber dazu benötige ich Hilfe, damit ich dabei nicht gestört werde.",
    ["Targorr the Dread served under Gath'Ilzogg as supreme Executioner. His methods were ruthless, even by filthy orc standards. Men who fought bravely to defend the Kingdom were tortured on his whim."] = "Targorr der Schreckliche diente als oberster Exekutor unter Gath'llzogg. Er ging grausam vor, selbst nach den Standards der dreckigen Orcs. Menschen, die tapfer gekämpft hatten, um das Königreich zu verteidigen, wurden nur zu seiner Belustigung gefoltert.",
    ["Thanks again for your help. Here's a bottle of Steamwheedle bilge rum. Take it to MacKinley and he can finally put to rest his crazy beliefs about Booty Bay booze."] = "Danke nochmals für Eure Hilfe, <name>. Hier habt Ihr eine Flasche Steamwheedle-Bilge-Rum. Bringt sie zu MacKinley und er wird endlich seine verrückten Ansichten über Drinks aus Booty Bay über Bord werfen können.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Icebane bracers."] = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, Eisflucharmschienen herzustellen.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Icy Scale gauntlets."] = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, Eisschuppenstulpen herzustellen.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Polar bracers."] = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, Polararmschienen herzustellen.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Polar gloves."] = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, Polarhandschuhe herzustellen.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create an Icebane breastplate."] = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, eine Eisfluchbrustplatte herzustellen.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create an Icy Scale breastplate."] = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, eine Eisschuppenbrustplatte herzustellen.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Glacial gloves."] = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, Gletscherhandschuhe herzustellen.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Glacial wrists."] = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, einen Gletscherhandschutz herzustellen.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Icebane gauntlets."] = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, Eisfluchstulpen herzustellen.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Icy Scale bracers."] = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, Eisschuppenarmschienen herzustellen.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create a Glacial cloak."] = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, einen Gletscherumhang herzustellen.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create a Polar tunic."] = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, eine Polartunika herzustellen.",
    ["That beached creature is not an isolated incident here in Darkshore. There are more along the coastline and even in the water."] = "Die gestrandete Kreatur ist kein Einzelfall hier in Dunkelküste. Entlang der Ufer und sogar im Wasser gibt es noch mehr davon.",
    ["That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."] = "Das ist ja eine unglaubliche Geschichte, <name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.",
    ["That's fascinating! I have always wondered about the truth... Well, you must share this knowledge, definitely! Go to Arch Druid Fandral Staghelm right away -- you'll find him in Darnassus, in the Cenarion Circle."] = "Das ist faszinierend! Ich habe mich immer gefragt, was die Wahrheit ist... Nun, Ihr müsst dieses Wissen auf alle Fälle teilen! Geht sofort zum Erzdruiden Fandral Staghelm.",
    ["The Agamand Mills area has become a foothold for the Scourge. Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered."] = "Die Gegend um Agamands Mühlen hat sich zu einem Außenposten der Geißel entwickelt. Am stärksten sind sie in der Gruft der Familie Agamand, wo ihr örtlicher militärischer Anführer, ein Skelett namens Captain Dargol, sein Hauptquartier hat.",
    ["The Battleboars of Brambleblade Ravine to the east are encroaching on our tribal hunting grounds. They are trained to be malicious by the Bristleback Quilboars with whom we are at war."] = "Die Kampfeber der Dornrankenklamm im Osten sind in unser Stammesjagdterritorium eingedrungen. Sie wurden von den Borstennackenstachelebern, mit denen wir uns im Krieg befinden, abgerichtet, niederträchtig zu sein.",
    ["The Bloodfuries have been subdued. But they will regroup soon enough if action is not taken. Far south of the Barrens lies a land known as Thousand Needles."] = "Die Blutfurien wurden besiegt. Sie werden sich jedoch schon bald wieder neu gruppieren, wenn wir nichts unternehmen. Ganz weit im Süden des Brachlandes liegt ein Land, das als Tausend Nadeln bekannt ist.",
    ["The Brackwells have a prize-winning pig, Princess. The sow is HUGE, and she got that way from sneaking over here and eating my veggies! So before she comes to our fields...Princess must die!"] = "Die Brackwells haben ein Schwein, eine Sau namens Prinzessin, die schon viele Preise gewonnen hat. Dass dieses Tier so riesig geworden ist, das kommt nur daher, dass es immer hier herübergeschlichen kommt und mein Gemüse frisst! Und deswegen muss Prinzessin sterben, bevor sie wieder unsere Felder heimsucht!",
    ["The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager. The villains! They don't deserve such a fine brew!, I have a tough task for you."] = "Die Dunkeleisenzwerge, angeführt von dem Bösewicht Hurley Pestatem, haben eines der besten Rezepte der Donnerbräus gestohlen, jenes für das Donnerbräu Lagerbier. Diese Schurken! Sie verdienen ein solch edles Gebräu nicht!",
    ["The Defias Front is constantly shifting. I've been following their movements for quite some time now. On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear."] = "Die Defias sind ständig in Bewegung. Ich überwache ihre Aktivitäten jetzt schon seit einiger Zeit. Und dabei habe ich festgestellt, dass viele Bandenmitglieder an den roten Lederkopftüchern zu erkennen sind, die sie tragen.",
    ["The Defias gang in Northshire wears burlap masks, but the Defias in Elwynn wear linen which I can use to make fine linen goods."] = "Die Mitglieder der Defias in Nordhain tragen Masken aus Sackleinen, die Masken der Defias in Elwynn dagegen sind aus gutem Leinen, aus dem ich Qualitätsleinenwaren herstellen kann.",
    ["The Demon Seed is a powerful tool for the Burning Legion. It rests in a cave on Dreadmist Peak, above a demonic altar of fire. I have prepared power stones that when placed near the Seed will disrupt its connection to the Legion."] = "Die Dämonensaat ist ein mächtiges Werkzeug der Brennenden Legion. Sie lebt in einer Höhle des Glutnebelgipfels, oberhalb eines dämonischen Altars des Feuers. Ich habe Kraftsteine vorbereitet, die, wenn sie in der Nähe der Saat platziert werden, deren Verbindung zur Legion unterbrechen.",
    ["The Earthen Ring had pure intentions towards our plagued brethren. But who is to know the motivations of those whispering in the ears of the Elder Council?"] = "Der irdene Ring hatte nur die besten Absichten, was unsere geplagten Brüder betraf. Aber wer weiß schon, welche Absichten jene verfolgen, die dem Ältestenrat Dinge einflüstern?",
    ["The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements. They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know."] = "Der Irdene Ring ist eine schamanistische Gruppe, die sich dem Studium und dem Erhalt der Elemente widmet. Sie hat bereits mehr über verrückte alte Götter und uralte Legenden und Lehren vergessen, als die meisten Gelehrten jemals in Erfahrung bringen werden.",
    ["The Embalmer is a name told in one of our children's stories. He was a kindly alchemist, driven mad by the death of his wife, Eliza. To restore her, he used dark magic to place his own heart within the bosom of his dead spouse."] = "Der Einbalsamierer... diesen Namen kennen wir aus einer Geschichte, die wir unseren Kindern erzählen. Er war ein freundlicher Alchimist, den der Tod seiner Frau Eliza in den Wahnsinn trieb.",
    ["The Gelkis Khan is dead, and now the Maraudine will fall! Kill the Maraudine Khan, Hratha! To face him, blow the horn on the high bluff in the Valley of Spears."] = "<name>, Ihr habt uns gegen die Magram geholfen. Jetzt helft uns dabei, die Maraudine zu schlagen! Tötet den Anführer ihres Klans, Khan Hratha!",
    ["The Kolkar are a threat to the Horde's claims in the Barrens; we must reduce the numbers of their troops. And so, I have a bounty task for you."] = "Die Kolkar sind eine echte Bedrohung für die Besitzansprüche der Horde im Brachland und wir müssen deren Truppen unbedingt dezimieren. Deshalb habe ich eine lohnenswerte Aufgabe für Euch.",
    ["The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came."] = "Die Massengräber südwestlich von Garrens Schlupfwinkel weiter im Norden wurden geschaffen, um der...",
    ["The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong."] = "Die Qiraji und ihre Diener besitzen Gegenstände, die aus dem seltensten und feinsten Material hergestellt werden: Knochen von riesengroßen uralten Kreaturen, Edelsteine aus den Tiefen der Erde, reines und starkes Metall.",
    ["The Razormane quilboars to the south, beyond the Field of Giants, have no skilled blacksmiths from what I am told, but they've apparently started to develop sturdier weapons."] = "Die Stacheleber des Grimmhauerstamms im Süden, hinter dem Feld der Riesen, haben keine erfahrenen Schmiede, soweit ich weiß, aber Sie haben anscheinend begonnen, stabilere Waffen zu entwickeln.",
    ["The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff. First you must pass the Rite of Strength."] = "Die Riten der Erdenmutter sind die Schritte, die ein junger Tauren gehen muss, um sich in Thunder Bluff Respekt zu verschaffen. Ihr müsst zuerst den Ritus der Kraft bestehen.",
    ["The Scourge are trying to form a base at the Agamand Mills. If they do, then they can stage further attacks within Tirisfal. The orders have been given."] = "Die Geißel versucht, bei Agamands Mühlen einen Stützpunkt zu errichten. Wenn ihnen das gelingt, können sie weitere Angriffe innerhalb von Tirisfal unternehmen. Es wurden klare Befehle erteilt.",
    ["The Silver Stream Mine to the east ran dry long ago. It was converted by the Miners' League into a storage depot, but now Kobolds have moved in, putting their filthy paws on good, Dwarven tools!"] = "Die Silberbachmine im Osten hat sich schon vor langer Zeit erschöpft. Sie wurde vom Bund der Bergarbeiter in ein Lagerhaus umgewandelt, aber jetzt sind dort Kobolde eingezogen und befingern mit ihren schmutzigen Pfoten gute zwergische Werkzeuge!",
    ["The Stormwind Army has placed a bounty on murloc lurkers and foragers in Elwynn. Slaughter them and bring me their torn murloc fins, and the Stormwind Army will reward you well."] = "Die Armee von Stormwind hat ein Kopfgeld auf die Murloclauerer und Murlocfutterwühler ausgesetzt, die sich in Elwynn herumtreiben. Erlegt sie und bringt mir ihre zerrissenen Murlocflossen, dann wird die Armee von Stormwind Euch ansehnlich belohnen Die Murlocs haben am Steinhügelsee nördlich von hier ein Dorf errichtet und ein weiteres ihrer Dörfer befindet sich im Süden, wo der Fluss sich teilt.",
    ["The Syndicate in Stromgarde do battle with our contingent of militia there."] = "Das Syndikat in Stromgarde bekämpft das Kontingent unserer Miliz dort.",
    ["The Timbermaw are the only furbolg tribe to escape the corruption. However, many other races kill furbolg blindly now, without bothering to see if they are friend or foe."] = "Die Furbolgs der Holzschlundfeste sind die einzigen Furbolgs, die von der Verderbnis verschont blieben. Aber viele andere Völker töten die Furbolgs jetzt blindwütig und scheren sich nicht darum, ob sie Freund oder Feind sind.",
    ["The Timbermaw tend to stay to themselves. While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible."] = "Die Furbolgs der Holzschlundfeste bleiben meist unter sich, <name>. Wir gewähren allen, die ihre Vertrauenswürdigkeit unter Beweis gestellt haben, freies Geleit, meiden aber, wenn möglich, andere Furbolgstämme.",
    ["The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."] = "Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.",
    ["The Venture Company has a string of operations through Stranglethorn which keeps hard-working goblins, like me, from making honest gold! Please, you must help me!"] = "Die Venture Company hat ein paar Sachen im Schlingendorntal am Laufen, die hart arbeitende Goblins, wie ich es einer bin, davon abhalten, ehrliches Gold zu verdienen. Bitte, Ihr müsst mir helfen!",
    ["The Vilebranch fight with supernatural ferocity. This is due to the foul magical weavings of the Vile Priestess Hexx. Throughout Jintha'alor you will find dark vessels of tainted blood."] = "Die Vilebranch kämpfen mit übernatürlicher Wildheit. Dies liegt an der elenden Magie, die von der üblen Priesterin Hexx gewirkt wird. Ihr werdet in ganz Jintha'Alor dunkle Gefäße mit besudeltem Blut finden.",
    ["The amount of salve made out of the reagents you brought me is good enough for ten doses. While I work with the village to try and make some more salve, I'd like for you to help us get a head start."] = "Die Salbe, die ich aus den Reagenzien herstellen konnte, die Ihr mir gebracht habt, reicht für zehn Dosen, <name>. Ich arbeite weiter mit den Dorfbewohnern zusammen und versuche mehr Salbe herzustellen.",
    ["The antidote is ready. Please see that Iverron drinks it. There is something that you should know -- the antidote -- it will only remain viable for 5 minutes."] = "Wir dürften in der Lage sein, Iverron zu helfen, denn ich kenne ein Gegengift, das gegen das Gift wirkt. Bevor ich es herstellen kann, benötige ich allerdings einige Zutaten. Ich brauche Hyazinth-Pilze.",
    ["The augurs of the Zandalar all wear a distinctive chest piece called a hauberk."] = "Die Weissager der Zandalar tragen einen bestimmten Brustschmuck, der Halsberge genannt wird.",
    ["The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show. You'd be wise to hold on to them."] = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Burg Cenarius erhalten habt, dienen zu weit mehr als der Angeberei, <name>. Ihr solltet deren Wert besser zu schätzen wissen.",
    ["The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show. You'd be wise to hold on to them."] = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Windruferin Proudhorn erhalten habt, dienen zu weit mehr als der Angeberei, <name>. Ihr solltet deren Wert besser zu schätzen wissen.",
    ["The confessors of the Zandalar all wear a distinctive mantle, marking them as the preservers of the tribe."] = "Alle Glaubenshüter der Zandalar tragen einen bestimmten Mantel, der sie als Beschützer des Stammes auszeichnet.",
    ["The crystal caverns of Terramok lie to the west, deep within Maraudon... It is an ancient place with much history. And I am looking to get my hands on some of it."] = "Die Kristallhöhlen von Terramok liegen im Westen, tief in Maraudon... Das ist ein uralter Ort mit einer langen Geschichte. Und ich will einiges davon in die Hände bekommen, <class>.",
    ["The defeated water elemental has left behind a strange water globe. You surmise that the object somehow fed the beast energy. Inside the globe, a putrid-looking form of water sloshes about."] = "Der besiegte Wasserelementar hat eine seltsame Wasserkugel zurückgelassen. Ihr vermutet, dass das Objekt die Kreatur irgendwie mit Energie versorgte. In der Kugel schwappt eine faulig aussehende Wassergestalt herum.",
    ["The demoniac seeks to embody power outright, not just possess it."] = "Der Besessene möchte Macht geradewegs verkörpern und nicht nur besitzen.",
    ["The druids built the Talon Den on Stonetalon Peak, where they keep many powerful items. They devised a complex scheme to keep them from falling into the wrong hands."] = "Die Druiden errichteten den Krallenbau auf dem Steinkrallengipfel, in dem sie viele mächtige Gegenstände aufbewahren. Sie haben sich ein komplexes Schema ausgedacht, damit sie nicht in die falschen Hände gelangen.",
    ["The druids in the Wailing Caverns, the Druids of the Fang, are an aberration. They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams."] = "Die Druiden in den Höhlen des Wehklagens, die Druiden des Giftzahns, sind eine Verirrung der Natur. Einst gehörten sie einem Orden edler Druiden an, deren Plan es war, das Brachland zu heilen, doch jetzt trachten sie danach, das Land ihren eigenen verderbten Träumen gleichzumachen.",
    ["The fight goes well. Perhaps the Warchief will allow us to return to our homes before the seasons change if we continue to make such great strides in our battle against the demons and their underlings."] = "Seid still, <name>, und lasst mich Euch etwas Wichtiges über unser Volk sagen, das nicht auf der Hand liegt. Wir sind ein stolzes Volk und der Krieg gegen die Menschen hat selbst Thralls große Geduld auf die Probe gestellt.",
    ["The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead."] = "Als Erstes werden wir Euer Rückgrat etwas kräftigen. Ich könnte Euch ins Brachland schicken, um Kodos zu jagen, aber mal ehrlich, lebend seid Ihr uns nützlicher als tot.",
    ["The following items have been stolen: *One Dark Iron Tuyere. *One Lookout's Spyglass. A reward is being offered to individuals who find and return these pilfered items."] = "Folgende Gegenstände wurden gestohlen: Eine Schmiedewindform. Ein Ausguck-Handfernrohr. Es wurde eine Belohnung für das Zurückbringen der gestohlenen Gegenstände ausgesetzt.",
    ["The future is inevitable! We hurl ourselves towards it like falling raindrops to the Great Sea. But perhaps, by studying the past, we can know what to expect and be better prepared for the unknown."] = "Die Zukunft ist unausweichlich! Wir stürzen ihr entgegen wie Regentropfen, die auf das große Meer prasseln. Aber vielleicht erfahren wir, indem wir die Vergangenheit studieren, was uns erwartet, und könnten uns besser auf das Unbekannte vorbereiten.",
    ["The gems that adorn Qiraji idols would work quite well, as their quality is superior. Bring me the ring and idols and I'll create a powerful ring for you."] = "Man sagt, dass die Ringe, die von den Lieutenants der Qiraji getragen werden, ungeheuere Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.",
    ["The gnome's voice crackles once again from the robot: \"I need to move OOX-09/HL to an open, safe place so it can begin a lengthy take-off procedure."] = "Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms: \"Ich muss OOX-09/HL an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann.",
    ["The gnome's voice crackles once again from the robot: \"I need to move OOX-17/TN to an open, safe place so it can begin a lengthy take-off procedure."] = "Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms: \"Ich muss OOX-17/TN an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann.",
    ["The gnome's voice crackles once again from the robot: \"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure."] = "Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms: \"Ich muss OOX-22/FE an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann.",
    ["The grand Isha Awak is lord of these waters. Great is his strength, and solemn his pride. The humans on the coast fear him, for he has consumed many of their number."] = "Isha Awak ist der Herr über diese Gewässer. Groß ist seine Kraft und edel sein Stolz. Die Menschen an der Küste fürchten ihn, denn er hat großen Schaden unter ihnen angerichtet.",
    ["The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed! My family is gone, taken by the plague."] = "Die Hure! Das Flittchen! Kenata lebt noch; ihre Familie blüht und gedeiht, während ich leide. Verlassene, wahrhaftig! Meine Familie wurde Opfer der Seuche.",
    ["The head of the beast is ready to be taken off... with great force. You have shown every sign that you are able to help us with this final mighty blow."] = "Eure Kraft ist offensichtlich, <name>. Dann zeigt mal, wie Ihr Euch mit echten Feinden schlagt. Die Felsfaustoger haben einen Unterschlupf südwestlich von hier, Richtung der Zwergenbrücke, und, wenn ich mich nicht täusche, werden die Raufer und Magi dort eine etwas größere Herausforderung darstellen - für uns waren sie das bislang zumindest.",
    ["The herbs of the Barrens are not quite like herbs in other lands. Their properties are mostly the same, but the oasis water here alters the plants; they are just slightly different."] = "Die Kräuter des Brachlandes sind anders als Kräuter anderer Länder. Ihre Eigenschaften sind zwar fast dieselben, aber das Oasenwasser hier verändert die Pflanzen; sie sind ein klein bisschen anders.",
    ["The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power."] = "Die angreifenden Stormpike sind nicht die einzige Bedrohung in dieser Region, Soldat. Der Krieg in diesem Tal tobt an zwei Fronten. Den kannibalistischen Winteraxtrollen dürstet es ebenso nach Macht.",
    ["The keg fizzles slightly."] = "Das Fässchen zischt ein wenig.",
    ["The last report I received from Agmond is troubling, more so now that he's dead! He mentioned that his diggers uncovered \"ancient urns\" at the dig site outside Uldaman."] = "Der letzte Bericht, den ich von Agmond erhalten habe, ist sehr beunruhigend, umso mehr, da er jetzt tot ist! Er erwähnte, dass seine Buddler an der Grabungsstätte vor Uldaman \"uralte Urnen\" entdeckt hätten.",
    ["The lifeless hand of the tauren druid clutches a surprisingly healthy looking oaken branch. Examining the branch reveals glyphs of a druidic nature carved into the bark."] = "Die leblose Hand des Tauren hält einen erstaunlich gesund aussehenden Eichenast umklammert. Als Ihr den Ast untersucht, entdeckt Ihr Glyphen druidischer Art, die in die Rinde geritzt sind.",
    ["The light slowly fades, the sword Trol'kalar, held within a stone sheath has been released."] = "Das Licht verglüht langsam, das Schwert Trol'kalar, das sich in einer steinernen Scheide befindet, ist freigegeben.",
    ["The madcaps of Zandalar are similar to rogues, but above all else they embrace madness..."] = "Die Wildfänge von Zandalar ähneln den Schurken, vertraut sind sie vor allem aber mit dem Wahnsinn...",
    ["The moment the artifact is removed from the Monolith, you feel the energy in the Stave of Equinex begin to fade."] = "In dem Moment, in dem das Artefakt vom Monolithen getrennt wird, fühlt Ihr, wie die Energie im Stock von Equinex sich zu verflüchtigen beginnt.",
    ["The moonwell water has revealed that embedded inside the crystal are a few small fragments of bone, as well as half of a jawbone."] = "Das Mondbrunnenwasser hat enthüllt, dass im Inneren des Kristalls einige kleine Knochenfragmente sowie ein Teil eines Kieferknochens eingebettet sind.",
    ["The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you."] = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.",
    ["The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of dominance and other minor components by and I'll create a set of powerful boots for you."] = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.",
    ["The parchment you found at the Master's Glaive is a page from an ancient text...written by elves!"] = "Das Pergament, das Ihr in der Meistergleve gefunden habt, ist eine Seite aus einem alten Text...",
    ["The pendant? Of course you can have it... Take it! I want no memory of him... just please, please leave in peace..."] = "Den Anhänger? Aber natürlich könnt Ihr ihn haben... Nehmt ihn! Nichts soll mich an ihn erinnern... nur bitte geht, bitte geht in Frieden...",
    ["The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity. Bring me the desecrated remnants of the departed along with reagents of purification and you shall know faith."] = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.> <Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.",
    ["The prison is ready. Now for the most difficult portion of this task. You must find and capture a Doomguard Commander within the Tainted Scar using this crystal prison."] = "Das Gefängnis ist bereit. Jetzt kommen wir zum schwierigsten Teil des Unterfangens. Ihr müsst mit Hilfe des Kristallgefängnisses einen Kommandanten der Verdammniswache in der faulenden Narbe finden und fangen.",
    ["The prized tunic of the Zandalar madcap is no exception, exuding the raw power of chaos and madness that they are able to channel."] = "Meine Augen haben mich schon seit langem im Stich gelassen, aber ich trauere ihnen nicht nach.",
    ["The ragged hide of Ghost Howl still bears a terrible wound, gained from the wolf's battles against the Burning Legion. Perhaps someone in Bloodhoof Village should know of Ghost Howl's demise...."] = "Der struppige Balg von Geistheuler trägt immer noch die schreckliche Wunde, die der Wolf im Kampf gegen die Brennende Legion davongetragen hat. Vielleicht weiß jemand in Bloodhoof, wie Geistheuler starb...",
    ["The raptors of the Barrens are smarter than raptors in other lands. And I think all that smarts is hiding in their horns!"] = "Die Raptoren des Brachlandes sind intelligenter als die Raptoren anderer Länder. Und ich glaube, dass ihre ganze Intelligenz in ihren Hörnern sitzt!",
    ["The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities. The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings."] = "Man sagt, dass die Ringe, die von den Lieutenants der Qiraji getragen werden, ungeheuere Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.",
    ["The sabercat's fur is a distinctive gray color, blending into the surrounding forest. As she lays there, you observe that she is badly wounded, with deep lacerations across her back and stomach."] = "Das Fell der Säblerkatze ist von einer auffälligen grauen Farbe, die sich nur wenig vom sie umgebenden Wald abhebt. Wie sie da liegt, erkennt Ihr, dass sie schwer verletzt ist und tiefe Wunden an Rücken und Bauchseite aufweist.",
    ["The spiders of the Searing Gorge are an invaluable source of shadow silk. As you know, shadow silk is highly sought after by the artisans of our trade."] = "Die Spinnen der sengenden Schlucht sind eine unschätzbare Quelle für Schattenseide. Wie Ihr wisst, ist Schattenseide bei den Fachleuten unseres Gewerbes heiß begehrt.",
    ["The survival of our people and lands comes at unfortunate costs. You have spilled the blood of nature's servants; many sick animals you have felled."] = "Das Überleben unseres Volkes und unserer Länder ist mit bedauerlichen Kosten verbunden, <name>. Ihr habt das Blut der Diener der Natur vergossen; viele kranke Tiere habt Ihr erledigt.",
    ["The terrible scorpid, Deathclasp, is believed to have retreated to the southern mountain range in the presence of increased silithid activity."] = "Man sagt, dass sich der grausame Skorpid Totenstachel nahe des südlichen Gebirgszuges wegen erhöhter Silithidenaktivität zurückgezogen hat.",
    ["The thunderhawk, is a fierce beast. It is time for you to face them. You must find where it roams, and bring me its wings as proof of your successful hunt."] = "Der Donnerfalke, <name>, ist eine ungestümes Wildtier. Es ist an der Zeit für Euch, ihm gegenüberzutreten. Ihr müsst herausfinden, wo er umherstreift, und mir seine Flügel als Beweis für Eure erfolgreiche Jagd bringen.",
    ["The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily."] = "Der Schatz befand sich so lange auf dem Meeresboden, dass die Edelsteine von einer dicken Kalkschicht umgeben sind. Aber die Macht, die in dieser Schutzbrille gefangen ist, wird Euch ermöglichen, sie leicht zu finden.",
    ["The ultimate symbol of a haruspex's power is what they wear."] = "Das ultimative Symbol der Macht eines Haruspex ist die Kleidung, die er trägt, <name>.",
    ["The ultimate symbol of power amongst the tribe is the garb we wear in battle. A demoniac's robes have fused fine runecloth and devastatingly powerful mojo into a single fabric."] = "Im Stamm ist das ultimative Zeichen für Macht die Kleidung, die im Kampf getragen wird. Die Roben des Besessenen vereinen feinen Runenstoff und verheerend mächtiges Mojo.",
    ["The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."] = "Der unaussprechliche alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.",
    ["The venom you gathered from the Witherbark's spider god is quite a find! I've been able to kill nearly two dozen rabbits with just a drop of the stuff."] = "Das Gift, das Ihr vom Spinnengott der Witherbarks beschafft habt, ist ein großer Fund! Ich konnte mit nur einem Tropfen von dem Zeug fast zwei Dutzend Hasen töten!",
    ["The vindicator's symbol of power is the breastplate."] = "Die Brustplatte ist das Symbol der Macht eines Vollstreckers.",
    ["The waters of Lake Elune'ara should dissolve the nightmares engulfing this object. Give me a moment to perform the cleansing."] = "Das Wasser des Elune'ara Sees wird die Alpträume auflösen, die den Gegenstand umgeben. Bitte, gebt mir einen Moment, um die Reinigung durchzuführen, <name>.",
    ["The witchdoctor Zalazane dwells on the Echo Isles to the east. They are the isles we once called home. From there he sends his trolls to the mainland, to hex our people and drag more of them under his sway."] = "Der Hexendoktor Zalazane lebt auf den Echoinseln im Osten. Das sind die Inseln, die wir einst Heimat nannten. Von dort aus entsendet er seine Trolle zum Festland, wo sie unser Volk verhexen und immer mehr von uns in ihren Bann ziehen.",
    ["There are dwarves preparing a dig site to the northwest. They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings."] = "Im Nordwesten bereiten Zwerge eine Grabungsstätte vor. Sie glauben, dass Geheimnisse in der Erde verborgen seien, und das stimmt auch; dies ist jedoch kein Grund, das Land bei der Suche nach diesen Lehren auszuhöhlen und zu besudeln.",
    ["There is a camp of Deadwood furbolgs directly to our southwest. Corruption permeates the camp, and I wish to put an end to it before they become a problem."] = "Direkt südwestlich von hier liegt ein Furbolglager der Totenwaldfelle. Ich bin nicht sicher, was sie vorhaben, aber ich würde dem gern einen Riegel vorschieben, ehe es zum Problem wird.",
    ["There is a green drake deep in the sunken temple of Atal'Hakkar by the name of Morphaz. Years ago, he overwhelmed me in a bold ambush and consumed my apprentice whole."] = "Es gibt einen grünen Drachen, tief im versunkenen Tempel von Atal'Hakkar, der sich Morphaz nennt. Vor Jahren überwältigte er mich aus einem kühnen Hinterhalt heraus und verschlang meinen Lehrling mit Haut und Haaren.",
    ["There is a malevolence growing in the timberlings. We are trying to find the source, but until we do...in order to keep Teldrassil safe we must cut down the timberlings who are beyond help."] = "Bosheit wuchert in den Bäumlingen. Wir versuchen, die Ursache dafür zu finden, aber bis dahin...",
    ["There is but one final reagent needed to complete the enchantment. In the south, towards the western coast, high above the bluffs, lies a Holy Spring."] = "Es fehlt nun nur noch ein Reagenz, um die Verzauberung zu vervollständigen. Im Süden, nahe der Westküste, liegt ein Heiliger Quell, hoch über den Steilhängen.",
    ["There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers."] = "Ich habe keinerlei Zweifel, dass ein mächtiger Hexenmeister sich innerhalb der Mauern Stromgardes aufhält. Von Zeit zu Zeit hat dieser Hexenmeister mit Hilfe eines arkanen magischen Relikts abscheuliche Dämonen in großer Zahl herbeibeschworen.",
    ["There's a high demand for the succulent taste of crawler meat among my customers; especially the meat from the monstrous crawlers."] = "Bei meinen Kunden besteht eine enorme Nachfrage nach dem saftigen Geschmack von Kriecherfleisch; besonders nach dem Fleisch der monströsen Kriecher.",
    ["There's a valley to the southeast, the Valley of Bones, haunted by Magram ghosts. Sounds scary, doesn't it? Well think how scary it is to the Magram!"] = "Im Südosten liegt ein Tal, das Tal der Knochen, das von den Geistern der Magram heimgesucht wird. Klingt gruselig, nicht wahr? Stellt Euch mal vor, wie sich die Magram erst gruseln müssen!",
    ["There, I did what Razzeric wanted. Just tell him to be careful when he sets this off. If he makes the slightest mistake, he won't be moving forward, he'll just be a burnt spot on the track."] = "So, ich habe getan, was Razzeric wollte. Sagt ihm nur, er soll vorsichtig sein, wenn er das zündet. Wenn er den kleinsten Fehler macht, fährt er nicht los, sondern ist nur noch ein Brandfleck auf der Rennstrecke.",
    ["These deviate creatures have strange, otherworldly properties."] = "Als Naralex tiefer in seinen Alptraum vorstieß, stieg eine seltsame Schar von Bestien unter dem Brachland in die Höhlen des Wehklagens vor.",
    ["They ain't a witch doctor; they spend their time castin' bones or readin' the leaves for insight - not hexin' people. As a shaman, you already know somethin' about the power of augury; we Zandalar prize the insight they give to the tribe."] = "Die Weissager unseres Stammes werden für ihre Gaben der göttlichen Sicht respektiert, ja wirklich. Sie sind nicht etwa eine Art Hexendoktor, nein, sie verbringen ihre Zeit mit dem Beschwören von Knochen oder dem Lesen von Blättern der Einsicht, und nicht mit dem Verhexen anderer.",
    ["They call themselves the Undermarket: Cutthroat traders that will sell, move, trade and do just about anything for the right price. It gets worse."] = "Sie bezeichnen sich selbst als den Untermarkt: Halsabschneider von Händlern, die verkaufen, verschieben, handeln und zu fast allem bereit sind, vorausgesetzt, der Preis stimmt. Es kommt noch schlimmer, <name>.",
    ["They imbue their breastplates with powerful mojo. If their beliefs falter in the face of the enemy, their breastplate will not."] = "Im Stamm verleiht die Kampfausrüstung Macht. Die Freidenker sind auf diese Weise geehrt.",
    ["They want the impossible from me! The Steamwheedle Cartel wants me to teach the Southsea pirates a lesson."] = "Argh! Sie verlangen das Unmögliche von mir!",
    ["Think you can match wits with Daryl the Bold, huh? I should think not! Of course, you're more than welcome to try. Here's a challenge that should prove to be above your abilities, so don't feel too bad if you can't face up to it."] = "Ihr glaubt wohl, Ihr könnt Euch mit Daryl dem Kühnen messen, hm? Das will ich auch nicht hoffen! Aber Ihr dürft es natürlich gern versuchen, wenn Ihr denn meint... Hier habt Ihr eine Herausforderung, der Ihr bestimmt nicht gewachsen seid.",
    ["Thinning the younger population of creatures here in Shadowglen was a good start, but there is still work to be done. The resources of the forest will be depleted too quickly if the problem is not addressed."] = "Seid gegrüßt, <name>. Ich bin Konservator Ilthalaine.",
    ["This is bad. It seems the Daggerspines are amassing for an attack. Naga are known for their ruthlessness in battle. They will keep attacking until I am dead."] = "Das ist übel. Es scheint, als ob die Säbelflossen sich zum Angriff sammeln. Naga sind bekannt für ihre Ruchlosigkeit im Kampf. Sie werden so lange angreifen, bis ich tot bin.",
    ["This scroll is from that scheming dryad Rynthariel, Keymaster of the Talon Den on Stonetalon Peak. She'll not be making any more contact with the messenger you looted this from, heh, but we must stand our ground here."] = "Diese Rolle ist von der Ränke schmiedenden Dryade Rynthariel, Schlüsselmeisterin des Krallenbaus auf dem Steinkrallengipfel. Mit dem Boten, von dem Ihr diese Rolle erbeutet habt, hat sie jetzt ja wohl keinen Kontakt mehr, aber nachgeben dürfen wir trotzdem nicht.",
    ["This will at least protect her from harm longer if she finds trouble. Return to me here after you've done your duty to Elune."] = "Ich brauche Eure Hilfe, <name>. Ich kann hier nicht weg, denn ich muss hier die anderen Schüler unterweisen, doch Ihr könntet einer unserer verwundeten Schildwachen direkt südlich von Dolanaar helfen.",
    ["This will be the most difficult part because there is some complexity to the plan. To the north of here, you will find a small trail into the mountains."] = "Das hier wird der schwierigste Teil werden, denn der Plan ist etwas kompliziert. Nördlich von hier findet Ihr einen kleinen Pfad, der in die Berge hinaufführt.",
    ["This world has been victim to massive mystic struggles, which tore magic currents from once stable channels. We struggle to determine the effects these changes have caused, and some of us fear the worst!"] = "Diese Welt ist gewaltigen mystischen Kämpfen zum Opfer gefallen, die magische Ströme aus ihren einst stabilen Kanälen rissen. Wir haben Mühe, die Auswirkungen dieser Veränderungen herauszufinden.",
    ["Through my divinations, I see that an item of power hides deep within the Burning Blade Coven, guarded by beasts and black magic. It is called the Burning Blade Medallion, and your next task is to find it and remove it from the coven."] = "Durch meine hellseherischen Kräfte weiß ich, dass im Koven der Burning Blade ein Gegenstand der Macht verborgen ist, der durch Bestien und schwarze Magie bewacht wird. Er wird das Medaillon der Burning Blade genannt und Eure nächste Aufgabe besteht darin, es zu finden und aus dem Koven zu entfernen.",
    ["Thule once told me that, long ago, he and two colleagues created a magic wand, woven together from the apprentice wands each mage possessed."] = "Thule erzählte mir einmal, dass er und zwei Kollegen vor langer Zeit einen magischen Zauberstab herstellten, der aus den Lehrlingszauberstäben zusammengewoben wurde, den jeder Magier besaß.",
    ["To Whom It May Concern: If you're reading this, I'm either dead or soon to be dead. It's hard to say. Most of the crew is dead anyhow. Found information about a Titan."] = "An den Finder dieses Briefs, wenn Ihr dies lest, bin ich wahrscheinlich bereits tot oder werde es in Kürze sein. Die meisten meiner Männer sind schon tot. Ich habe Informationen über einen Titanen entdeckt, über eine große Schlacht zwischen ihm und einem alten Gott. Ja, ein verdammter alter Gott.",
    ["To get paid, you're gonna have to get back to Ironforge and speak to Roetten himself. He'll love getting Leftwitch's package out of the way anyway."] = "Wenn Ihr Eure Bezahlung wollt, müsst Ihr nach Ironforge zurück und persönlich mit Roetten sprechen. Er dürfte froh sein, wenn er Leftwitchs Päckchen vom Hals hat.",
    ["To have a chance against Kurzen, we need his healing support neutralized. He has gathered a large number of Medicine Men who heal his forces with Jungle Remedies and poison our fighters with Venom Fern Extracts."] = "Um überhaupt eine Chance gegen Kurzen zu haben, müssen wir ihm die Möglichkeiten beschneiden, seine Truppen zu heilen. Er hat um sich eine große Anzahl an Medizinmännern versammelt, die seine Streitkräfte mit Dschungelarzneien heilen und unsere Kämpfer mit Giftfarnextrakt vergiften.",
    ["To pass this trial, you must travel south to the Field of Giants. There you will find a host of crawling, insect creatures. They are new to the Barrens and I do not like what they herald."] = "Um diese Prüfung zu bestehen, müsst Ihr nach Süden zum Feld der Riesen reisen. Dort findet Ihr einen Schwarm krabbelnder Insektenwesen. Sie sind neu im Brachland und mir gefällt nicht, was sie ankündigen.",
    ["To survive, I have to be tricky! I know the recipe for flash bombs."] = "Das Ödland ist eine unwirtliche Gegend voller heimtückischer Raubtiere und dreister Aasfresser. Unheimlich, besonders für einen so kleinen Goblin.",
    ["To tell you the truth, although there are no volcanoes here in Winterspring, I believe that there are far more threatening reasons for these hot springs..."] = "Also mal ehrlich, es gibt hier in Winterspring zwar keine Vulkane, aber ich glaube, dass es ein paar viel gefährlichere Ursachen für diese heißen Quellen gibt...",
    ["To the Caverns of Time you go, Lord:Lady;. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection."] = "Begebt Euch zu den Höhlen der Zeit, <Lord/Lady> <name>. Anachronos erwartet Eure Rückkehr. Übergebt ihm das Auge von C'Thun.",
    ["Travel to his cottage just north of town, and execute Stalvan, once and for all. When the deed is done, travel to Madame Eva's and show her his family ring."] = "Stalvan Mistmantle hat ein Leben der Verworfenheit gelebt und unschuldige Opfer starben von seiner Hand. Zweifellos hat er noch zahllose andere Verbrechen begangen und nun wird Dunkelhain von diesem Wahnsinnigen bedroht.",
    ["Travelers keep asking me about the Stonetalon Mountains. It seems to be a popular place for adventure--it doesn't matter if you're seeking wyvern, elementals, or you have business with the Venture Co."] = "Immer wieder fragen mich Reisende über das Steinkrallengebirge aus. Scheint ein beliebter Ort unter Abenteurern zu sein; spielt keine Rolle, ob man Flügeldrachen oder Elementare sucht, oder ob man Geschäfte mit der Venture Company machen will.",
    ["Tymor didn't give me anything to pay you with, so I suggest you take it up with him when you get back to Ironforge. I'm sure he'll still be in his place in the Mystic Ward."] = "Tymor hat mir nichts gegeben, um Euch zu bezahlen, also schlage ich vor, dass Ihr das mit ihm besprecht, wenn Ihr zurück in Ironforge seid. Ich bin mir sicher, er wird dann immer noch an seiner Wohnung im Mystikerviertel sein.",
    ["Ugh... It's so hot... I was exploring this area, when all of a sudden, the heat just became unbearable. I must be suffering from heat exhaustion."] = "Argh... es ist so heiß... Ich war gerade dabei, die Gegend zu erkunden, als die Hitze plötzlich unerträglich wurde. Ich muss wohl einen Hitzschlag haben.",
    ["Under normal circumstances, Rigger and I would lead our kodo past the Kolkar Centaur. Every now and then we hear the Centaur war drums, and when we hear those we stop."] = "Unter normalen Umständen würden Rigger und ich unseren Kodo an den Kolkarzentauren vorbeiführen. Aber ab und zu sind Kriegstrommeln der Zentauren zu hören, und dann machen wir sofort Halt.",
    ["Unfortunately, I can't dish out the beats like I used to, due to this here fat finger problem. Ye see, the climate out here combined with the lack o' air pressure makes me fingers expand."] = "Unglücklicherweise kann ich nicht mehr so austeilen, wie es früher einmal konnte, dank meines Problems hier, meine fetten Finger. Das Klima hier draußen und dazu der geringe Luftdruck lässt meine Finger einfach aufquellen.",
    ["Unfortunately, I see the only way to stop this threat to Felwood is a frontal attack. There are no other ways into Shadow Hold, and I have no means to teleport you inside."] = "Leider scheint die einzige Möglichkeit, diese Bedrohung für den Teufelswald zu stoppen, ein Frontalangriff zu sein. Es gibt keine anderen Wege in die Schattenfeste und ich habe keine Möglichkeit, Euch ins Innere zu teleportieren.",
    ["Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes."] = "Nach genauerer Analyse der Situation in Gnomeregan sieht es so aus, als hätten wir nicht nur dabei versagt, die Troggs auszulöschen, sondern als hätten wir dabei auch noch einen Großteil des Volkes der Gnome in schreckliche, hirnlose, bösartige Lepragnome verwandelt.",
    ["Using the water you brought, you will be able to temporarily douse the flame that holds the centaur relic. It will not work permanently, however, so you will have to be quick about it."] = "Wenn Ihr das Wasser benutzt, das Ihr mitgebracht habt, könnt Ihr vorübergehend die Flamme löschen, die das Zentaurenrelikt schützt. Aber der Effekt ist nicht von Dauer, daher müsst Ihr rasch handeln.",
    ["Valdred, once my good friend, was my wife's murderer. Although I am incapable of grieving, I do yearn for revenge. If you kill Valdred and bring me his cursed hands, then I will reward you."] = "Valdred, einst ein guter Freund von mir, ist der Mörder meiner Frau. Auch wenn ich keine Trauer empfinden kann, so sehne ich mich doch nach Rache. Wenn Ihr Valdred tötet und mir seine verfluchten Hände bringt, werde ich Euch belohnen.",
    ["Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the amulet back together."] = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde. Die einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen.",
    ["Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the medallion back together."] = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde. Die einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen.",
    ["Vengeance is power. The Zandalar vindicator is such power."] = "Rache ist Macht. Der zandalarianische Vollstrecker ist solch eine Macht.",
    ["Wanted: A skilled fighter to deal with the threat of the Pterrordax that inhabit the Un'Goro Crater. Their numbers are growing, and they are becoming a menace to travelers in the area."] = "Gesucht: Ein fähiger Kämpfer, der sich der Bedrohung durch die Pterrordax des Un'Goro Kraters annimmt. Ihre Zahl wächst ständig und sie werden zu einer Bedrohung für die Reisenden in der Gegend.",
    ["Warlocks tread dangerous ground in dealing with demons, but our demoniacs take this one step further. Through an ancient and arcane ritual, they allow a demon to enter their being."] = "Hexenmeister begeben sich bei ihrem Umgang mit Dämonen auf ein gefährliches Terrain, unsere Besessenen gehen jedoch noch einen Schritt weiter. Mit Hilfe eines uralten, arkanen Rituals erlauben sie es einem Dämon, in ihre Gestalt zu schlüpfen.",
    ["Warning: Proceed into Sishir Canyon west of here at your own risk. Besseleth and her eight-legged children of the forest have claimed this canyon as their webbed lair."] = "Warnung: Betretet Sishir Canyon westlich von hier auf eigene Gefahr. Besseleth und ihre achtbeinigen Kinder des Waldes haben diesen Canyon zu ihrem eingesponnen Unterschlupf erkoren.",
    ["We Forsaken are at war with the Lich King's army of the Scourge: necromantically raised armies of the undead, foul beasts of the north, and tormented spectres."] = "Wir Verlassenen liegen im Krieg mit der Geißel, der Armee des Lichkönigs: durch Nekromantie erweckte Armeen von Untoten, grausige Bestien des Nordens und gepeinigte Schreckgespenster.",
    ["We Zandalar invest power in those who speak with the authority of divinity."] = "Wir Zandalarianer investieren Macht in diejenigen, die mit der Gewalt des Göttlichen sprechen.",
    ["We Zandalar know not of druidic ways; nature is to be shaped by our need, not the other way around."] = "Die Zandalar kennen die Wege der Druiden nicht; die Natur soll nach unseren Bedürfnissen geformt werden und nicht umgekehrt.",
    ["We Zandalar prize what we wear as a symbol of accomplishment."] = "Wir Zandalarianer schätzen unsere Kleidung als eine Art Symbol für vollbrachte Taten.",
    ["We are hunters. Down below in Mulgore there is a mighty kodo named Arra'chea."] = "Ihr habt die Riten der Erdenmutter absolviert und Euch einen Platz in Thunder Bluff verdient. Um den Platz zu verteidigen, den Ihr Euch so hart erarbeitet habt, müsst Ihr allerdings auch weiterhin Euren Wert für unser Volk beweisen.",
    ["We are in short supply of a few items at the Warsong lumber camp!"] = "Uns hier im Holzfällerlager der Warsong gehen langsam einige Dinge aus!",
    ["We cannot allow the Burning Blade a foothold in Durotar! We must destroy them before their evil festers!"] = "Wir können den Burning Blade nicht erlauben, in Durotar Fuß zu fassen! Wir müssen sie vernichten, bevor das Böse zu schwären beginnt!",
    ["We have a real infestation problem to the west. Tunnel rat kobolds have moved into the foothills, setting up dens and fouling our land with their filth!"] = "Wir haben im Westen ein Problem mit einer echten Plage. Kobolde der Tunnelratten sind ins Vorgebirge eingedrungen, haben dort ihre Baue eingerichtet und verdrecken unser Land mit ihrem Abfall!",
    ["We have discovered another base of operations for the Twilight's Hammer. It is called Twilight's Run; it is a cave tucked in the northeast corner of Silithus."] = "Wir konnten eine weitere Operationsbasis der Twilight-Hammer ausfindig machen. Es ist eine gut versteckte Höhle in der nordöstlichen Ecke von Silithus, bekannt als die Kavernen der Twilight.",
    ["We have not sat idly by for a millennium. We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world."] = "Wir haben hier nicht ein Jahrtausend in völliger Untätigkeit verbracht, <name>. Wir sahen mit eigenen Augen, wie sich diese Biester an ihren eigenen Artgenossen gütlich taten, nachdem diese ihre Nützlichkeit für den Schwarm verloren hatten. Wir lauschten, als sie ihre Pläne schmiedeten, diese Welt in Schutt und Asche zu legen.",
    ["We heard the cries in the middle of the night. Then this morning, sure enough, the herd was missing two rams. That dastardly beast known as Vagash has been preying on our livelihood."] = "Wir haben mitten in der Nacht die Schreie gehört. Heute morgen fehlten der Herde dann tatsächlich zwei Widder. Diese heimtückische Bestie, Vagash genannt, hat sich über unsere Existenzgrundlage hergemacht.",
    ["We mages do more than just waggle our fingers and make pretty sparks! We control magic, the base fabric of our world! And that takes great care, and resolve."] = "Wir Magier machen mehr als nur mit den Fingern schnippen und hübsche Funken regnen lassen. Wir kontrollieren die Magie, die Grundsubstanz unserer Welt! Das erfordert große Umsicht und Entschlossenheit.",
    ["We must find if Yenniku is dead. Slay the Bloodscalp Headhunters and take from them their Shrunken Heads. You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them."] = "Wir müssen herausfinden, ob Yenniku tot ist. Erschlagt die Kopfjäger der Bloodscalp und nehmt ihnen ihre Schrumpfköpfe ab. Ihr müsst viele, viele Köpfe sammeln und ich werde sie überprüfen, um sicherzugehen, dass Yennikus Kopf nicht dabei ist.",
    ["We must save Sharpbeak! Fight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!"] = "Wir müssen Scharfschnabel retten! Kämpft Euch bis zum Gipfel von Jintha'Alor im Herzen des Vilebranchterritoriums vor, holt Euch den Schlüssel zu Scharfschnabels Käfig von der üblen Priesterin Hexx und dann sucht und befreit Scharfschnabel.",
    ["We must use restraint against Eranikus. We are to redeem him not destroy him. Tyrande is already en route to assist us in this task. We must weather the dragon's blows and save Nighthaven from certain destruction."] = "Wir müssen gegen Eranikus mit Bedacht vorgehen. Wir sollen ihn erlösen und nicht zerstören. Tyrande ist bereits auf dem Weg, um uns bei dieser Aufgabe zu unterstützen. Wir müssen die Attacken des Drachen überstehen und Nighthaven vor der sicheren Zerstörung bewahren.",
    ["We need to get out of here. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell."] = "Wir müssen hier weg, <name>. Helft mir, meine Ausrüstung aus dem Vorratsbereich zu holen und meine Freunde zu befreien. Falls wir hier rauskommen, dann müsst Ihr Euch weiter nach Morgans Wacht durchschlagen und mit Marshal Maxwell sprechen.",
    ["We shall rein in the worgen problem, have no worry of that. This evil that your friend introduced to our woods will be contained, and I bear her no ill will for her actions."] = "Wir werden das Worgproblem in den Griff bekommen, keine Frage. Das Böse, das Eure Freundin in unseren Wald gebracht hat, wird eingedämmt werden und ich nehme ihr ihre Handlungen nicht übel.",
    ["We were deep in a vast mine in Westfall, hidden beneath a barn in Moonbrook. No clue where these stinkin' thieving types came from. Anyway, the mine tunnel collapsed on us."] = "Wir waren tief unten in einer großen Mine in Westfall, deren Eingang unter einer Scheune in Moonbrook versteckt lag. Keine Ahnung, wo dieses elende Diebesgesindel herkam. Egal, jedenfalls stürzte der Minentunnel über uns ein.",
    ["We're sitting on a goldmine here, I tell you - a goldmine! Kodo bones will change the world forever... I have customers making furniture, music instruments, and even blasting powder out of them."] = "Wir sitzen hier auf einer Goldmine, ich sage Euch - einer Goldmine! Kodoknochen werden die Welt für immer verändern... Ich habe Kunden, die daraus Möbel, Musikinstrumente und sogar Sprengpulver herstellen.",
    ["We've learned that a source of furbolg corruption is from the satyr. They hold sway via talismans that they channel magic through. If the furbolg have a chance at salvation, we must lure out the satyr corruptor and take that talisman!"] = "Wir haben herausgefunden, dass die Satyrn ein Grund für die Verderbnis der Furbolgs sind. Sie sollen ihre Macht durch Talismane ausüben, mit denen sie ihre Magie kanalisieren können. Damit die Furbolgs Aussicht auf Rettung haben, müssen wir den Satyrverderber aus seinem Versteck locken und ihm diesen Talisman abnehmen!",
    ["Well met. I've something that might interest you. I have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality."] = "Seid gegrüßt, <class>. Ich habe hier etwas, das Euch interessieren könnte. Es gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität.",
    ["Well, the only caravan brave enough to travel these parts relies on me. Ever since I learned how to rejuvenate and control aged and dying kodos with my kodo kombobulator, the caravan owner Cork, Rigger, and I entered a partnership."] = "Bibbly glaubt, dass er der einzige Goblin in Desolace sei, der weiß, wie man Geld macht. Tja, die einzige Karawane, die mutig genug ist, diese Gebiete zu bereisen, verlässt sich auf mich.",
    ["Wha.. What happened? The last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs."] = "<Kernobee stöhn.t> Was... Was ist passiert? Das Letzte, an das ich mich erinnere, ist, wie ich von einer Gruppe Dunkeleisenzwerge gefangen, halb tot geprügelt und dann hier zu diesen schmutzigen Troggs geworfen wurde.",
    ["What?! Ah, so I did mention a bounty, didn't I? Well, that'll teach me to open my mouth, won't it? You did the work, so I suppose it is only right you reap the greatest reward from it."] = "Was?! Hm, ich hab wohl wirklich ein Kopfgeld erwähnt, nicht wahr? Gut, das wird mich lehren, meinen Mund nicht zu weit aufzureißen, oder? Ihr habt die Arbeit gemacht, also ist es wohl nur fair, wenn Ihr den größten Lohn einheimst.",
    ["When I struggled with the Forsaken's poisons, I had a vision. I had a vision of the druids in the Dor'danil Barrow Den, poisoned... murdered by the undead!"] = "Als ich mich mit den Giften der Verlassenen abplagte, hatte ich eine Vision. Ich sah die Druiden des Dor'danil-Grabhügels vergiftet... ermordet von den Untoten!",
    ["When doing this though, be sure to save me the water elemental cores!"] = "Wenn ich gegen meinen besseres Wissen und Gewissen handele und nun doch bleibe, um meinen Ingenieurladen an der Vergessenen Küste aufzumachen, muss ich mich dringend um diese nervigen Elementare kümmern.",
    ["When my life was ended upon the rocks, I had no clue what the afterlife held for me. The Lighthouse was black that night because Old Murk-Eye had scared the keeper's family off."] = "Als ich auf den Felsen mein Leben aushauchte, hatte ich keine Ahnung, was das Leben nach dem Tode für mich bereithalten würde. In jener Nacht war der Leuchtturm erloschen, weil Old Murk-Eye die Familie des Leuchtturmwärters vertrieben hatte.",
    ["When we fled Gnomeregan, we left so much data behind! Vitally important data! I need the data on a prismatic punch card, from a Matrix Punchograph 3005-D high security terminal, deep in Gnomeregan."] = "Als wir aus Gnomeregan flohen, haben wir so viele Daten zurückgelassen! Lebenswichtige Informationen! Ich brauche die Daten auf einer Prismalochkarte aus einem Matrix-Prägographen 3005-D, einem Hochsicherheitsterminal, tief in Gnomeregan.",
    ["While I do possess much knowledge about the owlbeasts you defeated in Winterspring, I am not very learned on the subject of the magics they wield."] = "Auch wenn ich viel über die Eulenbestien weiß, die Ihr in Winterspring erledigt habt, bin ich in der Magie, die sie wirken, nicht wirklich bewandert.",
    ["While I'd like to recover all my goods, I'm sure that's not possible. Still, there's a few things that I absolutely must have! As you see, my observatory is ready to go, but it needs the smaller of the two lenses."] = "Ich hätte zwar gern, dass Ihr mir all meine Waren zurückbringt, aber das dürfte wohl unmöglich sein. Es gibt jedoch ein paar Dinge, die ich unbedingt wiederhaben muss! Wie Ihr seht, ist mein Observatorium fast einsatzbereit, aber es fehlt noch die kleinere der zwei Linsen.",
    ["While the majority of the books were filled with - to put it bluntly - tripe, there were some gems. One of those tomes documented the creation of a set of armor fit for an archmage: Frostfire."] = "Als Behüterin hatte ich Zugang zu Vielem von Medivhs persönlicher Habe. Die Folianten waren für mich die aufschlussreichsten Gegenstände.",
    ["While we still know very little about why the furbolg have been ingesting this strange substance, I do think it's best that we put a stop to it before it gets out of hand."] = "Wir wissen leider immer noch nicht, warum die Furbolgs diese merkwürdige Substanz einnehmen.",
    ["While you have been exploring Un'Goro, I have seen other things that a mighty hunter such as yourself would relish in. One such sight was a huge ape among the other gorillas to the north."] = "Während Ihr Un'Goro erkundet habt, sind mir ein paar andere Dinge aufgefallen, die einem mächtigen Jäger wie Euch sicher gefallen würden. Zum Beispiel gibt es da einen gewaltigen Affen unter den Gorillas im Norden.",
    ["While you were down there I happened to notice that one of those beasts stood out from the rest. He was bigger and more menacing. I bet he's the one who led the others here to cause the disruption to the dig site."] = "Während Ihr da unten wart, ist mir aufgefallen, dass eines der Biester aus der Menge herausstach. Es war größer und bedrohlicher. Ich könnte wetten, das ist derjenige, der die anderen hierher geführt hat und für die Störung der Ausgrabungsstätte verantwortlich ist.",
    ["While you were gathering the supplies, I had some of my people handle marking the Scourge buildings we need demolished. Here's the plan: I'm going to give you ten sticks of my special compound."] = "Während Ihr die Vorräte gesammelt habt, habe ich einige meiner Leute die Geißelbauwerke kennzeichnen lassen, die wir abreißen müssen. So ist der Plan: Ich gebe Euch zehn Stecken meines speziellen Präparats.",
    ["While you were gone I fixed the pot you brought me. I even added an extra steam whistle, and look! There's a new chopper at the bottom that'll cut through leg bones!"] = "Während Ihr fort wart, habe ich den Topf, den Ihr mir brachtet, repariert. Ich habe sogar noch eine zusätzlich Dampfpfeife angebracht, und seht mal! Da ist ein neues Hackbeil am Boden, das kann Beinknochen durchtrennen.",
    ["While you were out gathering, I uncovered some old text in one of my tomes that indicates that an ancient plague wiped out thousands of innocent victims."] = "Lady Sylvanas hat sich an die königliche Apothekervereinigung gewandt.",
    ["Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home."] = "Während der törichte Narr Mok'Morokk seine Macht genießt und Tharg mit den Dämonen des Kummers und der Rache ringt und um die Führerschaft des Klans buhlt, scheine ich der Einzige zu sein, der die Ursache der Aggression in unserer alten Heimat herausfinden möchte.",
    ["Why don't we go over to the forge and get started on this? I've been preparing for your arrival for some time, so it shouldn't take long at all."] = "Warum gehen wir nicht rüber zur Schmiede und fangen damit an? Ich treffe schon seit einiger Zeit Vorbereitungen für Eure Ankunft, daher dürfte es nicht allzu lange dauern.",
    ["Will you assist me, mortal? Will you find the prayer to Elune? As I stated, the prayer was etched onto a golden tablet. One of these idol worshipping scoundrels must have it on their person."] = "Werdet Ihr mir helfen, sterbliches Wesen? Hört meine Geschichte.",
    ["With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache. Perhaps he or someone there can make further sense of what the gnolls are up to."] = "Jetzt, nachdem die Schlachtpläne der Gnolle entdeckt wurden, bleibt nur noch, die Pläne zu Hadoken Swiftstrider ins Camp Mojache zurückzubringen. Vielleicht kann er oder irgendjemand dort besser darauf schließen, was die Gnolle vorhaben.",
    ["With the loss of Guard Captain Malkhor, the position of Guard Captain of Revantusk is once again open."] = "Mit dem Verlust von Malkhor ist auch wieder der Posten des Wachbefehlshabers von Revantusk unbesetzt.",
    ["Without the blessings of Alexstrasza the Life-Binder and Nozdormu the Timeless, Teldrassil's growth has not been without flaw."] = "Ohne den Segen Alexstraszas der Lebensbinderin und Nozdormus des Zeitlosen gab es Makel in Teldrassils Wachstum.",
    ["Wouldn't ye know it, every time ol' Hansel wants to take a moment to relax and reflect upon his life, the powers that be give him another job."] = "Würd' ich's nicht besser wissen, würd' ich behaupten, dass jedesmal, wenn der alte Hansel sich endlich 'mal ein wenig entspannen möchte, ihm die höheren Mächte einen weiteren Auftrag erteilen.",
    ["Wreak havoc on the minions of evil. Zul'Gurub must taste Zandalar vengeance."] = "Die ultimative Rache wartet innerhalb Zul'Gurubs. Hakkar darf nicht mehr auferstehen.",
    ["Yes, imbecile, perhaps you are ready for a more involved set of missions. The albino demon bat, Duskwing, roams the countryside just north of here."] = "Bisher habt Ihr die Missionen abgeschlossen, die ich Euch aufgab, wenn Ihr auch nicht unbedingt ein Ausbund an Pünktlichkeit seid. Ihr denkt wahrscheinlich, dass Ihr bereit für eine Herausforderung seid.",
    ["Yet I'm not one to give out favors freely, even if you were sent here by an old friend. I hold nothing but hatred and contempt for our brutish ogre neighbors."] = "Ja, ich bin fürwahr mit der Verzauberung vertraut, die Ihr benötigt, <class>. Aber alles hat seinen Preis, selbst wenn Euch ein alter Freund schickt.",
    ["Yet another ship from my fleet has been lost to those overzealous humans at Northwatch Hold! Those bastards must be dealt with. Their paranoia has them in a state of frenzy."] = "Wieder ist ein Schiff meiner Flotte diesen übereifrigen Menschen der Feste Northwatch in die Hände gefallen! Man muss sich um diese Bastarde kümmern. Ihr Verfolgungswahn hat sie in eine Art Raserei versetzt.",
    ["You are one of my lieutenants! Prepare yourself. I will call upon you soon. My time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer."] = "Hmmm, Anführer der Searingblade... das beunruhigt mich zutiefst. Wenn sie es sind, die für Neeru zählen, dann sollten sie auch unser erstes Ziel sein. Dieser Satyr...",
    ["You be ready for your first test. South of Razor Hill, just outta town, one of our grunts be hurt fightin' off some o' Proudmoore's old troops."] = "Ihr seid bereit für Eure erste Prüfung, <name>. Südlich von Klingenhügel, direkt vor der Stadt, wurde eine Grunzerin verletzt, als sie einige von Proudmores alten Truppen bekämpfte.",
    ["You dare challenge Overlord Mok'Morokk? Haw! Me crush tiny! You tell me when ready for good beating."] = "Ihr wagt es, Oberanführer Mok'Morokk herauszufordern? Ha! Ich zerschmettern einen Winzling von <Volk>! Ihr mir sagen, wenn bereit für ordentliche Tracht Prügel.",
    ["You did so well with the lieutenants and underlings that I'd like you to do one last thing for me. Serena Bloodfeather is the sister of a harpy named Bloodfeather who was slain by Rexxar quite a while ago."] = "Ihr habt das mit den Offizieren und Unterlingen so gut erledigt, dass ich Euch noch um einen letzten Dienst bitten möchte. Serena Blutfeder ist die Schwester einer Harpyie namens Blutfeder, die Rexxar vor einer ganzen Weile erschlug.",
    ["You fancy yourself a hero of the Dawn, eh? I've seen our greatest soldiers get rolled over by Kel'Thuzad's plebes! How well could someone so clueless possibly fare in Naxxramas?"] = "Ihr haltet Euch für einen Helden der Dämmerung, ja? Ich habe gesehen, wie unsere besten Soldaten von Kel'Thuzads Gefolgsleuten überrannt wurden. Wie könnte jemand, der so ahnungslos ist wie Ihr, in Naxxramas bestehen?",
    ["You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs."] = "Unter dem Körper des Tauren findet Ihr einen Ranzen. Er hält ihn immer noch fest an sich gedrückt, als hätte er ihn beim Angriff der Troggs schützen wollen.",
    ["You got here just in the nick of time! The Pyrewood Council will be returning any moment. Arugal has other matters to tend to in the keep. He uses the Council as mere puppets to keep the mindless minions of Pyrewood under his control."] = "Ihr kommt gerade rechtzeitig, <name>! Der Rat von Pyrewood wird jeden Moment zurückkehren. Arugal muss sich in der Burg um andere Dinge kümmern. Er benutzt den Rat als reine Schachfiguren, um die hirnlosen Diener von Pyrewood unter seiner Kontrolle zu halten.",
    ["You have a promising air about you, and will prove yourself to the tribe. Perhaps someday soon you will be welcomed into the great city of Thunder Bluff."] = "Ihr seht viel versprechend aus, und ich denke, Ihr werdet Euch dem Stamm gegenüber beweisen. Vielleicht wird man Euch eines Tages in der großen Stadt Thunder Bluff willkommen heißen.",
    ["You have completed the necessary lessons all young druids are taught before they can adopt an aquatic aspect. Go now back to your trainer, Mathrengyl Bearwalker, in Darnassus."] = "Ihr habt die notwendigen Lektionen gemeistert, die alle jungen Druiden lernen, bevor sie einen Wasseraspekt annehmen können. Kehrt jetzt zu Eurem Lehrer Turak Runetotem nach Thunder Bluff zurück.",
    ["You have done well. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles."] = "Ihr habt Eure Sache gut gemacht, <name>. Ihr habt meinen Test und die Tests vor meinem bestanden. Kehrt zu Dorn in Tausend Nadeln zurück.",
    ["You have proven your loyalty to King Magni. And your hatred for the Dark Iron scum is as great as my own. There is a task I wish to complete myself but I am bound by honor to stay with Longbraid."] = "Ihr habt Eure Loyalität zu König Magni bewiesen, <class>. Und Euer Hass auf den Dunkeleisenabschaum ist genau so groß wie mein eigener. Es gibt da eine Aufgabe, die ich selbst beenden möchte, aber ich bin durch meine Ehre verpflichtet, bei Longbraid zu bleiben.",
    ["You have proven yourself time and again, and your resourcefulness seems to rival even that of Kurzen himself. You may be the salvation of our band of rebels...if you can pit yourself against Kurzen and prevail!"] = "Ihr habt Euren Wert wieder und wieder unter Beweis gestellt und Euer Einfallsreichtum scheint sich mit dem von Kurzen selbst messen zu können. Ihr könntet die Rettung für unseren Rebellentrupp sein...",
    ["You have the look of a fisherman! I love to fish - been fishing all my life. The best bait to use is soft-shelled clam meat; the fish just can't resist, you know what I mean?"] = "Ihr seht wahrlich aus wie ein Angler, <class>! Ich angle zu gern - schon mein Leben lang. Als Köder eignet sich das Fleisch der weichschaligen Muschel am besten.",
    ["You have uncovered a dark threat to the land. The Resonite cask you have found in that cave houses a slumbering Earthen by the name of Goggeroc."] = "Ihr habt eine dunkle Bedrohung für das Land entdeckt, <class>. Das Resonitfässlein, das Ihr in der Höhle gefunden habt, birgt einen schlummernden Irdenen namens Goggeroc.",
    ["You look as though you might need something to keep your hands warm, hm? I'll tell you what would help: a pair of nice, warm gloves."] = "Was haben wir denn hier? Ihr seht aus, als könntet Ihr was brauchen, was Euch die Hände warm hält, hm?",
    ["You look like a capable. Perhaps you're looking to make some money? Cork and I started this caravan to make a bundle of money; little did we know the dangers of turning a buck!"] = "Ihr seht fähig aus, <Volk>. Vielleicht wollt Ihr Euch etwas Geld verdienen? Cork und ich haben mit dieser Karawane angefangen, um einen Haufen Geld zu scheffeln.",
    ["You looking fer work? I might have some if you're up for a little challenge. I got a friend named Groy who makes a killing selling what the naga call akiris reed: it's some kind of valuable ocean reed."] = "Sucht'er Arbeit, <name>? Hab vielleicht was für Euch, wenn'er Euch was traut. Mein Freund Groy verdient sich dumm un' dämlich mit dem Verkauf von dem Zeuch, das die Naga Akirisschilfrohr nennen: is' so 'ne Art wertvolles Meeresschilfrohr.",
    ["You may have killed the raptors, but the silver they stole must be recovered! I have reports that the raptors have a large grouping of nests south of Ratchet, known as the Raptor Grounds."] = "Ihr habt zwar die Raptoren getötet, aber das Silber, das sie gestohlen haben, muss wiederbeschafft werden! Ich habe Berichte darüber, dass die Raptoren eine große Ansammlung von Nestern südlich von Ratchet haben, Raptorgründe genannt.",
    ["You must defeat Myzrael before she grows in strength. If you do not, then once she has gathered enough power she will challenge her captors!"] = "Ihr müsst Myzrael besiegen, bevor ihre Kraft größer wird. Wenn Ihr es nicht tut, wird sie ihre Häscher herausfordern, sobald sie genug Stärke gesammelt hat!",
    ["You must master both to have any chance of success in Zul'Gurub... and any chance of being like the Zandalar predators."] = "Ein Raubtier weiß, wie es sich an seine Beute heranschleicht, ein erfolgreiches Raubtier weiß aber auch, wie es seine Beute schlägt, sobald es zu ihr aufgeschlossen hat. Ihr müsst beides beherrschen, wenn Ihr in Zul'Gurub erfolgreich sein wollt...",
    ["You pick up the sack carefully and prepare to make your way back to Jessir Moonbow on the border of Felwood and Ashenvale. Hopefully the paladin will be given the proper respects once you've passed his remains on to his friends."] = "Ihr hebt den Sack vorsichtig auf und macht Euch auf den Rückweg zu Jessir Moonbow an der Grenze des Teufelswaldes und Ashenvale. Hoffentlich wird dem Paladin der ihm zustehende Respekt erwiesen, wenn Ihr seine Überreste seinen Freunden übergeben habt.",
    ["You secure the sealed testing kit for the journey back to the Undercity. Apothecary Zinge waits for you and the sealed field testing kit there."] = "\"Wir sind so weit, die Kraftquelle ist entfernt und die Daten sind gesichert. Also dann, sichere Reisen und all das.",
    ["You seek to prove your worth to my kind, mortal? Very well, perhaps we can be of mutual assistance. The ancient sandworm, Ouro, is a being of legendary power."] = "Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen. Der uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht.",
    ["You serve my husband well, but he does not know why Hammerfall is under attack."] = "Ihr seid meinem Gemahl ein treuer Diener, <class>, aber er weiß nicht, warum Hammerfall angegriffen wird.",
    ["You take this, mon. You take this to Aerie Peak, dead center of town by the well. You plant it! Drive it right into the ground! Show those dwarves that troll mean business!"] = "<Otho überreicht Euch einen langen, blutverschmierten Speer, den mehrere Greifenfedern umhüllen.> Nehmt den hier, Mann. Geht damit zum Aerie Peak, zum toten Stadtzentrum beim Brunnen. Platziert ihn dort! Rammt ihn richtig in den Boden und zeigt diesen Zwergen, dass die Trolle es ernst meinen! Kommt danach zu mir zurück...",
    ["You there! If you're looking for something to make yourself useful, then listen up! We need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment."] = "Ihr da! Wenn Ihr Euch irgendwie nützlich machen wollt, dann hört zu! Wir benötigen frisch erweckte Rekruten, die sich nach Deathknell begeben und dort nach allem suchen, was wir irgendwie gebrauchen können.",
    ["You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas."] = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden.",
    ["You'd think that being chief digger for Marshal Expeditions means I like digging. There might be worse things to do in this world... but none really leap to mind."] = "Man sollte meinen, dass ich gern grabe, nur weil ich der Oberbuddler von Marshals Expeditionen bin. Es könnte schlimmere Dinge in der Welt geben... auch wenn mir gerade keines einfällt.",
    ["You'll be happy to know we appear to be making progress in the mine, thanks in no small part to your efforts. We can now turn our eyes to other concerns."] = "Ihr werdet erfreut sein zu hören, dass wir anscheinend Fortschritte in der Mine machen. Der Dank dafür gebührt zu einem nicht unerheblichen Maß Euren Bemühungen.",
    ["You'll find Brother Neals in the abbey, in the bell tower... where he likes to taste his wine."] = "Jetzt, wo meine Ernte in Sicherheit ist, bringt diese Traubenliste zu Bruder Neals. Er ist verantwortlich für die Essens- und Getränkevorräte von Nordhain und ich bin mir sicher, er wird hoch erfreut sein zu hören, dass er frische Trauben bekommt.",
    ["You've almost proven yourself to be a master hunter of panthers."] = "Ihr habt schon fast bewiesen, dass Ihr die Kunst der Pantherjagd meisterlich versteht.",
    ["You've done doubly well in addressing the threat that the Zukk'ash insects pose to Camp Mojache. The threat these things pose is far from over, and I'd like to ask you for one last task on behalf of the Horde."] = "Ihr habt mehr als richtig gehandelt, indem Ihr Euch der Bedrohung, die die Insekten der Zukk'ash für das Camp Mojache darstellen, zugewandt habt. Die Gefahr, die von ihnen ausgeht, ist noch lange nicht vorüber.",
    ["You've proven to be a very reliable individual. As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance."] = "Ihr habt große Verlässlichkeit bewiesen, <name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.",
    ["You've shown your potential to the Forsaken under normal circumstances - now let's see you under pressure. The Rattlecage skeletons, more mindless minions of the Lich King, are a tougher foe than the zombies you have faced thus far."] = "Ihr habt den Verlassenen Euer Potenzial unter normalen Umständen gezeigt, <name>. Jetzt wollen wir mal sehen, wie es damit bestellt ist, wenn Ihr unter Druck steht.",
    ["Your beliefs are alien to us, heathen. Ancient Zandalar were once branded as heretics."] = "Eure Überzeugungen sind uns fremd, <Ungläubiger/Ungläubige>. Die Uralten von Zandalar wurden einst als Heiden gebrandmarkt.",
    ["Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young. The Wildmane Totem is made, and your last task lies ahead."] = "Die Geister sprechen von Eurer Säuberung der Wasserbrunnen von Winterhoof und Thunderhorn, junger <name>. Das Totem von Wildmane ist fertig und die letzte Aufgabe erwartet Euch.",
    ["Your previous investigations are proof that the Echo Ridge Mine needs purging. Return to the mine and help clear it of kobolds. Waste no time."] = "Eure Untersuchungen beweisen, dass die Echokammmine gesäubert werden muss. Kehrt in die Mine zurück und helft dabei, sie von den Kobolden zu befreien. Ihr dürft keine Zeit verlieren, <name>.",
    ["Zanzil the Outcast dwells with his followers in the Jubuwal and Aboraz Ruins, northeast of Booty Bay. He is exiled from his tribe. Why? Well..."] = "Zanzil der Ausgestoßene hält sich mit seinen Anhängern in den Ruinen von Aboraz und Jubuwai auf, nordöstlich von Booty Bay. Sein Stamm hat ihn verbannt. Warum? Nun...",
    ["another tribe of Furbolgs, the Foulweald, live southeast of Astranaar. They are not as many as the Thistlefur, but their ferocity poses a future threat."] = "<name>, südöstlich von Astranaar lebt noch ein anderer Stamm Furbolgs, die Fäulnisklauen. Es gibt zwar nicht so viele von ihnen wie das bei den Distelfellen der Fall ist, aber ihre Wildheit könnte sich in der Zukunft zu einem Problem auswachsen.",
    ["ath, is it? I can tell you're bursting with pride over completing the first test, hm? As I told you before, it's no large feat. You should try your hand at boar hunting."] = "<name>ath, stimmt's? Ich seh schon, Ihr platzt fast vor Stolz, dass Ihr den ersten Test bestanden habt. Aber ich hab Euch ja auch schon gesagt, dass das keine große Tat war. Ihr solltet Euch mal an der Eberjagd versuchen.",
    ["it is now time for you to travel to far-off lands. You are ready. You now hunt Frostmaw, a yeti in the Alterac Mountains. He is elusive, his white coat blending into the snows of his mountain home."] = "<name>, jetzt ist es Zeit, weit entfernte Länder zu bereisen. Ihr seid bereit. Ihr jagt jetzt Frostrachen, einen Yeti im Alteracgebirge. Er ist schwer zu erkennen, da sein weißes Fell mit den Schneefeldern seiner Bergheimat verschmilzt.",
    ["my brother soon stands before Chief Bloodhoof, and it is my honor to make his headdress for him. I want to ask a favor of you while I finish tanning these leather straps."] = "<name>, mein Bruder wird schon bald vor Häuptling Bloodhoof treten und es ist mir eine Ehre, einen Kopfputz für ihn anfertigen zu dürfen. Ich möchte Euch um einen Gefallen bitten, während ich die letzten dieser Lederriemen gerbe.",
    ["our scouts have identified the leader of this recent Trogg incursion. It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug."] = "<name>, unsere Späher haben den Anführer des jüngsten Eindringens der Troggs ermitteln können. Es scheint, als folgten diese Bestien am Loch Modan einem Häuptling namens Grawmug.",
    ["please, can you help me? My son Kron went hunting days ago, and he still hasn't returned. He went west towards the Barrens to hunt crocolisks along Southfury River."] = "<name>, bitte, könnt Ihr mir helfen? Mein Sohn Kron ist vor Tagen auf die Jagd gegangen und immer noch nicht zurück. Er wollte nach Westen in Richtung des Brachlandes, um dort am Ufer des Südstroms Krokilisken zu jagen.",
    ["the creation of each weapon will take some time. Additionally, you may only use the power of the Felcurse once per three minutes. Its weakening properties against Razelikh the Defiler and his minions may be variable in duration."] = "<name>, die Herstellung jeder einzelnen Waffe wird einige Zeit in Anspruch nehmen. Außerdem dürft Ihr die Macht des Teufelsfluchs nur einmal alle drei Minuten verwenden. Seine schwächenden Eigenschaften gegen Razelikh den Entweiher und seine Diener können unterschiedlich lang dauern.",
    ["the gnolls are still out there. I can hear their baying as they hunt in the hills above Lakeshire. And one cry is louder than the rest - Yowler, their leader."] = "Die Gnolle sind immer noch da draußen, <name>. Ich kann sie bellen hören, wenn sie in den Hügeln oberhalb von Seenhain jagen. Und das Geheul eines Gnolls ist lauter als das aller anderen - das von Jauler, ihrem Anführer.",
    ["you are a hunter worthy of our company. From the battlefields of Lordaeron to the deepest jungle, I have rarely witnessed such prowess with weaponry as you have demonstrated."] = "<name>, Ihr seid <ein Jäger, der/eine Jägerin> die; unserer Gesellschaft wahrlich würdig ist. Von den Schlachtfeldern von Lordaeron bis in den tiefsten Dschungel hinein habe ich selten jemanden gesehen, der so geschickt mit den Waffen umgegangen ist wie Ihr.",
    ["you are a with proven interest in the security of Northshire. You are now tasked with the protection of the surrounding Elwynn Forest."] = "<name>, Ihr habt bewiesen, dass Ihr als <class> Euch um die Sicherheit von Nordhain sorgt. Nun erhaltet Ihr die Aufgabe, Euch auch dem Schutz des umliegenden Waldes von Elwynn zu widmen.",
    ["you have served us well in the past, so I now entrust to you an important mission. The Grimtotem Clan is up to something secretive. Three agents of unknown origin were seen visiting the Grimtotem over the recent weeks."] = "<name>, Ihr habt uns in der Vergangenheit gut gedient, sodass ich Euch jetzt eine wichtige Mission anvertraue. Der Grimmtotemklan plant etwas, das niemand wissen soll. Drei Agenten unbekannter Herkunft wurden gesehen, wie sie die Grimmtotem in den vergangenen Wochen besuchten.",
    ["you helped us against the Magram. Now, help us beat the Maraudine! Kill the head of their clan, Khan Hratha! To face him, blow the Maraudine War Horn."] = "<name>, Ihr habt uns gegen die Magram geholfen. Jetzt helft uns dabei, die Maraudine zu schlagen! Tötet den Anführer ihres Klans, Khan Hratha! Um ihn herauszufordern, blast das Kriegshorn der Maraudine.",
    ["your help has been immeasurable. The time will come, no doubt, when I'll ask for your assistance against the silithid once more."] = "<name>, Eure Hilfe war wirklich unschätzbar wertvoll. Es wird zweifellos der Moment kommen, an dem ich erneut um Euren Beistand im Kampf gegen die Silithiden bitten muss.",
    ["your services to the Warlords surpassed all we could expect from the denizens of this world. We do not understand your people's notions of gratitude, or rewarding good works, but in this case..."] = "<name>, Euer Dienst für die Kriegsherrn hat alles übertroffen, was wir je von den Einwohnern dieser Welt erwartet haben. Wir kennen zwar nicht die Vorstellung Eures Volkes, von Dankbarkeit oder wie Ihr gute Arbeit bei Euch belohnt, aber in diesem Fall...ist eine Belohnung mehr als angebracht.",
}) do text[k] = v end

local objectives = GQ.LocaleObjectives
for k, v in pairs({
    ["According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.Should Korrak make himself known, destroy him and return to Warmaster Laggrond."] = "Tief in den Winteraxhöhlen versteckt sich Korrak der Blutrünstige. Den Legenden nach, wird der mächtige Anführer der Winteraxtrolle nur erscheinen, wenn 500 seiner Männer getötet wurden.  Begebt Euch zu den Winteraxhöhlen und vernichtet alles was sich Euch in den Weg stellt, solange bis Korrak selbst auftaucht. Tötet Korrak und kehrt zu Kriegsmeister Laggrond zurück.",
    ["Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Lightforge Bracers to Deliana in Ironforge."] = "Sammelt 15 Blutproben aus Winterspring und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Lichts zu Deliana in Ironforge.",
    ["Acquire 6 Bloodfeather Belts and bring them to Sentinel Arynia Cloudsbreak in the Oracle Glade."] = "Beschafft 6 Blutfedergürtel und bringt sie der Schildwache Arynia Cloudsbreak in der Lichtung des Orakels.",
    ["Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him."] = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.",
    ["Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager."] = "Andi Lynn in Gadgetzan möchte, dass Ihr das Truppenlager der Dünenbrecher vernichtet, indem Ihr 10 Schläger der Dünenbrecher 10 Vollstrecker der Dünenbrecher sowie Gor'marok den Verheerer tötet.",
    ["Apothecary Johaan in the town of Brill wants you to collect 5 Vials of Darkhound Blood."] = "Apotheker Johaan in der Stadt Brill möchte, dass Ihr 5 Phiolen Schattenhundblut sammelt.",
    ["Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom."] = "Die Apothekerin Zamah in Thunder Bluff möchte, dass Ihr zehn Schlangenflaum für sie sammelt.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make Frostfire Bindings if you bring her the following: 1 Desecrated Bindings, 6 Wartorn Cloth Scraps, 1 Arcane Crystal and 1 Nexus Crystal."] = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Frostfeuerbindungen anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 Paar entweihte Bindungen, 6 kampfzerschlissene Stoffstücke, 1 Arkankristall und 1 Nexuskristall.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make Frostfire Gloves if you bring her the following: 1 Desecrated Gloves, 8 Wartorn Cloth Scraps and 4 Mooncloth."] = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Frostfeuerhandschuhe anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 Paar entweihte Handschuhe, 8 kampfzerschlissene Stoffstücke und 4 Einheiten Mondstoff.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make Frostfire Leggings if you bring her the following: 1 Desecrated Leggings, 20 Wartorn Cloth Scraps, 4 Mooncloth and 2 Nexus Crystals."] = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Frostfeuergamaschen anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 Paar entweihte Gamaschen, 20 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make Frostfire Sandals if you bring her the following: 1 Desecrated Sandals, 12 Wartorn Cloth Scraps, 2 Mooncloth and 3 Cured Rugged Hides."] = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Frostfeuersandalen anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 Paar entweihte Sandalen, 12 kampfzerschlissene Stoffstücke, 2 Einheiten Mondstoff und 3 geschmeidige unverwüstliche Bälge.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make Frostfire Shoulderpads if you bring her the following: 1 Desecrated Shoulderpads, 12 Wartorn Cloth Scraps, 2 Mooncloth and 3 Cured Rugged Hides."] = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch Frostfeuerschulterpolster anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 Paar entweihte Schulterpolster, 12 kampfzerschlissene Stoffstücke, 2 Einheiten Mondstoff und 3 geschmeidige unverwüstliche Bälge.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make a Frostfire Belt if you bring her the following: 1 Desecrated Belt, 8 Wartorn Cloth Scraps, 2 Arcane Crystals and 2 Mooncloth."] = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Frostfeuergürtel anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 entweihten Gürtel, 8 kampfzerschlissene Stoffstücke, 2 Arkankristalle und 2 Einheiten Mondstoff.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make a Frostfire Circlet if you bring her the following: 1 Desecrated Circlet, 15 Wartorn Cloth Scraps, 3 Mooncloth and 3 Nexus Crystals."] = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch einen Frostfeuerreif anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 entweihten Reif, 15 kampfzerschlissene Stoffstücke, 3 Einheiten Mondstoff und 3 Nexuskristalle.",
    ["Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make a Frostfire Robe if you bring her the following: 1 Desecrated Robe, 25 Wartorn Cloth Scraps, 4 Mooncloth and 2 Nexus Crystals."] = "Erzmagierin Angela Dosantos bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern wird für Euch eine Frostfeuerrobe anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 entweihte Robe, 25 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.",
    ["Balir Frosthammer wants you to kill 6 Rockjaw Troggs and 6 Burly Rockjaw Troggs."] = "Balir Frosthammer möchte, dass Ihr 6 Troggs der Felsenkiefer und 6 bullige Troggs der Felsenkiefer tötet.",
    ["Banish 6 Portals at Mannoroc Coven and return to Taiga Wisemane at Shadowprey Village."] = "Verbannt 6 Portale in Mannorocs Koven und kehrt dann zu Taiga Wisemane nach Shadowprey zurück.",
    ["Barkeep Daniels of Lakeshire needs a keg of Thunderbrew Lager, a cask of Merlot, a bottle of Moonshine and a skin of Sweet Rum."] = "Barkeeper Daniels aus Seenhain braucht ein Fässchen Donnerbräu Lagerbier, ein Fässlein Merlot, eine Flasche Fusel und einen Schlauch mit süßem Rum.",
    ["Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Darnassus is the next step the tauren druid sought. Seek one of the druids there for assistance."] = "Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Darnassus bringt. Bittet einen der Druiden dort um Hilfe.",
    ["Bring 1 Qiraji Ceremonial Ring, 2 Amber Idols, 5 Gold Scarabs and 5 Clay Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Gebieterring der Qiraji, 2 Bernsteingötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Ceremonial Ring, 2 Jasper Idols, 5 Stone Scarabs and 5 Crystal Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Zeremonienring der Qiraji, 2 Jaspisgötzen, 5 Steinskarabäen und 5 Kristallskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Ceremonial Ring, 2 Obsidian Idols, 5 Silver Scarabs and 5 Bone Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Zeremonienring der Qiraji, 2 Obsidiangötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Ceremonial Ring, 2 Onyx Idols, 5 Stone Scarabs and 5 Crystal Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Zeremonienring der Qiraji, 2 Onyxgötzen, 5 Steinskarabäen und 5 Kristallskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Magisterial Ring, 2 Alabaster Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Gebieterring der Qiraji, 2 Alabastergötzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Magisterial Ring, 2 Azure Idols, 5 Gold Scarabs and 5 Clay Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Gebieterring der Qiraji, 2 Azurgötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Magisterial Ring, 2 Lambent Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Gebieterring der Qiraji, 2 züngelnde Götzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Magisterial Ring, 2 Vermillion Idols, 5 Silver Scarabs and 5 Bone Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Gebieterring der Qiraji, 2 Zinnobergötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Martial Drape, 2 Alabaster Idols, 5 Stone Scarabs and 5 Crystal Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Kampftuch der Qiraji, 2 Alabastergötzen, 5 Steinskarabäen und 5 Kristallskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Martial Drape, 2 Azure Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Kampftuch der Qiraji, 2 Azurgötzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Martial Drape, 2 Jasper Idols, 5 Gold Scarabs and 5 Clay Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Kampftuch der Qiraji, 2 Jaspisgötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Martial Drape, 2 Onyx Idols, 5 Silver Scarabs and 5 Bone Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Kampftuch der Qiraji, 2 Onyxgötzen, 5 Sillberskarabäen und 5 Knochenskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Ornate Hilt, 2 Jasper Idols, 5 Crystal Scarabs and 5 Stone Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest."] = "Bringt 1 verschnörkelten Griff der Qiraji, 2 Jaspisgötzen, 5 Kristallskarabäen und 5 Steinskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Ornate Hilt, 2 Obsidian Idols, 5 Silver Scarabs and 5 Bone Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest."] = "Bringt 1 verschnörkelten Griff der Qiraji, 2 Obsidiangötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Regal Drape, 2 Lambent Idols, 5 Stone Scarabs and 5 Crystal Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Hoheitstuch der Qiraji, 2 züngelnde Götzen, 5 Steinskarabäen und 5 Kristallskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Regal Drape, 2 Obsidian Idols, 5 Clay Scarabs and 5 Gold Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Hoheitstuch der Qiraji, 2 Obsidiangötzen, 5 Tonskarabäen und 5 Goldskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Regal Drape, 2 Obsidian Idols, 5 Gold Scarabs and 5 Clay Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Hoheitstuch der Qiraji, 2 Obsidiangötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Regal Drape, 2 Vermillion Idols, 5 Silver Scarabs and 5 Bone Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Hoheitstuch der Qiraji, 2 Zinnobergötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Spiked Hilt, 2 Amber Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Stachelgriff der Qiraji, 2 Bernsteingötzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.",
    ["Bring 1 Qiraji Spiked Hilt, 2 Azure Idols, 5 Silver Scarabs and 5 Bone Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest."] = "Bringt 1 Stachelgriff der Qiraji, 2 Azurgötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.",
    ["Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.Kill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn."] = "Bringt 10 gegrillte Bussardflügel und 5 Flaschen Dschungelrankenwein zu Käpt'n Smotts Rettungsboot.  Tötet Negolash und bringt Smotts' Entersäbel zu Captain Smotts ins Schlingendorntal.",
    ["Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay."] = "Bringt 10 Stängel Akirisschilfrohr zu Freibeuter Bloads nach Booty Bay.",
    ["Bring 10 Filled Pure Sample Jars to Laris Geardawdle in Ironforge.If you have trouble finding them, perhaps try to get more clues from Laris."] = "Bringt 10 mit reinen Proben gefüllte Krüge zu Laris Geardawdle in Ironforge.  Falls Ihr Probleme habt, fündig zu werden, dann kann Laris Euch vielleicht noch den einen oder anderen Hinweis geben.",
    ["Bring 10 Highperch Venom Sacs to Fiora Longears in Theramore."] = "Bringt 10 Steilhanggiftbeutel zu Fiora Longears in Theramore.",
    ["Bring 10 Monstrous Crawler Legs to Dar in the Swamp of Sorrows."] = "Bringt 10 monströse Kriecherbeine zu Dar in den Sümpfen des Elends.",
    ["Bring 10 Morrowgrain to Quintis Jonespyre in Feathermoon Stronghold."] = "Bringt 10 Einheiten Morgenkorn zu Quintis Jonespyre in der Festung Feathermoon.",
    ["Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas."] = "Bringt Pratt McGrubben in der Festung Feathermoon 10 Wutschrammyetibälge.",
    ["Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill."] = "Bringt Todeswache Burgess in Brill 10 scharlachrote Insignienringe.",
    ["Bring 10 Singing Blue Crystals to Crank Fizzlebub in Booty Bay."] = "Bringt 10 singende blaue Kristalle zu Crank Fizzlebub nach Booty Bay.",
    ["Bring 10 Thick Yeti Hides to Jangdor Swiftstrider in Camp Mojache."] = "Bringt Jangdor Swiftstrider im Camp Mojache 10 dicke Yetibälge.",
    ["Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus."] = "Bringt 10 Twilight-Anhänger zu Argentumwache Manados in Darnassus",
    ["Bring 10 Webwood Venom Sacs to Gilshalan Windwalker at Aldrassil."] = "Bringt Gilshalan Windwalker in Aldrassil 10 Waldwebergiftbeutel.",
    ["Bring 10 vials of Mountain Lion Blood to Apothecary Lydon in Tarren Mill."] = "Bringt 10 Phiolen mit Berglöwenblut zu Apotheker Lydon in Tarrens Mühle.",
    ["Bring 12 Red Burlap Bandanas to Deputy Willem outside the Northshire Abbey."] = "Bringt 12 rote Sackleinenkopftücher zu Deputy Willem in der Nähe der Abtei von Nordhain.",
    ["Bring 12 Silithid Eggs and the Digging Claw to Korran at the Crossroads."] = "Bringt Korran in Crossroads 12 Silithideneier und die Grabgabel.",
    ["Bring 12 Timberling Sprouts to Denalan at Lake Al'Ameth."] = "Bringt Denalan am Al'Amethsee 12 Bäumlingssprossen.",
    ["Bring 12 Tunnel Rat Ears to Mountaineer Kadrell in Thelsamar."] = "Bringt Gebirgsjäger Kadrell in Thelsamar 12 Tunnelrattenohren.",
    ["Bring 12 pieces of Light Leather to Veren Tallstrider in Thunder Bluff."] = "Bringt Veren Tallstrider in Thunder Bluff 12 Stücke leichtes Leder.",
    ["Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay."] = "Bringt 12 Proben von Zanzils Mixtur zu Crank Fizzlebub nach Booty Bay.",
    ["Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 17 Cenarion Tactical Badges and 1 Mark of Remulos to Vargus at Cenarion Hold in Silithus. You must also attain Revered reputation with Cenarion Circle to be able to complete this quest."] = "Bringt 15 cenarische Gefechtsabzeichen, 20 cenarische Versorgungsabzeichen, 17 cenarische Strategieabzeichen und 1 Mal von Remulos zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.",
    ["Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 20 Cenarion Tactical Badges and 1 Mark of Cenarius to Vargus at Cenarion Hold in Silithus. You must also attain Exalted reputation with Cenarion Circle to be able to complete this quest."] = "Bringt 15 cenarische Gefechtsabzeichen, 20 cenarische Versorgungsabzeichen, 20 cenarische Strategieabzeichen und 1 Mal des Cenarius zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.",
    ["Bring 15 Centaur Bracers to Regthar Deathgate, west of the Crossroads."] = "Bringt Regthar Deathgate westlich von Crossroads 15 Zentaurenarmschienen.",
